import subprocess, re
def probe(s):
    p = subprocess.run(["/workspace/executable","-n","--expression",s], input=b"5", capture_output=True)
    return (p.stdout+p.stderr).decode()
def lexOk(joined):
    return "lexer: invalid input text" not in probe(joined)
def scanChunk(cands):
    """cands: list of short candidates (<20 chars). Return set of bad indexes."""
    bad=set()
    while True:
        cur=[cands[i] for i in range(len(cands)) if i not in bad]
        if not cur: return bad
        joined="|".join(cur)
        out=probe(joined)
        if "lexer: invalid input text" not in out: return bad
        col=int(re.search(r'Error: 1:(\d+): lexer', out).group(1)); off=col-1
        pos=0; idx=None
        for i,c in enumerate(cur):
            if off==pos or pos<off<pos+len(c): idx=i; break
            pos+=len(c)+1
        if idx is None: return bad
        cnt=0
        for i in range(len(cands)):
            if i in bad: continue
            if cnt==idx: bad.add(i); break
            cnt+=1
def scanAll(cands, chunk=15):
    bad=set()
    for i in range(0,len(cands),chunk):
        bad |= {i+j for j in scanChunk(cands[i:i+chunk])}
    return bad
