	if n == nil {
		return nil
	}
	clone := *n
	clone.Parent = nil
	clone.Key = nil
	clone.Document = nil
	clone.Content = make([]*CandidateNode, len(n.Content))
	for i, c := range n.Content {
		clone.Content[i] = c.Copy()
	}
	if n.Alias != nil {
		clone.Alias = n.Alias
	}
	for _, c := range clone.Content {
		c.Parent = &clone
	}
	return &clone
}

// deep copy preserving parents for children only (not recursing)
func (n *CandidateNode) ShallowCopy() *CandidateNode {
	if n == nil {
		return nil
	}
	clone := *n
	clone.Content = nil
	return &clone
}

func (n *CandidateNode) GetKind() Kind { return n.Kind }

func (n *CandidateNode) GetPath() []interface{} {
	if n == nil {
		return []interface{}{}
	}
	var path []interface{}
	cur := n
	for cur != nil && cur.Parent != nil {
		if cur.Key != nil {
			switch cur.Key.Tag {
			case "!!int":
				i, err := parseStrictInt(cur.Key.Value)
				if err == nil {
					path = append([]interface{}{i}, path...)
				} else {
					path = append([]interface{}{cur.Key.Value}, path...)
				}
			default:
				path = append([]interface{}{cur.Key.Value}, path...)
			}
		}
		cur = cur.Parent
	}
	if path == nil {
		path = []interface{}{}
	}
	return path
}

