		}
		j++
	}
	if j == len(s) {
		return 0, errBadInt
	}
	for ; j < len(s); j++ {
		if s[j] < '0' || s[j] > '9' {
			return 0, errBadInt
		}
		i = i*10 + int(s[j]-'0')
	}
	if neg {
		i = -i
	}
	return i, nil
}

