func (n *CandidateNode) GetValue() string {
	if n == nil {
		return ""
	}
	return n.Value
}

func (n *CandidateNode) GetKey() string {
	if n == nil || n.Key == nil {
		return ""
	}
	return n.Key.Value
}

func (n *CandidateNode) AsList() []*CandidateNode {
	return []*CandidateNode{n}
}

func (n *CandidateNode) IsZero() bool {
	return n == nil
}

// NewScalar creates a scalar node
func NewScalar(tag string, value string, style Style) *CandidateNode {
	return &CandidateNode{Kind: ScalarNode, Tag: tag, Value: value, Style: style}
}

func NewSeq(tag string) *CandidateNode {
	return &CandidateNode{Kind: SequenceNode, Tag: tag, Style: ZeroStyle}
}

func NewMap(tag string) *CandidateNode {
	return &CandidateNode{Kind: MappingNode, Tag: tag, Style: ZeroStyle}
}

func EmptyNode() *CandidateNode {
	n := NewScalar("!!null", "null", ZeroStyle)
	n.nonEmpty = true
	return n
}

func (n *CandidateNode) CreateChild(parent *CandidateNode, key *CandidateNode, value *CandidateNode) *CandidateNode {
	value.Key = key
	value.Parent = parent
	return value
}

func (n *CandidateNode) AddChild(key *CandidateNode, value *CandidateNode) {
	value.Key = key
	value.Parent = n
	n.Content = append(n.Content, value)
}

func (n *CandidateNode) Len() int {
	if n == nil {
		return 0
	}
	return len(n.Content)
}

func (n *CandidateNode) GetContent() []*CandidateNode {
	if n == nil {
		return nil
	}
	return n.Content
}

func (n *CandidateNode) SetContent(c []*CandidateNode) {
	n.Content = c
	for _, child := range c {
		child.Parent = n
	}
}

func (n *CandidateNode) GuessTagFromType() string {
	switch n.Kind {
	case ScalarNode:
		return "!!str"
	case SequenceNode:
		return "!!seq"
	case MappingNode:
		return "!!map"
	}
	return ""
}
