cd /workspace && cat > pkg/yqlib/yamlparse.go <<'EOF'
package yqlib

import (
	"errors"
	"fmt"
	"strings"
)

type yamlParser struct {
	data          []byte
	pos           int
	line          int
	col           int
	anchors       map[string]*CandidateNode
	comments      []string
	pendingHead   []string
	lastFoot      string
	lastLine      string
	lineComment   string
	headComment   string
	footComment   string
	docIndex      int
	// state
}

type yamlError struct{ msg string }

func (e *yamlError) Error() string { return e.msg }

func yamlErr(msg string) error { return &yamlError{msg: msg} }

// ParseYAML parses a single yaml document, returns list of documents
func ParseYAML(data []byte, filename string, format string) ([]*CandidateNode, error) {
	p := &yamlParser{data: data, anchors: map[string]*CandidateNode{}}
	p.line = 1
	p.col = 1
	docs, err := p.parseDocuments()
	if err != nil {
		return nil, err
	}
	for _, d := range docs {
		setParents(d, nil, filename, format)
	}
	return docs, nil
}

func setParents(n *CandidateNode, parent *CandidateNode, filename string, format string) {
	if n == nil {
		return
	}
	n.Parent = parent
	n.filename = filename
	n.format = format
	for _, c := range n.Content {
		setParents(c, n, filename, format)
	}
	if n.Alias != nil {
		setParents(n.Alias, nil, "", format)
	}
}

func (p *yamlParser) atEOF() bool { return p.pos >= len(p.data) }

func (p *yamlParser) peek() byte {
	if p.atEOF() {
		return 0
	}
	return p.data[p.pos]
}

func (p *yamlParser) advance() byte {
	c := p.data[p.pos]
	p.pos++
	if c == '\n' {
		p.line++
		p.col = 1
	} else {
		p.col++
	}
	return c
}

func (p *yamlParser) skipSpaces() {
	for !p.atEOF() {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.advance()
		} else {
			break
		}
	}
}

// consumeRestOfLine advances to the next line
func (p *yamlParser) skipToEOL() {
	for !p.atEOF() && p.peek() != '\n' {
		p.advance()
	}
	if !p.atEOF() {
		p.advance()
	}
}

func (p *yamlParser) atLineStart() bool {
	return p.col == 1
}

// read a comment line starting with '#'
func (p *yamlParser) readComment() string {
	start := p.pos
	for !p.atEOF() && p.peek() != '\n' {
		p.advance()
	}
	text := string(p.data[start:p.pos])
	if !p.atEOF() {
		p.advance()
	}
	return strings.TrimRight(text, " \t\r")
}

func (p *yamlParser) commentText(c string) string {
	// c includes leading '#'
	c = strings.TrimPrefix(c, "#")
	// yaml spec: comments start with '#' followed by space or EOL; go-yaml keeps single space after '#'
	if len(c) > 0 && (c[0] == ' ' || c[0] == '\t') {
		return c[1:]
	}
	return c
}

func (p *yamlParser) parseDocuments() ([]*CandidateNode, error) {
	var docs []*CandidateNode
	for {
		// skip blank lines / comments at doc level, accumulating head comments
		var head []string
		for !p.atEOF() {
			p.skipSpaces()
			if p.atEOF() {
				break
			}
			c := p.peek()
			if c == '\n' {
				p.advance()
				// blank line: end pending comment block? go-yaml keeps them as foot comments
				continue
			}
			if c == '#' {
				head = append(head, p.readComment())
				continue
			}
			if c == '%' {
				// directive
				p.skipToEOL()
				continue
			}
			if p.isDocSeparator() {
				if len(docs) == 0 && len(head) == 0 {
					// leading separator - skip
					p.consumeSeparator()
					continue
				}
				break
			}
			break
		}
		if p.atEOF() && len(docs) > 0 && len(head) == 0 {
			break
		}
		if p.atEOF() && len(docs) == 0 && len(head) == 0 {
			break
		}
		if p.atEOF() && len(docs) == 0 && len(head) > 0 {
			// document with only comments
			d := &CandidateNode{Kind: MappingNode, Tag: "!!map"}
			d.HeadComment = joinComments(head)
			docs = append(docs, d)
			break
		}
		if p.isDocSeparator() && len(docs) > 0 {
			// trailing separator: empty document
			docs = append(docs, nil)
			p.consumeSeparator()
			continue
		}
		if p.isDocSeparator() && len(docs) == 0 && len(head) > 0 {
			p.consumeSeparator()
			continue
		}
		node, err := p.parseNode(0)
		if err != nil {
			return nil, err
		}
		if len(head) > 0 {
			node.HeadComment = joinComments(head)
		}
		foot := p.readTrailingComments()
		if foot != "" {
			node.FootComment = foot
		}
		if node == nil {
			node = &CandidateNode{Kind: MappingNode, Tag: "!!map"}
		}
		docs = append(docs, node)
		// check for next separator
		if p.atEOF() {
			break
		}
		p.skipSpaces()
		if p.atEOF() {
			break
		}
		if p.isDocSeparator() {
			p.consumeSeparator()
			continue
		}
		return nil, yamlErr(fmt.Sprintf("yaml: line %d: could not find expected ':'", p.line))
	}
	if len(docs) == 0 {
		return docs, nil
	}
	// go-yaml style: a nil document means empty
	return docs, nil
}

func joinComments(comments []string) string {
	var sb strings.Builder
	for i, c := range comments {
		if i > 0 {
			sb.WriteString("\n")
		}
		sb.WriteString(commentText(c))
	}
	return sb.String()
}

func (p *yamlParser) isDocSeparator() bool {
	if p.col != 1 {
		return false
	}
	// check for '---' or '...' possibly followed by stuff
	if p.pos+3 <= len(p.data) {
		s := p.data[p.pos : p.pos+3]
		if string(s) == "---" || string(s) == "..." {
			rest := ""
			if p.pos+3 < len(p.data) {
				rest = string(p.data[p.pos+3 : p.pos+4])
			}
			if rest == "" || rest == " " || rest == "\n" || rest == "\t" || rest == "\r" {
				return true
			}
		}
	}
	return false
}

func (p *yamlParser) consumeSeparator() {
	// consume the --- or ... line
	for !p.atEOF() && p.peek() != '\n' {
		p.advance()
	}
	if !p.atEOF() {
		p.advance()
	}
}

// readTrailingComments reads comments and blank lines at the end of a document
func (p *yamlParser) readTrailingComments() string {
	var comments []string
	var pendingBlanks int
	for !p.atEOF() {
		save := p.pos
		saveLine := p.line
		saveCol := p.col
		p.skipSpaces()
		if p.atEOF() {
			break
		}
		c := p.peek()
		if c == '\n' {
			p.advance()
			pendingBlanks++
			continue
		}
		if c == '#' {
			for i := 0; i < pendingBlanks; i++ {
				comments = append(comments, "")
			}
			pendingBlanks = 0
			comments = append(comments, p.readComment())
			continue
		}
		if pendingBlanks > 0 {
			// rest of document has content: stop (blanks become foot comment of previous doc)
			comments = append(comments, strings.Repeat("", 0))
		}
		// rewind
		p.pos = save
		p.line = saveLine
		p.col = saveCol
		break
	}
	if p.atEOF() && len(comments) > 0 {
		return joinComments(comments)
	}
	if p.atEOF() {
		return joinComments(comments)
	}
	if len(comments) == 0 {
		return ""
	}
	return joinComments(comments)
}

func (p *yamlParser) parseNode(indent int) (*CandidateNode, error) {
	p.skipSpaces()
	if p.atEOF() {
		return nil, nil
	}
	c := p.peek()
	if c == '#' {
		return nil, nil
	}
	if p.isDocSeparator() {
		return nil, nil
	}
	// block sequence
	if c == '-' {
		// is it a sequence entry?
		next := byte(' ')
		if p.pos+1 < len(p.data) {
			next = p.data[p.pos+1]
		}
		if next == ' ' || next == '\n' || next == '\t' || next == '\r' || p.pos+1 == len(p.data) {
			return p.parseBlockSeq(indent)
		}
	}
	if c == '{' || c == '[' || c == '"' || c == '\'' {
		return p.parseFlowOrQuoted(indent)
	}
	if c == '*' {
		return p.parseAlias(indent)
	}
	if c == '!' {
		return p.parseTagged(indent)
	}
	if c == '&' {
		return p.parseAnchored(indent)
	}
	return p.parseBlockScalarOrMap(indent)
}

func (p *yamlParser) parseAlias(indent int) (*CandidateNode, error) {
	// '*name'
	p.advance() // *
	start := p.pos
	for !p.atEOF() {
		c := p.peek()
		if isWordChar(c) {
			p.advance()
		} else {
			break
		}
	}
	name := string(p.data[start:p.pos])
	node := &CandidateNode{Kind: AliasNode, Tag: "", Value: name}
	if a, ok := p.anchors[name]; ok {
		node.Alias = a
		node.Content = a.Content
	} else {
		return nil, yamlErr(fmt.Sprintf("yaml: unknown anchor '%s' referenced", name))
	}
	p.skipSpaces()
	if !p.atEOF() && p.peek() == '#' {
		node.LineComment = p.commentText(p.readComment())
	} else if !p.atEOF() && p.peek() == '\n' {
		p.advance()
	}
	return node, nil
}

func isWordChar(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '-'
}

func (p *yamlParser) parseAnchored(indent int) (*CandidateNode, error) {
	p.advance() // &
	start := p.pos
	for !p.atEOF() {
		c := p.peek()
		if isWordChar(c) {
			p.advance()
		} else {
			break
		}
	}
	name := string(p.data[start:p.pos])
	p.skipSpaces()
	var node *CandidateNode
	var err error
	if !p.atEOF() && (p.peek() == '\n' || p.peek() == '#') {
		// anchor on a block node
		if p.peek() == '#' {
			lineC := p.commentText(p.readComment())
			node, err = p.parseNode(indent)
			if err != nil {
				return nil, err
			}
			if node == nil {
				node = NewScalar("!!null", "null", ZeroStyle)
			}
			node.LineComment = lineC
		} else {
			p.advance()
			node, err = p.parseNode(indent)
			if err != nil {
				return nil, err
			}
			if node == nil {
				node = NewScalar("!!null", "null", ZeroStyle)
			}
		}
	} else {
		node, err = p.parseScalarValue(indent)
		if err != nil {
			return nil, err
		}
		p.skipSpaces()
		if !p.atEOF() && p.peek() == '#' {
			node.LineComment = p.commentText(p.readComment())
		} else if !p.atEOF() && p.peek() == '\n' {
			p.advance()
		}
	}
	node.Anchor = name
	p.anchors[name] = node
	return node, nil
}

func (p *yamlParser) parseTagged(indent int) (*CandidateNode, error) {
	start := p.pos
	// read tag
	for !p.atEOF() {
		c := p.peek()
		if isWordChar(c) || c == '!' || c == '/' || c == '.' || c == ',' {
			p.advance()
		} else {
			break
		}
	}
	tag := string(p.data[start:p.pos])
	p.skipSpaces()
	var node *CandidateNode
	var err error
	if !p.atEOF() && (p.peek() == '\n' || p.peek() == '#') {
		if p.peek() == '#' {
			lineC := p.commentText(p.readComment())
			node, err = p.parseNode(indent)
			if err != nil {
				return nil, err
			}
			if node == nil {
				node = NewScalar("!!null", "null", ZeroStyle)
			}
			node.LineComment = lineC
		} else {
			p.advance()
			node, err = p.parseNode(indent)
			if err != nil {
				return nil, err
			}
			if node == nil {
				node = NewScalar("!!null", "null", ZeroStyle)
			}
		}
	} else {
		node, err = p.parseScalarValue(indent)
		if err != nil {
			return nil, err
		}
		p.skipSpaces()
		if !p.atEOF() && p.peek() == '#' {
			node.LineComment = p.commentText(p.readComment())
		} else if !p.atEOF() && p.peek() == '\n' {
			p.advance()
		}
	}
	node.Tag = tag
	return node, nil
}

func (p *yamlParser) parseBlockSeq(indent int) (*CandidateNode, error) {
	seq := NewSeq("!!seq")
	for {
		// we are at '-'
		p.advance() // '-'
		p.skipSpaces()
		var child *CandidateNode
		var err error
		if !p.atEOF() && (p.peek() == '\n' || p.peek() == '#') {
			if p.peek() == '#' {
				lineC := p.commentText(p.readComment())
				child, err = p.parseNode(indent + 2)
				if err != nil {
					return nil, err
				}
				if child != nil {
					child.LineComment = lineC
				} else {
					child = NewScalar("!!null", "null", ZeroStyle)
				}
			} else {
				p.advance()
				child, err = p.parseNode(indent + 2)
				if err != nil {
					return nil, err
				}
				if child == nil {
					child = NewScalar("!!null", "null", ZeroStyle)
				}
			}
		} else {
			child, err = p.parseScalarValue(indent + 2)
			if err != nil {
				return nil, err
			}
			p.skipSpaces()
			if !p.atEOF() && p.peek() == '#' {
				child.LineComment = p.commentText(p.readComment())
			} else if !p.atEOF() && p.peek() == '\n' {
				p.advance()
			}
		}
		seq.Content = append(seq.Content, child)
		// continue sequence if next line has same or deeper indent starting with '-'
		if !p.contSeq(indent) {
			break
		}
	}
	return seq, nil
}

// contSeq checks whether the next content line continues a block sequence at given indent
func (p *yamlParser) contSeq(indent int) bool {
	save := p.pos
	saveLine := p.line
	saveCol := p.col
	for {
		if p.atEOF() {
			return false
		}
		// skip whitespace at current line end
		for !p.atEOF() && (p.peek() == ' ' || p.peek() == '\t' || p.peek() == '\r') {
			p.advance()
		}
		if p.atEOF() {
			return false
		}
		if p.peek() == '\n' {
			p.advance()
			continue
		}
		break
	}
	ok := false
	if p.col-1 == indent && p.peek() == '-' {
		next := byte(' ')
		if p.pos+1 < len(p.data) {
			next = p.data[p.pos+1]
		}
		if next == ' ' || next == '\n' || next == '\t' || p.pos+1 == len(p.data) {
			ok = true
		}
	}
	p.pos = save
	p.line = saveLine
	p.col = saveCol
	return ok
}

func (p *yamlParser) parseFlowOrQuoted(indent int) (*CandidateNode, error) {
	c := p.peek()
	switch c {
	case '{':
		return p.parseFlowMap(indent)
	case '[':
		return p.parseFlowSeq(indent)
	case '"':
		v, err := p.parseDoubleQuoted()
		if err != nil {
			return nil, err
		}
		n := NewScalar("!!str", v, DoubleQuotedStyle)
		p.afterScalar(n)
		return n, nil
	case '\'':
		v, err := p.parseSingleQuoted()
		if err != nil {
			return nil, err
		}
		n := NewScalar("!!str", v, SingleQuotedStyle)
		p.afterScalar(n)
		return n, nil
	}
	return nil, nil
}

func (p *yamlParser) afterScalar(n *CandidateNode) {
	p.skipSpaces()
	if !p.atEOF() && p.peek() == '#' {
		n.LineComment = p.commentText(p.readComment())
	} else if !p.atEOF() && p.peek() == '\n' {
		p.advance()
	}
}

func (p *yamlParser) parseDoubleQuoted() (string, error) {
	p.advance() // "
	var sb strings.Builder
	for {
		if p.atEOF() {
			return "", yamlErr(fmt.Sprintf("yaml: while scanning a quoted scalar at line %d, column %d: line %d, column %d: found unexpected end of stream", 1, 2, p.line, p.col))
		}
		c := p.peek()
		if c == '"' {
			p.advance()
			break
		}
		if c == '\\' {
			p.advance()
			if p.atEOF() {
				return "", yamlErr("yaml: while scanning a quoted scalar: found unexpected end of stream")
			}
			e := p.advance()
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '0':
				sb.WriteByte(0)
			case 'a':
				sb.WriteByte(7)
			case 'b':
				sb.WriteByte(8)
			case 'v':
				sb.WriteByte(11)
			case 'f':
				sb.WriteByte(12)
			case 'e':
				sb.WriteByte(27)
			case 'x':
				v := p.readHex(2)
				sb.WriteByte(byte(v))
			case 'u':
				v := p.readHex(4)
				sb.WriteRune(runei(v))
			case 'U':
				v := p.readHex(8)
				sb.WriteRune(runei(v))
			case 'N':
				sb.WriteString("\u0085")
			case '_':
				sb.WriteString("\u00A0")
			case 'L':
				sb.WriteString("\u2028")
			case 'P':
				sb.WriteString("\u2029")
			case ' ':
				sb.WriteByte(' ')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case '/':
				sb.WriteByte('/')
			case '\n':
				// line continuation
				for !p.atEOF() && (p.peek() == ' ' || p.peek() == '\t') {
					p.advance()
				}
			default:
				sb.WriteByte('\\')
				sb.WriteByte(e)
			}
			continue
		}
		p.advance()
		sb.WriteByte(c)
	}
	return sb.String(), nil
}

func runei(v int64) rune { return rune(v) }

func (p *yamlParser) readHex(n int) int64 {
	var v int64
	for i := 0; i < n && !p.atEOF(); i++ {
		c := p.advance()
		var d int64
		switch {
		case c >= '0' && c <= '9':
			d = int64(c - '0')
		case c >= 'a' && c <= 'f':
			d = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int64(c-'A') + 10
		default:
			return v
		}
		v = v*16 + d
	}
	return v
}

func (p *yamlParser) parseSingleQuoted() (string, error) {
	p.advance() // '
	var sb strings.Builder
	for {
		if p.atEOF() {
			return "", yamlErr("yaml: while scanning a quoted scalar: found unexpected end of stream")
		}
		c := p.peek()
		if c == '\'' {
			p.advance()
			if !p.atEOF() && p.peek() == '\'' {
				p.advance()
				sb.WriteByte('\'')
				continue
			}
			break
		}
		p.advance()
		sb.WriteByte(c)
	}
	return sb.String(), nil
}

func (p *yamlParser) parseScalarValue(indent int) (*CandidateNode, error) {
	c := p.peek()
	switch c {
	case '|', '>':
		return p.parseBlockScalar(indent)
	}
	// plain scalar up to end of line (or key separator)
	return p.parsePlainScalar(indent, false)
}

func (p *yamlParser) parseBlockScalar(indent int) (*CandidateNode, error) {
	literal := p.advance() == '|'
	// parse indicators
	chomp := byte(0)
	explicitIndent := 0
	for !p.atEOF() {
		c := p.peek()
		if c == '-' || c == '+' {
			chomp = c
			p.advance()
		} else if c >= '1' && c <= '9' {
			explicitIndent = int(c - '0')
			p.advance()
		} else {
			break
		}
	}
	var lines []string
	// skip to end of line
	for !p.atEOF() && p.peek() != '\n' {
		p.advance()
	}
	if !p.atEOF() {
		p.advance()
	}
	baseIndent := -1
	if explicitIndent > 0 {
		baseIndent = indent + explicitIndent
	}
	for {
		if p.atEOF() {
			break
		}
		save := p.pos
		saveLine := p.line
		saveCol := p.col
		ind := 0
		for !p.atEOF() && p.peek() == ' ' {
			p.advance()
			ind++
		}
		if p.atEOF() {
			// trailing empty line
			p.pos = save
			p.line = saveLine
			p.col = saveCol
			break
		}
		if p.peek() == '\n' {
			p.advance()
			lines = append(lines, "")
			continue
		}
		if ind <= indent {
			p.pos = save
			p.line = saveLine
			p.col = saveCol
			break
		}
		if baseIndent < 0 {
			baseIndent = ind
		}
		if ind < baseIndent {
			p.pos = save
			p.line = saveLine
			p.col = saveCol
			break
		}
		// extra indentation beyond baseIndent is preserved
		pad := ind - baseIndent
		start := p.pos
		for !p.atEOF() && p.peek() != '\n' {
			p.advance()
		}
		line := string(p.data[start:p.pos])
		line = strings.Repeat(" ", pad) + strings.TrimRight(line, " \t\r")
		lines = append(lines, line)
		if !p.atEOF() {
			p.advance()
		}
	}
	var sb strings.Builder
	if literal {
		for _, l := range lines {
			sb.WriteString(l)
			sb.WriteString("\n")
		}
	} else {
		// folded
		for i, l := range lines {
			if l == "" {
				sb.WriteString("\n")
				continue
			}
			if i > 0 {
				prev := lines[i-1]
				if prev == "" {
					sb.WriteString(l)
					continue
				}
				if l[0] == ' ' || prev[0] == ' ' {
					sb.WriteString("\n")
					sb.WriteString(l)
					continue
				}
				sb.WriteString(" ")
				sb.WriteString(l)
				continue
			}
			sb.WriteString(l)
		}
		sb.WriteString("\n")
	}
	val := sb.String()
	switch chomp {
	case '-':
		val = strings.TrimRight(val, "\n")
	case '+':
		// keep
	}
	style := LiteralStyle
	if !literal {
		style = FoldedStyle
	}
	n := NewScalar("!!str", val, style)
	// after block scalar, comments are line comments
	return n, nil
}

func (p *yamlParser) parsePlainScalar(indent int, isKey bool) (*CandidateNode, error) {
	start := p.pos
	startLine := p.line
	// scan plain scalar: stops at ": " or " #" or EOL; may continue on following more-indented lines
	first := true
	var parts []string
	for {
		s := p.pos
		// scan to EOL
		for !p.atEOF() {
			c := p.peek()
			if c == '\n' {
				break
			}
			if c == ':' {
				// check if followed by space or EOL
				if p.pos+1 >= len(p.data) || p.data[p.pos+1] == ' ' || p.data[p.pos+1] == '\n' || p.data[p.pos+1] == '\t' {
					break
				}
			}
			if c == '#' && p.pos > 0 && (p.data[p.pos-1] == ' ' || p.data[p.pos-1] == '\t') {
				break
			}
			p.advance()
		}
		text := string(p.data[s:p.pos])
		text = strings.TrimRight(text, " \t\r")
		parts = append(parts, text)
		if first {
			if len(text) > 0 && (text[0] == '{' || text[0] == '[') {
				// flow inside a plain scalar: handled elsewhere
			}
			first = false
		}
		// check for continuation
		save := p.pos
		saveLine := p.line
		saveCol := p.col
		if p.atEOF() {
			break
		}
		if p.peek() != '\n' {
			break
		}
		p.advance()
		ind := 0
		for !p.atEOF() && p.peek() == ' ' {
			p.advance()
			ind++
		}
		if p.atEOF() {
			p.pos = save
			p.line = saveLine
			p.col = saveCol
			break
		}
		if p.peek() == '\n' || p.peek() == '#' {
			p.pos = save
			p.line = saveLine
			p.col = saveCol
			break
		}
		if p.isDocSeparator() {
			p.pos = save
			p.line = saveLine
			p.col = saveCol
			break
		}
		if ind <= indent {
			p.pos = save
			p.line = saveLine
			p.col = saveCol
			break
		}
		// continuation line
		continue
	}
	val := strings.Join(parts, " ")
	// strip a trailing '#' comment if it was separated
	n := resolveScalar(val)
	p.skipSpaces()
	if !p.atEOF() && p.peek() == '#' {
		n.LineComment = p.commentText(p.readComment())
	} else if !p.atEOF() && p.peek() == '\n' {
		p.advance()
	}
	return n, nil
}

func resolveScalar(val string) *CandidateNode {
	style := ZeroStyle
	if val == "" {
		return &CandidateNode{Kind: ScalarNode, Tag: "!!null", Value: "", Style: style}
	}
	tag, value := guessTag(val)
	return &CandidateNode{Kind: ScalarNode, Tag: tag, Value: value, Style: style}
}

func guessTag(val string) (string, string) {
	switch val {
	case "null", "Null", "NULL", "~":
		return "!!null", val
	case "true", "True", "TRUE":
		return "!!bool", val
	case "false", "False", "FALSE":
		return "!!bool", val
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return "!!float", val
	case "-.inf", "-.Inf", "-.INF":
		return "!!float", val
	case ".nan", ".NaN", ".NAN":
		return "!!float", val
	}
	if isIntStr(val) {
		return "!!int", val
	}
	if isFloatStr(val) {
		return "!!float", val
	}
	return "!!str", val
}

func isIntStr(s string) bool {
	t := s
	if t[0] == '+' || t[0] == '-' {
		t = t[1:]
	}
	if t == "" {
		return false
	}
	// hex
	if strings.HasPrefix(t, "0x") || strings.HasPrefix(t, "0X") {
		t = t[2:]
		if t == "" {
			return false
		}
		for i := 0; i < len(t); i++ {
			if !isHexDigit(t[i]) {
				return false
			}
		}
		return true
	}
	if strings.HasPrefix(t, "0o") || strings.HasPrefix(t, "0O") {
		t = t[2:]
		if t == "" {
			return false
		}
		for i := 0; i < len(t); i++ {
			if t[i] < '0' || t[i] > '7' {
				return false
			}
		}
		return true
	}
	for i := 0; i < len(t); i++ {
		if t[i] < '0' || t[i] > '9' {
			return false
		}
	}
	return true
}

func isFloatStr(s string) bool {
	t := s
	if t[0] == '+' || t[0] == '-' {
		t = t[1:]
	}
	if t == "" {
		return false
	}
	if strings.HasSuffix(t, "e") || strings.HasSuffix(t, "E") {
		return false
	}
	// must contain . or e/E
	dots := strings.Count(t, ".")
	if dots > 1 {
		return false
	}
	if strings.Contains(t, ".") || strings.ContainsAny(t, "eE") {
		// validate
		i := 0
		for i < len(t) {
			c := t[i]
			if c >= '0' && c <= '9' || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
				i++
				continue
			}
			return false
		}
		return true
	}
	return false
}

func isHexDigit(c byte) bool {
	return c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F'
}

var errUnexpected = errors.New("unexpected")

func (p *yamlParser) parseFlowSeq(indent int) (*CandidateNode, error) {
	seq := NewSeq("!!seq")
	seq.Style = FlowStyle
	p.advance() // [
	for {
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow sequence: found unexpected end of stream")
		}
		if p.peek() == ']' {
			p.advance()
			break
		}
		n, err := p.parseFlowNode(indent)
		if err != nil {
			return nil, err
		}
		seq.Content = append(seq.Content, n)
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow sequence: found unexpected end of stream")
		}
		c := p.peek()
		if c == ',' {
			p.advance()
			continue
		}
		if c == ']' {
			p.advance()
			break
		}
		return nil, yamlErr("yaml: while parsing a flow sequence: did not find expected ',' or ']'")
	}
	return seq, nil
}

func (p *yamlParser) skipFlowWS() {
	for !p.atEOF() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.advance()
			continue
		}
		if c == '#' {
			// comment inside flow
			for !p.atEOF() && p.peek() != '\n' {
				p.advance()
			}
			continue
		}
		break
	}
}

func (p *yamlParser) parseFlowNode(indent int) (*CandidateNode, error) {
	c := p.peek()
	switch c {
	case '[':
		return p.parseFlowSeq(indent)
	case '{':
		return p.parseFlowMap(indent)
	case '"':
		v, err := p.parseDoubleQuoted()
		if err != nil {
			return nil, err
		}
		n := NewScalar("!!str", v, DoubleQuotedStyle)
		return n, nil
	case '\'':
		v, err := p.parseSingleQuoted()
		if err != nil {
			return nil, err
		}
		n := NewScalar("!!str", v, SingleQuotedStyle)
		return n, nil
	case '*':
		return p.parseAlias(indent)
	case '&':
		return p.parseAnchoredFlow(indent)
	case '!':
		return p.parseTaggedFlow(indent)
	}
	return p.parsePlainScalar(indent, false)
}

func (p *yamlParser) parseAnchoredFlow(indent int) (*CandidateNode, error) {
	p.advance() // &
	start := p.pos
	for !p.atEOF() {
		c := p.peek()
		if isWordChar(c) {
			p.advance()
		} else {
			break
		}
	}
	name := string(p.data[start:p.pos])
	p.skipFlowWS()
	var node *CandidateNode
	var err error
	if !p.atEOF() && (p.peek() == '\n' || p.peek() == '#') {
		p.skipFlowWS()
	}
	node, err = p.parseFlowNode(indent)
	if err != nil {
		return nil, err
	}
	node.Anchor = name
	p.anchors[name] = node
	return node, nil
}

func (p *yamlParser) parseTaggedFlow(indent int) (*CandidateNode, error) {
	start := p.pos
	for !p.atEOF() {
		c := p.peek()
		if isWordChar(c) || c == '!' || c == '/' || c == '.' || c == ',' {
			p.advance()
		} else {
			break
		}
	}
	tag := string(p.data[start:p.pos])
	p.skipFlowWS()
	node, err := p.parseFlowNode(indent)
	if err != nil {
		return nil, err
	}
	node.Tag = tag
	return node, nil
}

func (p *yamlParser) parseFlowMap(indent int) (*CandidateNode, error) {
	m := NewMap("!!map")
	m.Style = FlowStyle
	p.advance() // {
	for {
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow mapping: found unexpected end of stream")
		}
		if p.peek() == '}' {
			p.advance()
			break
		}
		var key *CandidateNode
		var err error
		// parse key
		c := p.peek()
		switch c {
		case '"':
			v, e := p.parseDoubleQuoted()
			if e != nil {
				return nil, e
			}
			key = NewScalar("!!str", v, DoubleQuotedStyle)
		case '\'':
			v, e := p.parseSingleQuoted()
			if e != nil {
				return nil, e
			}
			key = NewScalar("!!str", v, SingleQuotedStyle)
		case '?':
			p.advance()
			p.skipFlowWS()
			if !p.atEOF() && p.peek() == ':' {
				p.advance()
			}
			key = NewScalar("!!merge", "<<", ZeroStyle)
			val, e := p.parseFlowNode(indent)
			if e != nil {
				return nil, e
			}
			m.Content = append(m.Content, val)
			p.skipFlowWS()
			if !p.atEOF() && p.peek() == ',' {
				p.advance()
			}
			continue
		case '[':
			key, err = p.parseFlowSeq(indent)
		case '{':
			key, err = p.parseFlowMap(indent)
		case '*':
			key, err = p.parseAlias(indent)
		default:
			key, err = p.parsePlainScalar(indent, true)
		}
		if err != nil {
			return nil, err
		}
		if key == nil {
			key = NewScalar("!!null", "null", ZeroStyle)
		}
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow mapping: found unexpected end of stream")
		}
		if p.peek() != ':' {
			// key without value: null
			m.Content = append(m.Content, NewScalar("!!null", "null", ZeroStyle))
			continue
		}
		p.advance() // :
		p.skipFlowWS()
		val, err := p.parseFlowNode(indent)
		if err != nil {
			return nil, err
		}
		if val == nil {
			val = NewScalar("!!null", "null", ZeroStyle)
		}
		val.Key = key
		m.Content = append(m.Content, val)
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow mapping: found unexpected end of stream")
		}
		c = p.peek()
		if c == ',' {
			p.advance()
			continue
		}
		if c == '}' {
			p.advance()
			break
		}
		return nil, yamlErr("yaml: while parsing a flow mapping: did not find expected ',' or '}'")
	}
	return m, nil
}
