func (p *yamlParser) atEOF() bool { return p.pos >= len(p.data) }

func (p *yamlParser) peek() byte {
	if p.atEOF() {
		return 0
	}
	return p.data[p.pos]
}

func (p *yamlParser) advance() byte {
	c := p.data[p.pos]
	p.pos++
	if c == '\n' {
		p.line++
		p.col = 1
	} else {
		p.col++
	}
	return c
}

func (p *yamlParser) savePos() (int, int, int) { return p.pos, p.line, p.col }

func (p *yamlParser) restorePos(s int, l int, c int) {
	p.pos, p.line, p.col = s, l, c
}

func (p *yamlParser) skipSpaces() {
	for !p.atEOF() {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.advance()
		} else {
			break
		}
	}
}

func (p *yamlParser) skipToEOL() {
	for !p.atEOF() && p.peek() != '\n' {
		p.advance()
	}
	if !p.atEOF() {
		p.advance()
	}
}

func (p *yamlParser) readCommentText() string {
	start := p.pos
	for !p.atEOF() && p.peek() != '\n' {
		p.advance()
	}
	text := string(p.data[start:p.pos])
	if !p.atEOF() {
		p.advance()
	}
	return commentText(strings.TrimRight(text, " \t\r"))
}

func commentText(c string) string {
	if len(c) > 0 && (c[0] == ' ' || c[0] == '\t') {
		return c[1:]
	}
	return c
}

func joinComments(comments []string) string {
	var sb strings.Builder
	for i, c := range comments {
		if i > 0 {
			sb.WriteString("\n")
		}
		sb.WriteString(c)
	}
	return sb.String()
}

func isDocSep(s string) bool {
	return s == "---" || s == "..."
}

// consumeLeading: skips comments and blank lines, returning collected comments.
// Returns false if a document separator or content was found (position left at the content/separator).
func (p *yamlParser) consumeLeading() ([]string, bool, bool) {
	var head []string
	var blanks int
	for !p.atEOF() {
		p.skipSpaces()
		if p.atEOF() {
			return head, false, true
		}
		c := p.peek()
		if c == '\n' {
			p.advance()
			if len(head) > 0 {
