	p.anchors[name] = node
	return node, nil
}

func (p *yamlParser) parseTaggedKey(indent int) (*CandidateNode, error) {
	start := p.pos
	for !p.atEOF() {
		c := p.peek()
		if isWordChar(c) || c == '!' || c == '/' || c == '.' || c == ',' || c == '<' || c == '>' {
			p.advance()
		} else {
			break
		}
	}
	tag := string(p.data[start:p.pos])
	p.skipSpaces()
	if !p.atEOF() && p.peek() == ':' {
		key := NewScalar(tag, "", ZeroStyle)
		key.Tag = tag
		return key, nil
	}
	var node *CandidateNode
	var err error
	if p.atEOF() || p.peek() == '\n' {
		p.advance()
		node, err = p.parseBlockNode(indent)
		if err != nil {
			return nil, err
		}
		if node == nil {
			node = NewScalar("!!null", "null", ZeroStyle)
		}
	} else {
		node, err = p.parseValue(indent, true)
		if err != nil {
			return nil, err
		}
	}
	node.Tag = tag
	return node, nil
}

func (p *yamlParser) parseAlias() (*CandidateNode, error) {
	p.advance() // *
	start := p.pos
	for !p.atEOF() && isWordChar(p.peek()) {
		p.advance()
	}
	name := string(p.data[start:p.pos])
	node := &CandidateNode{Kind: AliasNode, Tag: "", Value: name}
	if a, ok := p.anchors[name]; ok {
		node.Alias = a
		node.Content = a.Content
	} else {
		return nil, yamlErr(fmt.Sprintf("yaml: unknown anchor '%s' referenced", name))
	}
	return node, nil
}

// parseBlockMap parses a block mapping; key is the first key already parsed.
func (p *yamlParser) parseBlockMap(indent int, firstKey *CandidateNode) (*CandidateNode, error) {
	m := NewMap("!!map")
	curKey := firstKey
	for {
		p.advance() // ':'
		p.skipSpaces()
		var val *CandidateNode
		var err error
		if p.atEOF() || p.peek() == '\n' || p.peek() == '#' {
			var lineC string
			if !p.atEOF() && p.peek() == '#' {
				lineC = p.readCommentText()
				// comment on same line as key: belongs to the key
				if curKey != nil {
					curKey.LineComment = lineC
				}
			} else {
				if !p.atEOF() {
					p.advance()
				}
			}
			// look ahead: nested content with deeper indent?
			sp, l, cl := p.savePos()
			ni, has := p.nextLineIndent()
			_ = ni
			if has && p.col-1 > indent && !isDocSep(p.peek3()) {
				val, err = p.parseBlockNode(p.col - 1)
				if err != nil {
					return nil, err
				}
				if val == nil {
					p.restorePos(sp, l, cl)
					val = NewScalar("!!null", "null", ZeroStyle)
				}
			} else {
				p.restorePos(sp, l, cl)
				val = NewScalar("!!null", "null", ZeroStyle)
			}
		} else {
			// value on same line
			nxtIndent := p.col - 1
			val, err = p.parseValue(nxtIndent, true)
			if err != nil {
				return nil, err
			}
			if val == nil {
				val = NewScalar("!!null", "null", ZeroStyle)
			}
		}
		val.Key = curKey
		val.Parent = m
		m.Content = append(m.Content, val)
		// find next key line
		sp, l, cl := p.savePos()
		if p.atEOF() {
			break
		}
		ni, has := p.nextLineIndent()
		if !has {
			break
		}
		if ni != indent {
			p.restorePos(sp, l, cl)
			break
		}
		// go to the content of the next line
		p.skipSpaces()
		if p.atEOF() || p.peek() == '\n' {
			p.restorePos(sp, l, cl)
			break
		}
		if isDocSep(p.peek3()) {
			p.restorePos(sp, l, cl)
			break
		}
		// comments? handled by caller
		k, isK, err := p.tryParseKey(indent)
		if err != nil {
			return nil, err
		}
		if !isK {
			p.restorePos(sp, l, cl)
			break
		}
		curKey = k
	}
	return m, nil
}

// parseBlockSeq parses a block sequence
func (p *yamlParser) parseBlockSeq(indent int) (*CandidateNode, error) {
	seq := NewSeq("!!seq")
	for {
		p.advance() // '-'
		p.skipSpaces()
		var child *CandidateNode
		var err error
		if p.atEOF() || p.peek() == '\n' || p.peek() == '#' {
			var lineC string
			if !p.atEOF() && p.peek() == '#' {
				lineC = p.readCommentText()
			} else if !p.atEOF() {
				p.advance()
			}
			sp, l, cl := p.savePos()
			ni, has := p.nextLineIndent()
			_ = ni
			if has && p.col-1 > indent && !isDocSep(p.peek3()) {
				child, err = p.parseBlockNode(p.col - 1)
				if err != nil {
					return nil, err
				}
				if child == nil {
					p.restorePos(sp, l, cl)
					child = NewScalar("!!null", "null", ZeroStyle)
				}
			} else {
				p.restorePos(sp, l, cl)
				child = NewScalar("!!null", "null", ZeroStyle)
			}
			if lineC != "" && child != nil {
				child.LineComment = lineC
			}
		} else {
			child, err = p.parseBlockNode(p.col - 1)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = NewScalar("!!null", "null", ZeroStyle)
			}
		}
		seq.Content = append(seq.Content, child)
		// next sequence entry?
		sp, l, cl := p.savePos()
		if p.atEOF() {
			break
		}
		ni, has := p.nextLineIndent()
		if !has {
			break
		}
		if ni != indent || p.peek() != '-' || !seqStart(p) {
			p.restorePos(sp, l, cl)
			break
		}
		// check for comments between entries: handled by caller loop
		// position at content
		p.skipSpaces()
		if p.atEOF() || p.peek() == '\n' || isDocSep(p.peek3()) {
			p.restorePos(sp, l, cl)
			break
		}
	}
	return seq, nil
}

// parseValue parses a value: scalar (possibly multi-line), flow, quoted, block scalar
func (p *yamlParser) parseValue(indent int, allowEmpty bool) (*CandidateNode, error) {
	if p.atEOF() || p.peek() == '\n' {
		if allowEmpty {
			return NewScalar("!!null", "null", ZeroStyle), nil
		}
		return nil, nil
	}
	c := p.peek()
	switch c {
	case '|', '>':
		return p.parseBlockScalar(indent)
	case '"':
		v, err := p.parseDoubleQuoted()
		if err != nil {
			return nil, err
		}
		n := NewScalar("!!str", v, DoubleQuotedStyle)
		p.afterScalar(n)
		return n, nil
	case '\'':
		v, err := p.parseSingleQuoted()
		if err != nil {
			return nil, err
		}
		n := NewScalar("!!str", v, SingleQuotedStyle)
		p.afterScalar(n)
		return n, nil
	case '{':
		n, err := p.parseFlowMap(indent)
		if err != nil {
			return nil, err
		}
		p.afterScalar(n)
		return n, nil
	case '[':
		n, err := p.parseFlowSeq(indent)
		if err != nil {
			return nil, err
		}
		p.afterScalar(n)
		return n, nil
	case '*':
		n, err := p.parseAlias()
		if err != nil {
			return nil, err
		}
		p.afterScalar(n)
		return n, nil
	case '&':
		return p.parseAnchoredValue(indent)
	case '!':
		return p.parseTaggedValue(indent)
	}
	return p.parsePlainValue(indent)
}

func (p *yamlParser) afterScalar(n *CandidateNode) {
	sp, l, c := p.savePos()
	p.skipSpaces()
	if !p.atEOF() && p.peek() == '#' {
		n.LineComment = p.readCommentText()
	} else if !p.atEOF() && p.peek() == '\n' {
		p.advance()
	} else {
		p.restorePos(sp, l, c)
	}
}

func (p *yamlParser) parseAnchoredValue(indent int) (*CandidateNode, error) {
	p.advance() // &
	start := p.pos
	for !p.atEOF() && isWordChar(p.peek()) {
		p.advance()
	}
	name := string(p.data[start:p.pos])
	p.skipSpaces()
	var node *CandidateNode
	var err error
	if p.atEOF() || p.peek() == '\n' || p.peek() == '#' {
		lineC := ""
		if !p.atEOF() && p.peek() == '#' {
			lineC = p.readCommentText()
		}
		if p.atEOF() {
			node = NewScalar("!!null", "null", ZeroStyle)
		} else {
			p.advance()
			node, err = p.parseBlockNode(indent)
			if err != nil {
				return nil, err
			}
			if node == nil {
				node = NewScalar("!!null", "null", ZeroStyle)
			}
		}
		if lineC != "" {
			node.LineComment = lineC
		}
	} else {
		node, err = p.parseValue(indent, true)
		if err != nil {
			return nil, err
		}
	}
	node.Anchor = name
	p.anchors[name] = node
	return node, nil
}

func (p *yamlParser) parseTaggedValue(indent int) (*CandidateNode, error) {
	start := p.pos
	for !p.atEOF() {
		c := p.peek()
		if isWordChar(c) || c == '!' || c == '/' || c == '.' || c == ',' || c == '<' || c == '>' {
			p.advance()
		} else {
			break
		}
	}
	tag := string(p.data[start:p.pos])
	p.skipSpaces()
	var node *CandidateNode
	var err error
	if p.atEOF() || p.peek() == '\n' || p.peek() == '#' {
		lineC := ""
		if !p.atEOF() && p.peek() == '#' {
			lineC = p.readCommentText()
		}
		if p.atEOF() {
			node = NewScalar("!!null", "null", ZeroStyle)
		} else {
			p.advance()
			node, err = p.parseBlockNode(indent)
			if err != nil {
				return nil, err
			}
			if node == nil {
				node = NewScalar("!!null", "null", ZeroStyle)
			}
		}
		if lineC != "" {
			node.LineComment = lineC
		}
	} else {
		node, err = p.parseValue(indent, true)
		if err != nil {
			return nil, err
		}
	}
	node.Tag = tag
	return node, nil
}

func (p *yamlParser) parseBlockScalar(indent int) (*CandidateNode, error) {
	literal := p.advance() == '|'
	chomp := byte(0)
	explicitIndent := 0
	for !p.atEOF() {
		c := p.peek()
		if c == '-' || c == '+' {
			chomp = c
			p.advance()
		} else if c >= '1' && c <= '9' {
			explicitIndent = int(c - '0')
			p.advance()
		} else {
			break
		}
	}
	for !p.atEOF() && p.peek() != '\n' {
		p.advance()
	}
	if !p.atEOF() {
		p.advance()
	}
	var lines []string
	var trailingBlanks int
	baseIndent := -1
	if explicitIndent > 0 {
		baseIndent = indent + explicitIndent
	}
	for {
		if p.atEOF() {
			break
		}
		sp, l, cl := p.savePos()
		ind := 0
		for !p.atEOF() && p.peek() == ' ' {
			p.advance()
			ind++
		}
		if p.atEOF() {
			p.restorePos(sp, l, cl)
			break
		}
		if p.peek() == '\n' {
			p.advance()
			lines = append(lines, "")
			continue
		}
		if ind <= indent || (baseIndent >= 0 && ind < baseIndent) {
			p.restorePos(sp, l, cl)
			break
		}
		if baseIndent < 0 {
			baseIndent = ind
		}
		pad := ind - baseIndent
		st := p.pos
		for !p.atEOF() && p.peek() != '\n' {
			p.advance()
		}
		line := string(p.data[st:p.pos])
		line = strings.Repeat(" ", pad) + strings.TrimRight(line, " \t\r")
		lines = append(lines, line)
		if !p.atEOF() {
			p.advance()
		}
	}
	// trim trailing blank lines per chomping
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailingBlanks++
	}
	var sb strings.Builder
	if literal {
		for _, l := range lines {
			sb.WriteString(l)
			sb.WriteString("\n")
		}
	} else {
		for i, l := range lines {
			if i == 0 {
				sb.WriteString(l)
				continue
			}
			prev := lines[i-1]
			if l == "" || prev == "" {
				sb.WriteString("\n")
				sb.WriteString(l)
				continue
			}
			if l[0] == ' ' || prev[0] == ' ' {
				sb.WriteString("\n")
				sb.WriteString(l)
				continue
			}
			sb.WriteString(" ")
			sb.WriteString(l)
		}
		sb.WriteString("\n")
	}
	val := sb.String()
	switch chomp {
	case '-':
		val = strings.TrimRight(val, "\n")
	case '+':
		val += strings.Repeat("\n", trailingBlanks)
	}
	style := LiteralStyle
	if !literal {
		style = FoldedStyle
	}
	n := NewScalar("!!str", val, style)
	if chomp == 0 {
		// clip
	}
	return n, nil
}

func (p *yamlParser) parsePlainKey(indent int) (*CandidateNode, error) {
	n, err := p.parsePlain(indent, true)
	if err != nil {
		return nil, err
	}
	return n, nil
}

func (p *yamlParser) parsePlainValue(indent int) (*CandidateNode, error) {
	n, err := p.parsePlain(indent, false)
	if err != nil {
		return nil, err
	}
	return n, nil
}

// parsePlain parses a plain scalar which may span multiple (more indented) lines
func (p *yamlParser) parsePlain(indent int, isKey bool) (*CandidateNode, error) {
	var parts []string
	first := true
	for {
		if p.atEOF() {
			break
		}
		st := p.pos
		for !p.atEOF() {
			c := p.peek()
			if c == '\n' {
				break
			}
			if c == ':' {
				if p.pos+1 >= len(p.data) || p.data[p.pos+1] == ' ' || p.data[p.pos+1] == '\n' || p.data[p.pos+1] == '\t' || p.data[p.pos+1] == '\r' {
					break
				}
			}
			if c == '#' && p.pos > 0 && (p.data[p.pos-1] == ' ' || p.data[p.pos-1] == '\t') {
				break
			}
			if c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
				if !isKey {
					break
				}
			}
			p.advance()
		}
		text := string(p.data[st:p.pos])
		text = strings.TrimRight(text, " \t\r")
		parts = append(parts, text)
		sp, l, cl := p.savePos()
		if p.atEOF() || p.peek() != '\n' {
			break
		}
		p.advance()
		ind := 0
		for !p.atEOF() && p.peek() == ' ' {
			p.advance()
			ind++
		}
		if p.atEOF() || p.peek() == '\n' || p.peek() == '#' || isDocSep(p.peek3()) {
			p.restorePos(sp, l, cl)
			break
		}
		if ind <= indent {
			p.restorePos(sp, l, cl)
			break
		}
	}
	val := strings.Join(parts, " ")
	n := resolveScalar(val)
	// trailing comment
	sp, l, c := p.savePos()
	p.skipSpaces()
	if !p.atEOF() && p.peek() == '#' {
		n.LineComment = p.readCommentText()
	} else if !p.atEOF() && p.peek() == '\n' {
		p.advance()
	} else {
		p.restorePos(sp, l, c)
	}
	return n, nil
}

func (p *yamlParser) parseFlowSeq(indent int) (*CandidateNode, error) {
	seq := NewSeq("!!seq")
	seq.Style = FlowStyle
	p.advance() // [
	for {
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow sequence: found unexpected end of stream")
		}
		if p.peek() == ']' {
			p.advance()
			break
		}
		n, err := p.parseFlowNode(indent)
		if err != nil {
			return nil, err
		}
		seq.Content = append(seq.Content, n)
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow sequence: found unexpected end of stream")
		}
		c := p.peek()
		if c == ',' {
			p.advance()
			continue
		}
		if c == ']' {
			p.advance()
			break
		}
		return nil, yamlErr(fmt.Sprintf("yaml: line %d: did not find expected ',' or ']'", p.line))
	}
	return seq, nil
}

func (p *yamlParser) skipFlowWS() {
	for !p.atEOF() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.advance()
			continue
		}
		if c == '#' {
			for !p.atEOF() && p.peek() != '\n' {
				p.advance()
			}
			continue
		}
		break
	}
}

func (p *yamlParser) parseFlowNode(indent int) (*CandidateNode, error) {
	if p.atEOF() {
		return NewScalar("!!null", "null", ZeroStyle), nil
	}
	c := p.peek()
	switch c {
	case '[':
		return p.parseFlowSeq(indent)
	case '{':
		return p.parseFlowMap(indent)
	case '"':
		v, err := p.parseDoubleQuoted()
		if err != nil {
			return nil, err
		}
		return NewScalar("!!str", v, DoubleQuotedStyle), nil
	case '\'':
		v, err := p.parseSingleQuoted()
		if err != nil {
			return nil, err
		}
		return NewScalar("!!str", v, SingleQuotedStyle), nil
	case '*':
		n, err := p.parseAlias()
		if err != nil {
			return nil, err
		}
		return n, nil
	case '&':
		n, err := p.parseAnchoredFlow(indent)
		if err != nil {
			return nil, err
		}
		return n, nil
	case '!':
		n, err := p.parseTaggedFlow(indent)
		if err != nil {
			return nil, err
		}
		return n, nil
	case ':':
		// empty key value
		return NewScalar("!!null", "null", ZeroStyle), nil
	}
	return p.parsePlain(indent, false)
}

func (p *yamlParser) parseAnchoredFlow(indent int) (*CandidateNode, error) {
	p.advance() // &
	start := p.pos
	for !p.atEOF() && isWordChar(p.peek()) {
		p.advance()
	}
	name := string(p.data[start:p.pos])
	p.skipFlowWS()
	node, err := p.parseFlowNode(indent)
	if err != nil {
		return nil, err
	}
	node.Anchor = name
	p.anchors[name] = node
	return node, nil
}

func (p *yamlParser) parseTaggedFlow(indent int) (*CandidateNode, error) {
	start := p.pos
	for !p.atEOF() {
		c := p.peek()
		if isWordChar(c) || c == '!' || c == '/' || c == '.' || c == ',' || c == '<' || c == '>' {
			p.advance()
		} else {
			break
		}
	}
	tag := string(p.data[start:p.pos])
	p.skipFlowWS()
	node, err := p.parseFlowNode(indent)
	if err != nil {
		return nil, err
	}
	node.Tag = tag
	return node, nil
}

func (p *yamlParser) parseFlowMap(indent int) (*CandidateNode, error) {
	m := NewMap("!!map")
	m.Style = FlowStyle
	p.advance() // {
	for {
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow mapping: found unexpected end of stream")
		}
		if p.peek() == '}' {
			p.advance()
			break
		}
		var key *CandidateNode
		var err error
		c := p.peek()
		if c == '?' {
			p.advance()
			p.skipFlowWS()
			if !p.atEOF() && p.peek() == ':' {
				p.advance()
			}
			val, e := p.parseFlowNode(indent)
			if e != nil {
				return nil, e
			}
			key = NewScalar("!!merge", "<<", ZeroStyle)
			val.Key = key
			m.Content = append(m.Content, val)
			p.skipFlowWS()
			if !p.atEOF() && p.peek() == ',' {
				p.advance()
			}
			continue
		}
		switch c {
		case '"':
			var v string
			v, err = p.parseDoubleQuoted()
			if err != nil {
				return nil, err
			}
			key = NewScalar("!!str", v, DoubleQuotedStyle)
		case '\'':
			var v string
			v, err = p.parseSingleQuoted()
			if err != nil {
				return nil, err
			}
			key = NewScalar("!!str", v, SingleQuotedStyle)
		case '[', '{':
			var n *CandidateNode
			if c == '[' {
				n, err = p.parseFlowSeq(indent)
			} else {
				n, err = p.parseFlowMap(indent)
			}
			if err != nil {
				return nil, err
			}
			// complex key
			p.skipFlowWS()
			if !p.atEOF() && p.peek() == ':' {
				p.advance()
				p.skipFlowWS()
				val, e := p.parseFlowNode(indent)
				if e != nil {
					return nil, e
				}
				val.Key = n
				m.Content = append(m.Content, val)
				p.skipFlowWS()
				if !p.atEOF() && p.peek() == ',' {
					p.advance()
				}
				continue
			}
			key = n
		case '*':
			key, err = p.parseAlias()
		case ':':
			// empty key
			p.advance()
			p.skipFlowWS()
			val, e := p.parseFlowNode(indent)
			if e != nil {
				return nil, e
			}
			val.Key = NewScalar("!!null", "null", ZeroStyle)
			m.Content = append(m.Content, val)
			p.skipFlowWS()
			if !p.atEOF() && p.peek() == ',' {
				p.advance()
			}
			continue
		default:
			key, err = p.parsePlain(indent, true)
		}
		if err != nil {
			return nil, err
		}
		if key == nil {
			key = NewScalar("!!null", "null", ZeroStyle)
		}
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow mapping: found unexpected end of stream")
		}
		if p.peek() == ':' {
			p.advance()
			p.skipFlowWS()
			val, err := p.parseFlowNode(indent)
			if err != nil {
				return nil, err
			}
			if val == nil {
				val = NewScalar("!!null", "null", ZeroStyle)
			}
			val.Key = key
			m.Content = append(m.Content, val)
		} else {
			val := NewScalar("!!null", "null", ZeroStyle)
			val.Key = key
			m.Content = append(m.Content, val)
		}
		p.skipFlowWS()
		if p.atEOF() {
			return nil, yamlErr("yaml: while parsing a flow mapping: found unexpected end of stream")
		}
		c = p.peek()
		if c == ',' {
			p.advance()
			continue
		}
		if c == '}' {
			p.advance()
			break
		}
		return nil, yamlErr(fmt.Sprintf("yaml: line %d: did not find expected ',' or '}'", p.line))
	}
	return m, nil
}

func (p *yamlParser) parseDoubleQuoted() (string, error) {
	p.advance() // "
	var sb strings.Builder
	for {
		if p.atEOF() {
			return "", yamlErr(fmt.Sprintf("yaml: while scanning a quoted scalar at line 1, column 5: line %d, column %d: found unexpected end of stream", p.line, p.col))
		}
		c := p.peek()
		if c == '"' {
			p.advance()
			break
		}
		if c == '\\' {
			p.advance()
			if p.atEOF() {
				return "", yamlErr("yaml: while scanning a quoted scalar: found unexpected end of stream")
			}
			e := p.advance()
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '0':
				sb.WriteByte(0)
			case 'a':
				sb.WriteByte(7)
			case 'b':
				sb.WriteByte(8)
			case 'v':
				sb.WriteByte(11)
			case 'f':
				sb.WriteByte(12)
			case 'e':
				sb.WriteByte(27)
			case 'x':
				sb.WriteByte(byte(p.readHex(2)))
			case 'u':
				sb.WriteRune(rune(p.readHex(4)))
			case 'U':
				sb.WriteRune(rune(p.readHex(8)))
			case 'N':
				sb.WriteString("\u0085")
			case '_':
				sb.WriteString("\u00A0")
			case 'L':
				sb.WriteString("\u2028")
			case 'P':
				sb.WriteString("\u2029")
			case '"', '\\', '/', '\'':
				sb.WriteByte(e)
			case ' ':
				sb.WriteByte(' ')
			case '\n':
				for !p.atEOF() && (p.peek() == ' ' || p.peek() == '\t') {
					p.advance()
				}
			default:
				sb.WriteByte('\\')
				sb.WriteByte(e)
			}
			continue
		}
		p.advance()
		sb.WriteByte(c)
	}
	return sb.String(), nil
}

func rune(v int64) rune { return rune(v) }

func (p *yamlParser) readHex(n int) int64 {
	var v int64
	for i := 0; i < n && !p.atEOF(); i++ {
		c := p.advance()
		var d int64
		switch {
		case c >= '0' && c <= '9':
			d = int64(c - '0')
		case c >= 'a' && c <= 'f':
			d = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int64(c-'A') + 10
		default:
			return v
		}
		v = v*16 + d
	}
	return v
}

func (p *yamlParser) parseSingleQuoted() (string, error) {
	p.advance() // '
	var sb strings.Builder
	for {
		if p.atEOF() {
			return "", yamlErr("yaml: while scanning a quoted scalar: found unexpected end of stream")
		}
		c := p.peek()
		if c == '\'' {
			p.advance()
			if !p.atEOF() && p.peek() == '\'' {
				p.advance()
				sb.WriteByte('\'')
				continue
			}
			break
		}
		p.advance()
		sb.WriteByte(c)
	}
	return sb.String(), nil
}

func resolveScalar(val string) *CandidateNode {
	if val == "" {
		return &CandidateNode{Kind: ScalarNode, Tag: "!!null", Value: ""}
	}
	tag, _ := guessTag(val)
	return &CandidateNode{Kind: ScalarNode, Tag: tag, Value: val}
}

func guessTag(val string) (string, string) {
	switch val {
	case "null", "Null", "NULL", "~":
		return "!!null", val
	case "true", "True", "TRUE":
		return "!!bool", val
	case "false", "False", "FALSE":
		return "!!bool", val
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF", "-.inf", "-.Inf", "-.INF", ".nan", ".NaN", ".NAN":
		return "!!float", val
	}
	if isIntStr(val) {
		return "!!int", val
	}
	if isFloatStr(val) {
		return "!!float", val
	}
	return "!!str", val
}

func isIntStr(s string) bool {
	t := s
	if t[0] == '+' || t[0] == '-' {
		t = t[1:]
	}
	if t == "" {
		return false
	}
	if strings.HasPrefix(t, "0x") || strings.HasPrefix(t, "0X") {
		t = t[2:]
		if t == "" {
			return false
		}
		for i := 0; i < len(t); i++ {
			if !isHexDigit(t[i]) {
				return false
			}
		}
		return true
	}
	if strings.HasPrefix(t, "0o") || strings.HasPrefix(t, "0O") {
		t = t[2:]
		if t == "" {
			return false
		}
		for i := 0; i < len(t); i++ {
			if t[i] < '0' || t[i] > '7' {
				return false
			}
		}
		return true
	}
	if strings.HasPrefix(t, "0b") || strings.HasPrefix(t, "0B") {
		t = t[2:]
		if t == "" {
			return false
		}
		for i := 0; i < len(t); i++ {
			if t[i] != '0' && t[i] != '1' {
				return false
			}
		}
		return true
	}
	for i := 0; i < len(t); i++ {
		if t[i] < '0' || t[i] > '9' {
			return false
		}
	}
	return true
}

func isFloatStr(s string) bool {
	t := s
	if t[0] == '+' || t[0] == '-' {
		t = t[1:]
	}
	if t == "" {
		return false
	}
	if strings.ContainsAny(t, ".eE") == false {
		return false
	}
	i := 0
	digits := 0
	for i < len(t) {
		c := t[i]
		if c >= '0' && c <= '9' {
			digits++
			i++
			continue
		}
		if c == '.' {
			i++
			continue
		}
		if c == 'e' || c == 'E' {
			if i == 0 || i == len(t)-1 {
				return false
			}
			if t[i+1] == '+' || t[i+1] == '-' {
				i++
			}
			i++
			continue
		}
		if c == '+' || c == '-' {
			if i == 0 {
				i++
				continue
			}
			return false
		}
		return false
	}
	return digits > 0
}

func isHexDigit(c byte) bool {
	return c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F'
}
