package yqlib

import (
	"fmt"
	"strings"
)

type yamlEmitter struct {
	sb             strings.Builder
	indent         int
	compactSeq     bool
	unwrapScalar   bool
	keepComments   bool
	printDocSep    bool
	docIndex       int
}

func clampIndent(i int) int {
	if i < 2 || i > 9 {
		return 2
	}
	return i
}

func EncodeYAML(node *CandidateNode, indent int, compactSeq bool, unwrapScalar bool, keepComments bool) (string, error) {
	e := &yamlEmitter{indent: clampIndent(indent), compactSeq: compactSeq, unwrapScalar: unwrapScalar, keepComments: keepComments, printDocSep: true}
	if node == nil {
		return "", nil
	}
	e.emitNode(node, 0, false, false)
	out := e.sb.String()
	if out == "" {
		return out, nil
	}
	if !strings.HasSuffix(out, "\n") {
		out += "\n"
	}
	return out, nil
}

func (e *yamlEmitter) writeIndent(col int) {
	e.sb.WriteString(strings.Repeat(" ", col))
}

func (e *yamlEmitter) writeComments(comment string, col int) {
	if comment == "" || !e.keepComments {
		return
	}
	parts := strings.Split(comment, "\n")
	for _, p := range parts {
		e.writeIndent(col)
		if p == "" {
			e.sb.WriteString("#\n")
		} else {
			e.sb.WriteString("# " + p + "\n")
		}
	}
}

// emitNode writes the node. col is the starting column for the node content.
// isSeqItem means the node follows a "- "
func (e *yamlEmitter) emitNode(n *CandidateNode, col int, isSeqItem bool, isMapValue bool) {
	if n == nil {
		return
	}
	e.writeComments(n.HeadComment, col)
	switch n.Kind {
	case SequenceNode:
		e.emitSeq(n, col, isSeqItem)
	case MappingNode:
		e.emitMap(n, col, isSeqItem)
	case AliasNode:
		e.writeIndent(col)
		e.sb.WriteString("*" + n.Value)
		e.writeLineComment(n, col)
	default:
		e.emitScalar(n, col, isSeqItem, isMapValue)
	}
}

func (e *yamlEmitter) writeLineComment(n *CandidateNode, col int) {
	if !e.keepComments || n == nil || n.LineComment == "" {
		e.sb.WriteString("\n")
		return
	}
	parts := strings.Split(n.LineComment, "\n")
	e.sb.WriteString(" # " + parts[0] + "\n")
	for _, p := range parts[1:] {
		e.writeIndent(col + e.indent)
		e.sb.WriteString("# " + p + "\n")
	}
}

func (e *yamlEmitter) emitSeq(n *CandidateNode, col int, isSeqItem bool) {
	if n.Style == FlowStyle {
		e.emitFlowSeq(n)
		return
	}
	if len(n.Content) == 0 {
		e.writeIndent(col)
		e.sb.WriteString("[]")
		e.writeLineComment(n, col)
		return
	}
	// determine dash column
	dashCol := col
	if isSeqItem {
		// nested sequence within a sequence entry: keep compact
		dashCol = col
	} else if e.compactSeq {
		dashCol = col
	}
	for i, child := range n.Content {
		if i > 0 {
			dashCol = e.seqDashCol(n, col, isSeqItem, i)
		} else {
			dashCol = e.seqDashCol(n, col, isSeqItem, 0)
		}
		e.writeComments(child.HeadComment, dashCol)
		e.writeIndent(dashCol)
		e.sb.WriteString("- ")
		e.emitNode(child, dashCol+2, true, false)
	}
}

func (e *yamlEmitter) seqDashCol(n *CandidateNode, col int, isSeqItem bool, i int) int {
	if i == 0 {
		return col
	}
	// subsequent items align with the first
	return col
}

func (e *yamlEmitter) emitMap(n *CandidateNode, col int, isSeqItem bool) {
	if n.Style == FlowStyle {
		e.emitFlowMap(n)
		return
	}
	if len(n.Content) == 0 {
		e.writeIndent(col)
		e.sb.WriteString("{}")
		e.writeLineComment(n, col)
		return
	}
	for _, child := range n.Content {
		e.writeComments(child.Key.HeadComment, col)
		e.writeIndent(col)
		e.sb.WriteString(encodeKey(child.Key))
		e.sb.WriteString(":")
		if child.Kind == SequenceNode && child.Style != FlowStyle {
			// block sequence as value
			newCol := col
			if !e.compactSeq {
				newCol = col + e.indent
			} else if e.indent > 2 {
				newCol = col + e.indent - 2
			}
			e.sb.WriteString("\n")
			e.emitNode(child, newCol, false, true)
			continue
		}
		if child.Kind == MappingNode && child.Style != FlowStyle {
			if len(child.Content) == 0 {
				e.sb.WriteString(" {}\n")
				continue
			}
			e.sb.WriteString("\n")
			e.emitNode(child, col+e.indent, false, true)
			continue
		}
		e.sb.WriteString(" ")
		e.emitScalarOrInline(child, col)
	}
}

func (e *yamlEmitter) emitScalarOrInline(n *CandidateNode, col int) {
	switch n.Kind {
	case SequenceNode:
		e.emitFlowSeq(n)
	case MappingNode:
		e.emitFlowMap(n)
	case AliasNode:
		e.sb.WriteString("*" + n.Value)
		e.writeLineComment(n, col)
	default:
		e.emitScalar(n, col, false, true)
	}
}

func (e *yamlEmitter) emitFlowSeq(n *CandidateNode) {
	e.sb.WriteString("[")
	for i, c := range n.Content {
		if i > 0 {
			e.sb.WriteString(", ")
		}
		e.emitInline(c)
	}
	e.sb.WriteString("]")
}

func (e *yamlEmitter) emitFlowMap(n *CandidateNode) {
	e.sb.WriteString("{")
	for i, c := range n.Content {
		if i > 0 {
			e.sb.WriteString(", ")
		}
		e.sb.WriteString(encodeKey(c.Key) + ": ")
		e.emitInline(c)
	}
	e.sb.WriteString("}")
}

func (e *yamlEmitter) emitInline(n *CandidateNode) {
	switch n.Kind {
	case SequenceNode:
		if n.Style == FlowStyle {
			e.emitFlowSeq(n)
		} else {
			// block style inside flow: emit flow anyway
			e.emitFlowSeq(n)
		}
	case MappingNode:
		if n.Style == FlowStyle {
			e.emitFlowMap(n)
		} else {
			e.emitFlowMap(n)
		}
	case AliasNode:
		e.sb.WriteString("*" + n.Value)
	default:
		e.sb.WriteString(encodeScalar(n, true))
	}
}

func (e *yamlEmitter) emitScalar(n *CandidateNode, col int, isSeqItem bool, isMapValue bool) {
	if n.Tag == "!!null" && n.Style == ZeroStyle {
		// null: print raw value
		e.sb.WriteString(n.Value)
		e.writeLineComment(n, col)
		return
	}
	if e.unwrapScalar && !isMapValue && !isSeqItem {
		// top-level unwrap: print raw
		e.sb.WriteString(n.Value)
		e.writeLineComment(n, col)
		return
	}
	e.writeIndent(col)
	e.sb.WriteString(encodeScalar(n, false))
	e.writeLineComment(n, col)
}

func (e *yamlEmitter) emitTopScalar(n *CandidateNode) {
	e.sb.WriteString(n.Value)
	e.writeLineComment(n, 0)
}

func encodeKey(k *CandidateNode) string {
	if k == nil {
		return "null"
	}
	switch k.Kind {
	case ScalarNode:
		if k.Tag == "!!merge" {
			return "<<"
		}
		return encodeScalar(k, true)
	case SequenceNode:
		return "[...]"
	case MappingNode:
		return "{...}"
	case AliasNode:
		return "*" + k.Value
	}
	return "null"
}

// encodeScalar produces the yaml representation of a scalar
func encodeScalar(n *CandidateNode, asKey bool) string {
	switch n.Style {
	case DoubleQuotedStyle:
		return quoteDouble(n.Value)
	case SingleQuotedStyle:
		return quoteSingle(n.Value)
	case LiteralStyle:
		return encodeLiteral(n, true)
	case FoldedStyle:
		return encodeLiteral(n, false)
	}
	if n.Tag == "!!null" {
		return n.Value
	}
	if n.Tag != "" && n.Tag != "!!str" && n.Tag != "!!int" && n.Tag != "!!float" && n.Tag != "!!bool" && n.Tag != "!!null" {
		// explicit tag
		return n.Tag + " " + maybeQuote(n.Value)
	}
	return maybeQuote(n.Value)
}

func maybeQuote(v string) string {
	if needsQuote(v) {
		return quoteDouble(v)
	}
	return v
}

func needsQuote(v string) bool {
	if v == "" {
		return true
	}
	switch v {
	case "true", "True", "TRUE", "false", "False", "FALSE", "null", "Null", "NULL", "~", "y", "Y", "n", "N", "yes", "Yes", "YES", "no", "No", "NO", "on", "On", "ON", "off", "Off", "OFF":
		return true
	}
	if isIntStr(v) || isFloatStr(v) {
		return true
	}
	c := v[0]
	if strings.IndexByte("!?&*-|>%@`\"'{}[],# \t", c) >= 0 {
		if !(c == '-' && (len(v) == 1 || (v[1] != ' '))) {
			return true
		}
		if c == '-' && len(v) > 1 && v[1] != ' ' {
			return true
		}
		return true
	}
	if strings.Contains(v, ": ") || strings.HasSuffix(v, ":") {
		return true
	}
	if strings.Contains(v, " #") {
		return true
	}
	if strings.ContainsAny(v, "\n\r") {
		return true
	}
	if strings.HasSuffix(v, " ") || strings.HasPrefix(v, " ") {
		return true
	}
	for i := 0; i < len(v); i++ {
		if v[i] < 0x20 || v[i] == 0x7f {
			return true
		}
	}
	return false
}

func quoteSingle(v string) string {
	return "'" + strings.ReplaceAll(v, "'", "''") + "'"
}

func quoteDouble(v string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range v {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\t':
			sb.WriteString("\\t")
		case '\r':
			sb.WriteString("\\r")
		case 0:
			sb.WriteString("\\0")
		case 7:
			sb.WriteString("\\a")
		case 8:
			sb.WriteString("\\b")
		case 11:
			sb.WriteString("\\v")
		case 12:
			sb.WriteString("\\f")
		case 27:
			sb.WriteString("\\e")
		case 0x85:
			sb.WriteString("\\N")
		case 0xA0:
			sb.WriteString("\\_")
		case 0x2028:
			sb.WriteString("\\L")
		case 0x2029:
			sb.WriteString("\\P")
		default:
			if r < 0x20 || r == 0x7f {
				fmt.Fprintf(&sb, "\\x%02X", r)
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func encodeLiteral(n *CandidateNode, literal bool) string {
	v := n.Value
