		sb.WriteString("-")
	} else if strings.HasSuffix(v, "\n\n") {
		sb.WriteString("+")
	}
	// detect indentation needs
	minIndent := -1
	for _, line := range strings.Split(strings.TrimSuffix(v, "\n"), "\n") {
		ind := 0
		for ind < len(line) && line[ind] == ' ' {
			ind++
		}
		if line != "" && (minIndent < 0 || ind < minIndent) {
			minIndent = ind
		}
	}
	if minIndent > 0 {
		sb.WriteString(fmt.Sprintf("%d", minIndent))
	}
	sb.WriteString("\n")
	lines := strings.Split(v, "\n")
	// drop last empty element caused by trailing newline
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
