func clampIndent(i int) int {
	if i < 2 || i > 9 {
		return 2
	}
	return i
}

func EncodeYAML(node *CandidateNode, indent int, compactSeq bool, unwrapScalar bool, keepComments bool) (string, error) {
	e := &yamlEmitter{indent: clampIndent(indent), compactSeq: compactSeq, unwrapScalar: unwrapScalar, keepComments: keepComments, printDocSep: true}
	if node == nil {
		return "", nil
	}
	e.emitNode(node, 0, false, false)
	out := e.sb.String()
	if out == "" {
		return out, nil
	}
	if !strings.HasSuffix(out, "\n") {
		out += "\n"
	}
	return out, nil
}

