{"command": "cd /workspace && cat > cmd/cli.go <<'GOEOF'
package cmd

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type commandSpec struct {
	name        string
	aliases     []string
	helpText    string
	usageText   string
	validArgs   []string
	hasSubCmds  bool
}

type parsedArgs struct {
	args        []string
	positional  []string
	isEval      bool
	isEvalAll   bool
	isCompletion string
}

type yqArgs struct {
	vals        flagValues
	positional  []string
	cmdName     string // "eval", "eval-all", "completion", ""
}

func newFlagValues() flagValues {
	v := flagValues{bools: map[string]bool{}, strings: map[string]string{}, ints: map[string]int{}, chars: map[string]string{}}
	for _, d := range flagDefs {
		switch d.kind {
		case flagBool:
			v.bools[d.long] = d.defB
		case flagString:
			v.strings[d.long] = d.defS
		case flagInt:
			v.ints[d.long] = d.defI
		case flagChar:
			v.chars[d.long] = d.defS
		}
	}
	return v
}

func (v *flagValues) getBool(name string) bool { return v.bools[name] }
func (v *flagValues) getString(name string) string {
	if s, ok := v.strings[name]; ok {
		return s
	}
	return ""
}
func (v *flagValues) getInt(name string) int { return v.ints[name] }

type flagError struct{ msg string }

func (e *flagError) Error() string { return e.msg }

// parseFlags mimics pflag parsing
func parseFlags(args []string, rootOnly map[string]bool) (*yqArgs, error) {
	vals := newFlagValues()
	res := &yqArgs{vals: vals}
	cmdName := ""
	i := 0
	endFlags := false
	for i < len(args) {
		a := args[i]
		if endFlags {
			res.positional = append(res.positional, a)
			i++
			continue
		}
		switch {
		case a == "--":
			endFlags = true
			i++
			continue
		case strings.HasPrefix(a, "--"):
			body := a[2:]
			val := ""
			hasVal := false
			if idx := strings.Index(body, "="); idx >= 0 {
				val = body[idx+1:]
				body = body[:idx]
				hasVal = true
			}
			d := findFlagLong(body)
			if d == nil {
				return nil, &flagError{fmt.Sprintf("unknown flag: --%s", body)}
			}
			if rootOnly[d.long] {
				return nil, &flagError{fmt.Sprintf("unknown flag: --%s", body)}
			}
			if d.kind == flagBool {
				if hasVal {
					b, err := strconv.ParseBool(val)
					if err != nil {
						return nil, &flagError{fmt.Sprintf("invalid argument %q for \"--%s\" flag: strconv.ParseBool: parsing %q: invalid syntax", val, body, val)}
					}
					vals.bools[d.long] = b
				} else {
					vals.bools[d.long] = true
				}
			} else {
				if !hasVal {
					if i+1 >= len(args) {
						return nil, &flagError{fmt.Sprintf("flag needs an argument: --%s", body)}
					}
					i++
					val = args[i]
				}
				if err := setFlagValue(vals, d, val); err != nil {
					return nil, err
				}
			}
			i++
			continue
		case len(a) > 1 && a[0] == '-':
			// short flags, possibly combined
			rest := a[1:]
			j := 0
			for j < len(rest) {
				sh := string(rest[j])
				if sh == "h" {
					return &yqArgs{vals: vals, helpRequested: true, positional: res.positional}, nil
				}
				d := findFlagShort(sh)
				if d == nil || rootOnly[d.long] {
					if d == nil {
						return nil, &flagError{fmt.Sprintf("unknown shorthand flag: %q in -%s", sh, rest)}
					}
					return nil, &flagError{fmt.Sprintf("unknown shorthand flag: %q in -%s", sh, rest)}
				}
				if d.kind == flagBool {
					// check for =value
					val := ""
					hasVal := false
					if j+1 < len(rest) && rest[j+1] == '=' {
						val = rest[j+2:]
						hasVal = true
						j = len(rest)
					} else {
						j++
					}
					if hasVal {
						b, err := strconv.ParseBool(val)
						if err != nil {
							return nil, &flagError{fmt.Sprintf("invalid argument %q for \"-%s, --%s\" flag: strconv.ParseBool: parsing %q: invalid syntax", val, d.short, d.long, val)}
						}
						vals.bools[d.long] = b
					} else {
						vals.bools[d.long] = true
					}
					continue
				}
				// value flag
				restAfter := rest[j+1:]
				var val string
				if strings.HasPrefix(restAfter, "=") {
					val = restAfter[1:]
					j = len(rest)
				} else if restAfter != "" {
					val = restAfter
					j = len(rest)
				} else {
					if i+1 >= len(args) {
						return nil, &flagError{fmt.Sprintf("flag needs an argument: %q in -%s", sh, rest)}
					}
					i++
					val = args[i]
					j = len(rest)
				}
				if err := setFlagValue(vals, d, val); err != nil {
					return nil, err
				}
			}
			i++
			continue
		default:
			// positional
			if cmdName == "" && len(res.positional) == 0 {
				switch a {
				case "eval", "e":
					cmdName = "eval"
					i++
					continue
				case "eval-all", "ea":
					cmdName = "eval-all"
					i++
					continue
				case "completion", "shell-completion":
					cmdName = "completion"
					i++
					continue
				}
			}
			res.positional = append(res.positional, a)
			i++
		}
	}
	res.cmdName = cmdName
	return res, nil
}

func setFlagValue(vals *flagValues, d *flagDef, val string) error {
	switch d.kind {
	case flagString:
		vals.strings[d.long] = val
	case flagChar:
		if len(val) == 0 {
			return &flagError{fmt.Sprintf("invalid argument %q for \"--%s\" flag: ", val, d.long)}
		}
		vals.chars[d.long] = string(val[0])
	case flagInt:
		n, err := strconv.ParseInt(val, 0, 64)
		if err != nil {
			ne := err.(*strconv.NumError)
			return &flagError{fmt.Sprintf("invalid argument %q for \"-%s, --%s\" flag: strconv.ParseInt: parsing %q: %s", val, d.short, d.long, val, ne.Err.Error())}
		}
		vals.ints[d.long] = int(n)
	}
	return nil
}

var _ = os.Stdout
GOEOF
python3 - <<'PY'
p='cmd/cli.go'
s=open(p).read()
s=s.replace('type yqArgs struct {\n\tvals','type yqArgs struct {\n\thelpRequested bool\n\tvals')
open(p,'w').write(s)
PY
go vet ./cmd/ 2>&1|head -5"}

