						vals.bools[d.long] = b
					} else {
						vals.bools[d.long] = true
					}
					continue
				}
				// value flag
				restAfter := rest[j+1:]
				var val string
				if strings.HasPrefix(restAfter, "=") {
					val = restAfter[1:]
					j = len(rest)
				} else if restAfter != "" {
					val = restAfter
					j = len(rest)
				} else {
					if i+1 >= len(args) {
						return nil, &flagError{fmt.Sprintf("flag needs an argument: %q in -%s", sh, rest)}
					}
					i++
					val = args[i]
					j = len(rest)
				}
				if err := setFlagValue(vals, d, val); err != nil {
					return nil, err
				}
			}
			i++
			continue
		default:
			// positional
			if cmdName == "" && len(res.positional) == 0 {
				switch a {
				case "eval", "e":
					cmdName = "eval"
					i++
					continue
				case "eval-all", "ea":
					cmdName = "eval-all"
					i++
					continue
				case "completion", "shell-completion":
					cmdName = "completion"
					i++
					continue
				}
			}
			res.positional = append(res.positional, a)
			i++
		}
	}
	res.cmdName = cmdName
	return res, nil
}

func setFlagValue(vals *flagValues, d *flagDef, val string) error {
	switch d.kind {
	case flagString:
		vals.strings[d.long] = val
	case flagChar:
		if len(val) == 0 {
			return &flagError{fmt.Sprintf("invalid argument %q for \"--%s\" flag: ", val, d.long)}
		}
		vals.chars[d.long] = string(val[0])
	case flagInt:
		n, err := strconv.ParseInt(val, 0, 64)
		if err != nil {
			ne := err.(*strconv.NumError)
			return &flagError{fmt.Sprintf("invalid argument %q for \"-%s, --%s\" flag: strconv.ParseInt: parsing %q: %s", val, d.short, d.long, val, ne.Err.Error())}
		}
		vals.ints[d.long] = int(n)
	}
	return nil
}

