{"command": "cd /workspace && cat > pkg/yqlib/lexer.go <<'GOEOF'
package yqlib

import (
	"fmt"
	"strconv"
	"strings"
)

type lexer struct {
	data          string
	pos           int
	line          int
	col           int
	allowQuestion bool
	prevOpType    opType
}

type lexError struct {
	msg string
	line int
	col  int
}

func (e *lexError) Error() string { return fmt.Sprintf("%d:%d: lexer: %s", e.line, e.col, e.msg) }

func (l *lexer) atEOF() bool { return l.pos >= len(l.data) }

func (l *lexer) peek() byte {
	if l.atEOF() {
		return 0
	}
	return l.data[l.pos]
}

func (l *lexer) advance() byte {
	c := l.data[l.pos]
	l.pos++
	if c == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return c
}

func (l *lexer) lineCol() (int, int) { return l.line, l.col }

// tokenize converts the expression into tokens. Stops at newline.
func Tokenize(expr string) ([]*token, error) {
	l := &lexer{data: expr, line: 1, col: 1}
	var toks []*token
	for !l.atEOF() {
		c := l.peek()
		if c == '\n' {
			break
		}
		if c == ' ' || c == '\t' || c == '\r' {
			l.advance()
			continue
		}
		if c == '#' {
			// comment to end of line
			for !l.atEOF() && l.peek() != '\n' {
				l.advance()
			}
			continue
		}
		line, col := l.lineCol()
		t, err := l.next()
		if err != nil {
			return nil, &lexError{msg: fmt.Sprintf("invalid input text %q", l.data[l.pos-0:]), line: line, col: col}
		}
		if t == nil {
			// no token matched: report error at this position with the remaining text
			rest := l.data[l.pos:]
			return nil, &lexError{msg: fmt.Sprintf("invalid input text %q", truncateText(rest)), line: line, col: col}
		}
		t.line = line
		t.column = col
		l.prevOpType = t.operationType
		toks = append(toks, t)
	}
	return toks, nil
}

func truncateText(s string) string {
	if len(s) > 20 {
		return s[:20] + "..."
	}
	return s
}

func (l *lexer) next() (*token, error) {
	c := l.peek()
	switch c {
	case '"':
		s, err := l.readDoubleQuoted()
		if err != nil {
			return nil, err
		}
		n := NewScalar("!!str", s, DoubleQuotedStyle)
		return &token{operationType: opNone, literalNode: n}, nil
	case '$':
		l.advance()
		start := l.pos
		for !l.atEOF() && isWordChar(l.peek()) {
			l.advance()
		}
		name := l.data[start:l.pos]
		if name == "" {
			return nil, nil
		}
		return &token{operationType: opVariable, value: name}, nil
	case '.':
		// field or recursive descent
		if l.pos+1 < len(l.data) && l.data[l.pos+1] == '.' {
			l.advance()
			l.advance()
			return &token{operationType: opRecursiveDescent}, nil
		}
		l.advance()
		// field name: run of field chars
		start := l.pos
		for !l.atEOF() && isFieldChar(l.peek()) {
			l.advance()
		}
		name := l.data[start:l.pos]
		if strings.HasSuffix(name, "?") && name != "?" {
			// drop one trailing question mark
			l.pos--
			name = name[:len(name)-1]
		}
		t := &token{operationType: opSelf, fieldName: name, hasField: name != ""}
		if name == "" {
			t.hasField = false
		}
		l.allowQuestion = true
		return t, nil
	}
	// hex number
	if c == '0' && l.pos+1 < len(l.data) && (l.data[l.pos+1] == 'x' || l.data[l.pos+1] == 'X') {
		start := l.pos
		l.advance()
		l.advance()
		j := l.pos
		for !l.atEOF() && isHexDigit(l.peek()) {
			l.advance()
		}
		if l.pos == j {
			// not a hex number: rewind and fall through to number
			l.pos = start
		} else {
			v := l.data[start:l.pos]
			return &token{operationType: opNumber, value: v}, nil
		}
	}
	if c >= '0' && c <= '9' || (c == '-' && l.pos+1 < len(l.data) && l.data[l.pos+1] >= '0' && l.data[l.pos+1] <= '9') {
		start := l.pos
		if c == '-' {
			l.advance()
		}
		digits := 0
		for !l.atEOF() && l.peek() >= '0' && l.peek() <= '9' {
			l.advance()
			digits++
		}
		if !l.atEOF() && l.peek() == '.' {
			l.advance()
			for !l.atEOF() && l.peek() >= '0' && l.peek() <= '9' {
				l.advance()
			}
		}
		if !l.atEOF() && (l.peek() == 'e' || l.peek() == 'E') {
			save := l.pos
			l.advance()
			if !l.atEOF() && (l.peek() == '+' || l.peek() == '-') {
				l.advance()
			}
			d := 0
			for !l.atEOF() && l.peek() >= '0' && l.peek() <= '9' {
				l.advance()
				d++
			}
			if d == 0 {
				l.pos = save
			}
		}
		v := l.data[start:l.pos]
		return &token{operationType: opNumber, value: v}, nil
	}
	// multi-char operators
	for _, s := range []string{"|=", "+=", "-=", "*=", "==", "!=", "<=", ">="} {
		if strings.HasPrefix(l.data[l.pos:], s) {
			var op opType
			switch s {
			case "|=":
				op = opUpdateAssign
			case "+=":
				op = opAddAssign
			case "-=":
				op = opSubtractAssign
			case "*=":
				op = opMultiplyAssign
			case "==":
				op = opEquals
			case "!=":
				op = opNotEquals
			case "<=":
				op = opLessThanOrEqual
			case ">=":
				op = opGreaterThanOrEqual
			}
			for i := 0; i < len(s); i++ {
				l.advance()
			}
			l.allowQuestion = false
			return &token{operationType: op}, nil
		}
	}
	switch c {
	case '[':
		l.advance()
		l.allowQuestion = true
		return &token{operationType: opOpenBracket}, nil
	case ']':
		l.advance()
		l.allowQuestion = true
		return &token{operationType: opCloseBracket}, nil
	case '(':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opOpenParen}, nil
	case ')':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opCloseParen}, nil
	case '{':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opOpenBrace}, nil
	case '}':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opCloseBrace}, nil
	case ',':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opUnion}, nil
	case '|':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opPipe}, nil
	case ':':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opColon}, nil
	case ';':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opSemicolon}, nil
	case '=':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opAssign}, nil
	case '+':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opAdd}, nil
	case '-':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opSubtract}, nil
	case '*':
		l.advance()
		l.allowQuestion = false
