}

func wordToken(w string) (opType, bool) {
	switch w {
	case "as":
		return opAs, true
	case "ref":
		return opRef, true
	case "and":
		return opAnd, true
	case "or":
		return opOr, true
	case "not":
		return opNot, true
	case "true":
		return opBool, true
	case "false":
