	}
	return "", false
}

func (l *lexer) readDoubleQuoted() (string, error) {
	l.advance() // "
	var sb strings.Builder
	for {
		if l.atEOF() {
			return "", fmt.Errorf("unexpected end")
		}
		c := l.peek()
		if c == '"' {
			l.advance()
			break
		}
		if c == '\\' {
			l.advance()
			if l.atEOF() {
				return "", fmt.Errorf("unexpected end")
			}
			e := l.advance()
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '0':
				sb.WriteByte(0)
			case 'a':
				sb.WriteByte(7)
			case 'b':
				sb.WriteByte(8)
			case 'v':
				sb.WriteByte(11)
			case 'f':
				sb.WriteByte(12)
			case 'e':
				sb.WriteByte(27)
			case '"', '\\', '/', '\'':
				sb.WriteByte(e)
			default:
				sb.WriteByte('\\')
				sb.WriteByte(e)
			}
			continue
		}
		l.advance()
		sb.WriteByte(c)
	}
	return sb.String(), nil
}

