	case '.':
		// field or recursive descent
		if l.pos+1 < len(l.data) && l.data[l.pos+1] == '.' {
			l.advance()
			l.advance()
			return &token{operationType: opRecursiveDescent}, nil
		}
		l.advance()
		// field name: run of field chars
		start := l.pos
		for !l.atEOF() && isFieldChar(l.peek()) {
			l.advance()
		}
		name := l.data[start:l.pos]
		if strings.HasSuffix(name, "?") && name != "?" {
			// drop one trailing question mark
			l.pos--
			name = name[:len(name)-1]
		}
		t := &token{operationType: opSelf, fieldName: name, hasField: name != ""}
		if name == "" {
			t.hasField = false
		}
		l.allowQuestion = true
		return t, nil
	}
	// hex number
	if c == '0' && l.pos+1 < len(l.data) && (l.data[l.pos+1] == 'x' || l.data[l.pos+1] == 'X') {
		start := l.pos
		l.advance()
		l.advance()
		j := l.pos
		for !l.atEOF() && isHexDigit(l.peek()) {
			l.advance()
		}
		if l.pos == j {
			// not a hex number: rewind and fall through to number
			l.pos = start
		} else {
			v := l.data[start:l.pos]
			return &token{operationType: opNumber, value: v}, nil
		}
	}
	if c >= '0' && c <= '9' || (c == '-' && l.pos+1 < len(l.data) && l.data[l.pos+1] >= '0' && l.data[l.pos+1] <= '9') {
		start := l.pos
		if c == '-' {
			l.advance()
		}
		digits := 0
		for !l.atEOF() && l.peek() >= '0' && l.peek() <= '9' {
			l.advance()
			digits++
		}
		if !l.atEOF() && l.peek() == '.' {
			l.advance()
			for !l.atEOF() && l.peek() >= '0' && l.peek() <= '9' {
				l.advance()
			}
		}
		if !l.atEOF() && (l.peek() == 'e' || l.peek() == 'E') {
			save := l.pos
			l.advance()
			if !l.atEOF() && (l.peek() == '+' || l.peek() == '-') {
				l.advance()
			}
			d := 0
			for !l.atEOF() && l.peek() >= '0' && l.peek() <= '9' {
				l.advance()
				d++
			}
			if d == 0 {
				l.pos = save
			}
		}
		v := l.data[start:l.pos]
		return &token{operationType: opNumber, value: v}, nil
	}
	// multi-char operators
	for _, s := range []string{"|=", "+=", "-=", "*=", "==", "!=", "<=", ">="} {
		if strings.HasPrefix(l.data[l.pos:], s) {
			var op opType
			switch s {
			case "|=":
				op = opUpdateAssign
			case "+=":
				op = opAddAssign
			case "-=":
				op = opSubtractAssign
			case "*=":
				op = opMultiplyAssign
			case "==":
				op = opEquals
			case "!=":
				op = opNotEquals
			case "<=":
				op = opLessThanOrEqual
			case ">=":
				op = opGreaterThanOrEqual
			}
			for i := 0; i < len(s); i++ {
				l.advance()
			}
			l.allowQuestion = false
			return &token{operationType: op}, nil
		}
	}
	switch c {
	case '[':
		l.advance()
		l.allowQuestion = true
		return &token{operationType: opOpenBracket}, nil
	case ']':
		l.advance()
		l.allowQuestion = true
		return &token{operationType: opCloseBracket}, nil
	case '(':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opOpenParen}, nil
	case ')':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opCloseParen}, nil
	case '{':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opOpenBrace}, nil
	case '}':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opCloseBrace}, nil
	case ',':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opUnion}, nil
	case '|':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opPipe}, nil
	case ':':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opColon}, nil
	case ';':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opSemicolon}, nil
	case '=':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opAssign}, nil
	case '+':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opAdd}, nil
	case '-':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opSubtract}, nil
	case '*':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opMultiply}, nil
	case '/':
		if strings.HasPrefix(l.data[l.pos:], "//") {
			l.advance()
			l.advance()
			l.allowQuestion = false
			return &token{operationType: opAlternative}, nil
		}
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opDivide}, nil
	case '%':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opModulo}, nil
	case '<':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opLessThan}, nil
	case '>':
		l.advance()
		l.allowQuestion = false
		return &token{operationType: opGreaterThan}, nil
	case '?':
		if l.allowQuestion {
			l.advance()
			l.allowQuestion = true
			return &token{operationType: opOptional}, nil
		}
		return nil, nil
	}
	// keywords
	if isWordChar(c) {
		start := l.pos
		for !l.atEOF() && isWordChar(l.peek()) {
			l.advance()
		}
		w := l.data[start:l.pos]
		op, ok := wordToken(w)
		if ok {
			l.allowQuestion = false
			return &token{operationType: op, value: w}, nil
		}
		// rewind: maybe a shorter token matches
		for i := len(w) - 1; i > 0; i-- {
			op2, ok2 := wordToken(w[:i])
			if ok2 {
				l.pos = start + i
				l.allowQuestion = false
				return &token{operationType: op2, value: w[:i]}, nil
			}
		}
		l.pos = start
		return nil, nil
	}
	return nil, nil
}

func isFieldChar(c byte) bool {
	switch c {
	case '!', '"', '(', ')', ',', '.', ':', ';', '=', '[', '\\', ']', '{', '|', '}':
		return false
	}
	return c > ' '
}

func wordToken(w string) (opType, bool) {
	switch w {
	case "as":
		return opAs, true
	case "ref":
		return opRef, true
	case "and":
		return opAnd, true
	case "or":
		return opOr, true
	case "not":
		return opNot, true
	case "true":
		return opBool, true
	case "false":
		return opBool, true
	case "null":
		return opNull, true
	case "True":
		return opBool, true
	case "False":
		return opBool, true
	case "Null":
		return opNull, true
	case "TRUE":
		return opBool, true
	case "FALSE":
		return opBool, true
	case "NULL":
		return opNull, true
	case "~":
		return opNull, true
	}
	if f, ok := functionToken(w); ok {
		return opFunction, true
	}
	return opNone, false
}

// functionToken returns the function name if known
func functionToken(w string) (string, bool) {
	known := map[string]bool{
		"keys": true, "length": true, "map": true, "map_values": true, "select": true, "has": true,
		"eval": true, "with": true, "with_entries": true, "to_entries": true, "from_entries": true,
		"pick": true, "del": true, "setpath": true, "delpaths": true, "path": true, "parent": true,
		"parents": true, "filename": true, "fileIndex": true, "documentIndex": true, "document_index": true,
		"error": true, "line": true, "column": true, "type": true, "tostring": true, "tonumber": true,
		"tojson": true, "fromjson": true, "toyaml": true, "fromyaml": true, "toxml": true, "fromxml": true,
		"toprops": true, "fromprops": true, "tocsv": true, "fromcsv": true, "totsv": true, "fromtsv": true,
		"to_tsv": true, "from_tsv": true, "to_csv": true, "from_csv": true, "filter": true, "flatten": true,
		"unique": true, "unique_by": true, "sort": true, "sort_by": true, "group_by": true, "reverse": true,
		"min": true, "max": true, "first": true, "split": true, "join": true, "test": true, "match": true,
		"capture": true, "sub": true, "trim": true, "upcase": true, "downcase": true, "explode": true,
		"format_datetime": true, "now": true, "tz": true, "envsubst": true, "load": true,
		"docIndex": true, "di": true, "fi": true, "tag": true, "key": true, "ref": true,
		"all": true, "any": true, "all_c": true, "any_c": true,
	}
	if known[w] {
		return w, true
	}
	return "", false
}

func (l *lexer) readDoubleQuoted() (string, error) {
	l.advance() // "
	var sb strings.Builder
	for {
		if l.atEOF() {
			return "", fmt.Errorf("unexpected end")
		}
		c := l.peek()
		if c == '"' {
			l.advance()
			break
		}
		if c == '\\' {
			l.advance()
			if l.atEOF() {
				return "", fmt.Errorf("unexpected end")
			}
			e := l.advance()
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '0':
				sb.WriteByte(0)
			case 'a':
				sb.WriteByte(7)
			case 'b':
				sb.WriteByte(8)
			case 'v':
				sb.WriteByte(11)
			case 'f':
				sb.WriteByte(12)
			case 'e':
				sb.WriteByte(27)
			case '"', '\\', '/', '\'':
				sb.WriteByte(e)
			default:
				sb.WriteByte('\\')
				sb.WriteByte(e)
			}
			continue
		}
		l.advance()
		sb.WriteByte(c)
	}
	return sb.String(), nil
}

