package yqlib

import (
	"fmt"
)

type parser struct {
	toks []*token
	pos  int
}

// ParseExpression parses the token list into an expression tree
func ParseExpression(toks []*token) (*expressionNode, error) {
	p := &parser{toks: toks}
	if len(toks) == 0 {
		return nil, nil
	}
	node, err := p.parseExpr(0)
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.toks) {
		return nil, parseErrorf("bad expression, please check expression syntax")
	}
	return node, nil
}

func (p *parser) peek() *token {
	if p.pos >= len(p.toks) {
		return nil
	}
	return p.toks[p.pos]
}

func (p *parser) isPathToken(t *token) bool {
	if t == nil {
		return false
	}
	switch t.operationType {
	case opSelf, opRecursiveDescent, opOpenBracket:
		return true
	}
	return false
}

func (p *parser) parseExpr(minPrec int) (*expressionNode, error) {
	lhs, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil {
			break
		}
		// juxtaposition: path token following a path expression
		if p.isPathToken(t) {
			// implicit pipe
			if minPrec > 2 {
				break
			}
			p.pos++
			// parse the rhs path expression at a tight precedence
			rhs, err := p.parsePathRhs()
			if err != nil {
				return nil, err
			}
			lhs = &expressionNode{operationType: opPipe, Lhs: lhs, Rhs: rhs}
			continue
		}
		// postfix optional
		if t.operationType == opOptional {
			if minPrec > 9 {
				break
			}
			p.pos++
			lhs = &expressionNode{operationType: opOptional, Lhs: lhs}
			continue
		}
		if !t.operationType.isOperator() {
			break
		}
		prec := t.operationType.precedence()
		if prec < minPrec {
			break
		}
		// special: as operator requires a pipe
		if t.operationType == opAs {
			p.pos++
			varTok := p.peek()
			varName := ""
			if varTok != nil && varTok.operationType == opVariable {
				varName = varTok.value
				p.pos++
			}
			pipeTok := p.peek()
			if pipeTok == nil || pipeTok.operationType != opPipe {
				return nil, parseErrorf("must use variable with a pipe, e.g. `exp as $x | ...`")
			}
			p.pos++
			rhs, err := p.parseExpr(2)
			if err != nil {
				return nil, err
			}
			lhs = &expressionNode{operationType: opAs, Lhs: lhs, Rhs: rhs, varName: varName}
			continue
		}
		// assignment operators need a lhs
		if lhs == nil {
			return nil, parseErrorf("bad expression, please check expression syntax")
		}
		np := t.operationType.numParameters()
		if np == 2 {
			p.pos++
			next := prec
			if t.operationType.rightAssoc() {
				next = prec + 1
			} else {
				next = prec + 1
			}
			rhs, err := p.parseExpr(next)
			if err != nil {
				return nil, err
			}
			lhs = &expressionNode{operationType: t.operationType, Lhs: lhs, Rhs: rhs}
			continue
		}
		break
	}
	return lhs, nil
}

// parsePathRhs parses the rhs of a juxtaposed path: a path expression
func (p *parser) parsePathRhs() (*expressionNode, error) {
	lhs, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil {
			break
		}
		if t.operationType == opOptional {
			p.pos++
			lhs = &expressionNode{operationType: opOptional, Lhs: lhs}
			continue
		}
		if !p.isPathToken(t) {
			break
		}
		if minPrec := 0; false {
			_ = minPrec
		}
		p.pos++
		rhs, err := p.parsePathRhs()
		if err != nil {
			return nil, err
		}
		lhs = &expressionNode{operationType: opPipe, Lhs: lhs, Rhs: rhs}
	}
	return lhs, nil
}

func (p *parser) parsePrimary() (*expressionNode, error) {
	t := p.peek()
	if t == nil {
		return nil, parseErrorf("bad expression, please check expression syntax")
	}
	switch t.operationType {
	case opSelf:
		p.pos++
		return p.parseTraverse(&expressionNode{operationType: opSelf})
	case opRecursiveDescent:
		p.pos++
		return p.parseTraverse(&expressionNode{operationType: opRecursiveDescent})
	case opOpenBracket:
		return p.parseBracket(nil)
	case opOpenParen:
		p.pos++
		inner, err := p.parseExpr(0)
		if err != nil {
			return nil, err
		}
		if t2 := p.peek(); t2 == nil || t2.operationType != opCloseParen {
			return nil, parseErrorf("bad expression - probably missing close bracket on (")
		}
		p.pos++
		if inner == nil {
			inner = &expressionNode{operationType: opSelf}
		}
		return inner, nil
	case opOpenBrace:
		return p.parseMapLiteral()
	case opNumber:
		p.pos++
		return p.numberNode(t.value)
	case opString:
		p.pos++
		return &expressionNode{operationType: opString, literalNode: t.literalNode}, nil
	case opVariable:
		p.pos++
		return &expressionNode{operationType: opVariable, varName: t.value}, nil
	case opBool, opNull:
		p.pos++
		var v string
		if t.operationType == opNull {
			v = "null"
		} else {
			v = t.value
		}
		tag := "!!bool"
		if t.operationType == opNull {
			tag = "!!null"
		}
		return &expressionNode{operationType: t.operationType, literalNode: &CandidateNode{Kind: ScalarNode, Tag: tag, Value: v}}, nil
	case opFunction:
		return p.parseFunctionCall()
	case opPipe, opUnion, opAlternative, opAssign, opUpdateAssign, opAddAssign, opSubtractAssign, opMultiplyAssign,
		opAdd, opSubtract, opMultiply, opDivide, opModulo, opEquals, opNotEquals, opLessThan, opLessThanOrEqual,
		opGreaterThan, opGreaterThanOrEqual, opAnd, opOr, opNot, opAs, opRef:
		// operator without lhs
		return nil, &operatorArityError{op: t.operationType, have: 0}
	case opCloseParen:
		return nil, parseErrorf("bad expression, got close brackets without matching opening bracket")
	case opCloseBracket:
		return nil, parseErrorf("bad expression, could not find matching `)`")
	case opCloseBrace:
		return nil, parseErrorf("bad expression, could not find matching `)`")
	case opColon:
		return nil, &operatorArityError{op: opColon, have: 0}
	case opSemicolon:
		return nil, &operatorArityError{op: opSemicolon, have: 0}
	case opOptional:
		return nil, parseErrorf("bad expression, please check expression syntax")
	}
	return nil, parseErrorf("bad expression, please check expression syntax")
}

type operatorArityError struct {
	op   opType
	have int
}

func (e *operatorArityError) Error() string {
	desc := e.op.tokenDescription()
	if desc == "" {
		desc = "'" + e.op.functionName() + "'"
	}
	return fmt.Sprintf("Error: %s expects %d args but there is %d", desc, e.op.numParameters(), e.have)
}

func (o opType) functionName() string {
	return ""
}

// parseTraverse continues the traversal chain after a field/self token
func (p *parser) parseTraverse(lhs *expressionNode) (*expressionNode, error) {
	for {
		t := p.peek()
		if t == nil {
			break
		}
		if t.operationType == opOpenBracket {
			node, err := p.parseBracket(lhs)
			if err != nil {
				return nil, err
			}
			lhs = node
			continue
		}
		if t.operationType == opSelf {
			// juxtaposed field
			p.pos++
			rhs := &expressionNode{operationType: opSelf, fieldName: t.fieldName, hasField: t.hasField}
			lhs = &expressionNode{operationType: opPipe, Lhs: lhs, Rhs: rhs}
			continue
		}
		if t.operationType == opRecursiveDescent {
			p.pos++
			rhs := &expressionNode{operationType: opRecursiveDescent}
			lhs = &expressionNode{operationType: opPipe, Lhs: lhs, Rhs: rhs}
			continue
		}
		break
	}
	return lhs, nil
}

// parseBracket parses `[...]` as an index/iterate/slice, or as an array literal if lhs==nil
func (p *parser) parseBracket(lhs *expressionNode) (*expressionNode, error) {
	p.pos++ // consume [
	// collect expressions separated by commas
	var exps []*expressionNode
	var first *expressionNode
	var startExp, endExp *expressionNode
	isEmpty := true
	for {
		t := p.peek()
		if t == nil {
			return nil, parseErrorf("bad expression, could not find matching `]`")
		}
		if t.operationType == opCloseBracket {
			p.pos++
			break
		}
		if t.operationType == opColon {
			// slice with empty start
			p.pos++
			isEmpty = false
			startExp = nil
			if e := p.peek(); e != nil && e.operationType != opCloseBracket {
				if e.operationType == opColon {
					return nil, parseErrorf("bad expression, please check expression syntax")
				}
				e2, err := p.parseExpr(0)
				if err != nil {
					return nil, err
				}
				endExp = e2
			}
			if t2 := p.peek(); t2 == nil || t2.operationType != opCloseBracket {
				return nil, parseErrorf("bad expression, could not find matching `]`")
			}
			p.pos++
			first = nil
			goto slice
		}
		isEmpty = false
		e, err := p.parseExpr(0)
		if err != nil {
			return nil, err
		}
		if t2 := p.peek(); t2 != nil && t2.operationType == opColon {
			// slice
			p.pos++
			if e2 := p.peek(); e2 != nil && e2.operationType != opCloseBracket {
				if e2.operationType == opColon {
					return nil, parseErrorf("bad expression, please check expression syntax")
				}
				v, err := p.parseExpr(0)
				if err != nil {
					return nil, err
				}
				endExp = v
			}
			if t3 := p.peek(); t3 == nil || t3.operationType != opCloseBracket {
				return nil, parseErrorf("bad expression, could not find matching `]`")
			}
			p.pos++
			startExp = e
			goto slice
		}
		if exps == nil {
			exps = []*expressionNode{}
		}
		exps = append(exps, e)
		if t3 := p.peek(); t3 != nil && t3.operationType == opUnion {
			p.pos++
			continue
		}
		if t3 := p.peek(); t3 != nil && t3.operationType == opOptional {
			p.pos++
		}
		if t4 := p.peek(); t4 != nil && t4.operationType == opCloseBracket {
			p.pos++
			break
		}
		if t5 := p.peek(); t5 != nil && t5.operationType == opUnion {
			p.pos++
			continue
		}
		return nil, parseErrorf("bad expression, could not find matching `]`")
	}
	if isEmpty {
		// iterate
		node := &expressionNode{operationType: opOpenBracket, isIterate: true, Lhs: lhs}
		return node, nil
	}
	if lhs == nil {
		// array literal
		return &expressionNode{operationType: opBlock, blockKind: 1, block: exps}, nil
	}
	if len(exps) == 1 {
		return &expressionNode{operationType: opOpenBracket, Lhs: lhs, indexExps: exps}, nil
	}
	return &expressionNode{operationType: opOpenBracket, Lhs: lhs, indexExps: exps}, nil
slice:
	_ = exps
	if lhs == nil {
		return nil, parseErrorf("bad expression, please check expression syntax")
	}
	return &expressionNode{operationType: opOpenBracket, Lhs: lhs, indexExps: []*expressionNode{}, isSlice: true,
		sliceStart: startExp, sliceEnd: endExp}, nil
}

func (p *parser) parseMapLiteral() (*expressionNode, error) {
	p.pos++ // {
	var keys, vals []*expressionNode
	for {
		t := p.peek()
		if t == nil {
			return nil, parseErrorf("bad expression, could not find matching `}`")
		}
		if t.operationType == opCloseBrace {
			p.pos++
			break
		}
