		np := functionMinParams(name)
		if np > 0 {
			return nil, &functionArityError{name: name, min: np}
		}
	}
	return &expressionNode{operationType: opFunction, varName: name, arguments: args}, nil
}

type functionArityError struct {
	name string
	min  int
}

func (e *functionArityError) Error() string {
	return fmt.Sprintf("Error: '%s' expects %d arg but received none", e.name, e.min)
}

func functionMinParams(name string) int {
	switch name {
	case "map", "map_values", "select", "has", "eval", "with", "with_entries", "pick", "del", "setpath",
		"delpaths", "filter", "unique_by", "sort_by", "group_by", "all_c", "any_c", "split", "join", "test",
		"match", "capture", "sub", "explode", "format_datetime", "tz", "envsubst", "ireduce", "load", "error":
		return 1
	case "ref":
		return 2
	}
