func (e *evaluator) evalLogic(node *expressionNode, input *CandidateNode) ([]*CandidateNode, error) {
	lhs, err := e.eval(node.Lhs, input)
	if err != nil {
		return nil, err
	}
	rhs, err := e.eval(node.Rhs, input)
	if err != nil {
		return nil, err
	}
	var out []*CandidateNode
	for _, r := range rhs {
