func (e *evaluator) evalNot(node *expressionNode, input *CandidateNode) ([]*CandidateNode, error) {
	// not is a unary function: it operates on the current node
	res, err := e.eval(node.Rhs, input)
	if err != nil {
		return nil, err
	}
	var out []*CandidateNode
	for _, r := range res {
		out = append(out, NewBool(!isTruthy(r)))
