func (e *evaluator) evalBracket(node *expressionNode, input *CandidateNode) ([]*CandidateNode, error) {
	var inputs []*CandidateNode
	if node.Lhs != nil {
		l, err := e.eval(node.Lhs, input)
		if err != nil {
			return nil, err
		}
		inputs = l
	} else {
		inputs = []*CandidateNode{input}
	}
	var out []*CandidateNode
	for _, in := range inputs {
