		if node.isSlice {
			var s, en *CandidateNode
			if node.sliceStart != nil {
				sr, err := e.eval(node.sliceStart, in)
				if err != nil {
					return nil, err
				}
				if len(sr) > 0 {
					s = sr[0]
				}
			}
			if node.sliceEnd != nil {
				er, err := e.eval(node.sliceEnd, in)
				if err != nil {
					return nil, err
