	case opSelf:
		if node.hasField {
			return traverseField([]*CandidateNode{input}, node.fieldName, false)
		}
		return []*CandidateNode{input}, nil
	case opRecursiveDescent:
		return recursiveDescent([]*CandidateNode{input}), nil
