				return []*CandidateNode{c}
			}
		}
		if key.Tag == "!!int" || key.Tag == "!!float" || key.Tag == "!!bool" {
			return []*CandidateNode{NewScalar("!!null", "null", ZeroStyle)}
		}
		return []*CandidateNode{NewScalar("!!null", "null", ZeroStyle)}
	case SequenceNode:
		if key.Tag != "!!int" {
			return nil, errIndexArray(key.Value)
		}
		i, err := strconv.ParseInt(key.Value, 0, 64)
		if err != nil {
			return nil, errIndexArray(key.Value)
		}
		if i < 0 || int(i) >= len(n.Content) {
			return []*CandidateNode{NewScalar("!!null", "null", ZeroStyle)}
		}
		return []*CandidateNode{n.Content[i]}
	}
	return []*CandidateNode{}
}

func errIndexArray(key string) error {
	_, err := strconv.ParseInt(key, 10, 64)
	if err != nil {
		ne := err.(*strconv.NumError)
		return fmt.Errorf("cannot index array with '%s' (strconv.ParseInt: parsing %q: %s)", key, key, ne.Err.Error())
	}
	return fmt.Errorf("cannot index array with '%s'", key)
}

func sliceNode(n *CandidateNode, start *CandidateNode, end *CandidateNode) []*CandidateNode {
	if n == nil {
		return []*CandidateNode{}
	}
	if n.Kind != SequenceNode {
		return []*CandidateNode{}
	}
	s := int64(0)
	if start != nil {
		i, err := strconv.ParseInt(start.Value, 0, 64)
		if err != nil {
			return []*CandidateNode{}
		}
		s = i
	}
	e := int64(len(n.Content))
	if end != nil {
		i, err := strconv.ParseInt(end.Value, 0, 64)
		if err != nil {
			return []*CandidateNode{}
		}
		e = i
	}
	if s < 0 {
		s = 0
	}
	if e > int64(len(n.Content)) {
		e = int64(len(n.Content))
	}
	if s > e {
		s = e
	}
	newNode := NewSeq(n.Tag)
	newNode.Tag = n.Tag
	newNode.Content = n.Content[s:e]
	for _, c := range newNode.Content {
		c.Parent = newNode
	}
	return []*CandidateNode{newNode}
}

func traverseField(nodes []*CandidateNode, name string, optional bool) ([]*CandidateNode, error) {
	var out []*CandidateNode
	for _, n := range nodes {
		if n == nil {
			continue
		}
		switch n.Kind {
		case MappingNode:
			found := false
			for _, c := range n.Content {
				if c.Key != nil && c.Key.Value == name {
					out = append(out, c)
					found = true
					break
				}
			}
			if !found {
				out = append(out, NewScalar("!!null", "null", ZeroStyle))
			}
		case SequenceNode:
			i, err := strconv.ParseInt(name, 0, 64)
			if err != nil {
				ne := err.(*strconv.NumError)
				return nil, fmt.Errorf("cannot index array with '%s' (strconv.ParseInt: parsing %q: %s)", name, name, ne.Err.Error())
			}
			if i < 0 || int(i) >= len(n.Content) {
				out = append(out, NewScalar("!!null", "null", ZeroStyle))
			} else {
				out = append(out, n.Content[i])
			}
		}
	}
	return out, nil
}

func recursiveDescent(n *CandidateNode) []*CandidateNode {
	var out []*CandidateNode
	if n == nil {
		return out
	}
	out = append(out, n)
	switch n.Kind {
	case MappingNode, SequenceNode:
		for _, c := range n.Content {
			out = append(out, recursiveDescent(c)...)
		}
	}
	return out
}

