	if n == nil {
		return "", nil
	}
	// top-level: print document
	if n.Kind == ScalarNode {
		if p.opts.unwrapScalar {
			out := n.Value
			if p.opts.keepComments && n.LineComment != "" {
				out += " # " + strings.SplitN(n.LineComment, "\n", 2)[0]
			}
			return out, nil
		}
	}
	// a document that is an empty map/seq prints nothing
	if n.Kind == MappingNode && len(n.Content) == 0 && n.Style == ZeroStyle && n.Tag == "!!map" && n.HeadComment == "" {
