package yqlib

import (
	"fmt"
	"strconv"
	"strings"
)

func (e *evaluator) evalBinary(node *expressionNode, input *CandidateNode) ([]*CandidateNode, error) {
	switch node.operationType {
	case opAssign:
		return e.evalAssign(node, input, false)
	case opUpdateAssign:
		return e.evalAssign(node, input, true)
	case opAddAssign, opSubtractAssign, opMultiplyAssign:
		return e.evalUpdateArith(node, input)
	case opAdd, opSubtract, opMultiply, opDivide, opModulo:
		lhs, err := e.eval(node.Lhs, input)
		if err != nil {
			return nil, err
		}
		rhs, err := e.eval(node.Rhs, input)
		if err != nil {
			return nil, err
		}
		var out []*CandidateNode
		for _, r := range rhs {
			for _, l := range lhs {
				res, err := applyArith(node.operationType, l, r)
				if err != nil {
					return nil, err
				}
				out = append(out, res)
			}
		}
		return out, nil
	case opEquals, opNotEquals, opLessThan, opLessThanOrEqual, opGreaterThan, opGreaterThanOrEqual:
		lhs, err := e.eval(node.Lhs, input)
		if err != nil {
			return nil, err
		}
		rhs, err := e.eval(node.Rhs, input)
		if err != nil {
			return nil, err
		}
		var out []*CandidateNode
		for _, r := range rhs {
			for _, l := range lhs {
				b, err := compareNodes(node.operationType, l, r)
				if err != nil {
					return nil, err
				}
				out = append(out, NewBool(b))
			}
		}
		return out, nil
	}
	return nil, fmt.Errorf("unhandled operator")
}

func (e *evaluator) evalAssign(node *expressionNode, input *CandidateNode, update bool) ([]*CandidateNode, error) {
	// lhs must have a path
	lhs, err := e.eval(node.Lhs, input)
	if err != nil {
		return nil, err
	}
	var rhsVals []*CandidateNode
	if update {
		rhsVals = []*CandidateNode{input}
	} else {
		rhsVals, err = e.eval(node.Rhs, input)
		if err != nil {
			return nil, err
		}
	}
	var out []*CandidateNode
	for _, r := range rhsVals {
		doc := input.Copy()
		var newRoot *CandidateNode = doc
		for _, l := range lhs {
			path := l.GetPath()
			if len(path) == 0 {
				continue
			}
			newRoot = setPathValue(doc, path, r)
		}
		out = append(out, newRoot)
	}
	return out, nil
}

func setPathValue(root *CandidateNode, path []interface{}, val *CandidateNode) *CandidateNode {
	cur := root
	for i, p := range path {
		switch cur.Kind {
		case MappingNode:
			key := fmt.Sprintf("%v", p)
			found := -1
			for j, c := range cur.Content {
				if c.Key != nil && c.Key.Value == key {
					found = j
					break
				}
			}
			if found < 0 {
				if i == len(path)-1 {
					k := NewScalar("!!str", key, ZeroStyle)
					v := val.Copy()
					v.Key = k
					cur.Content = append(cur.Content, v)
					return root
				}
				// create intermediate map
				k := NewScalar("!!str", key, ZeroStyle)
				nm := NewMap("!!map")
				nm.Key = k
				cur.Content = append(cur.Content, nm)
				cur = nm
				continue
			}
			c := cur.Content[found]
			if i == len(path)-1 {
				nv := val.Copy()
				nv.Key = c.Key
				nv.HeadComment = c.HeadComment
				nv.LineComment = c.LineComment
				nv.FootComment = c.FootComment
				cur.Content[found] = nv
				nv.Parent = cur
				return root
			}
			cur = c
		case SequenceNode:
			idx := -1
			switch pv := p.(type) {
			case int:
				idx = pv
			case string:
				if n, err := strconv.Atoi(pv); err == nil {
					idx = n
				}
			}
			if idx < 0 || idx >= len(cur.Content) {
				if i == len(path)-1 {
					nv := val.Copy()
					cur.Content = append(cur.Content, nv)
					nv.Parent = cur
					return root
				}
				return root
			}
			c := cur.Content[idx]
			if i == len(path)-1 {
				nv := val.Copy()
				cur.Content[idx] = nv
				nv.Parent = cur
				return root
			}
			cur = c
		default:
			// scalar at root: replace
			if i == len(path)-1 {
				return val.Copy()
			}
			nm := NewMap("!!map")
			return root
		}
	}
	return root
}

func (e *evaluator) evalUpdateArith(node *expressionNode, input *CandidateNode) ([]*CandidateNode, error) {
	lhs, err := e.eval(node.Lhs, input)
	if err != nil {
		return nil, err
	}
	var out []*CandidateNode
	doc := input.Copy()
	newRoot := doc
	for _, l := range lhs {
		path := l.GetPath()
		if len(path) == 0 {
			continue
		}
		cur := navigatePath(doc, path)
		if cur == nil {
			continue
		}
		var opRes *CandidateNode
		switch node.operationType {
		case opAddAssign:
			r := cur.Copy()
			r.Key = nil
			r.Parent = nil
			v := NewScalar(cur.Tag, cur.Value, cur.Style)
			opRes, err = applyArith(opAdd, cur, cur)
		case opSubtractAssign:
			opRes, err = applyArith(opAdd, cur, cur)
		case opMultiplyAssign:
			opRes, err = applyArith(opMultiply, cur, cur)
		}
		if err != nil {
			return nil, err
		}
		setPathValue(doc, path, opRes)
	}
	return []*CandidateNode{newRoot}, nil
}

func navigatePath(root *CandidateNode, path []interface{}) *CandidateNode {
	cur := root
	for _, p := range path {
		key := fmt.Sprintf("%v", p)
		switch cur.Kind {
		case MappingNode:
			found := false
			for _, c := range cur.Content {
				if c.Key != nil && c.Key.Value == key {
					cur = c
					found = true
					break
				}
			}
			if !found {
				return nil
			}
		case SequenceNode:
			idx := -1
			switch pv := p.(type) {
			case int:
				idx = pv
			case string:
				if n, err := strconv.Atoi(pv); err == nil {
					idx = n
				}
			}
			if idx < 0 || idx >= len(cur.Content) {
				return nil
			}
			cur = cur.Content[idx]
		default:
			return nil
		}
	}
	return cur
}

func applyArith(op opType, l *CandidateNode, r *CandidateNode) (*CandidateNode, error) {
	lv := nodeValue(l)
	rv := nodeValue(r)
	lt := tagOrKind(l)
	rt := tagOrKind(r)
	switch op {
	case opAdd:
		// strings
		if lt == "!!str" || rt == "!!str" {
			return NewScalar("!!str", scalarString(l)+scalarString(r), ZeroStyle), nil
		}
		if lt == "!!null" {
			return r.Copy(), nil
		}
		if rt == "!!null" {
			return l.Copy(), nil
		}
		if l.Kind == SequenceNode {
			if r.Kind == SequenceNode {
				n := NewSeq("!!seq")
				n.Content = append(n.Content, l.Content...)
				n.Content = append(n.Content, r.Content...)
				return n, nil
			}
			n := NewSeq("!!seq")
			n.Content = append(n.Content, l.Content...)
			n.Content = append(n.Content, r)
			return n, nil
		}
		if l.Kind == MappingNode {
			if r.Kind == MappingNode {
				n := NewMap("!!map")
				n.Content = append(n.Content, l.Content...)
				n.Content = append(n.Content, r.Content...)
				return n, nil
			}
			return nil, fmt.Errorf("%v (%v) cannot be added to a %v (%v)", rt, pathStr(r), lt, pathStr(l))
		}
		if r.Kind == SequenceNode || r.Kind == MappingNode {
			return nil, fmt.Errorf("%v (%v) cannot be added to a %v (%v)", rt, pathStr(r), lt, pathStr(l))
		}
		if lt == "!!bool" || rt == "!!bool" {
			if lt == "!!bool" && rt == "!!bool" {
				return nil, fmt.Errorf("!!bool cannot be added to !!bool")
			}
			if lt == "!!bool" {
				return nil, fmt.Errorf("!!bool cannot be added to %v", rt)
			}
			return nil, fmt.Errorf("%v cannot be added to !!bool", lt)
		}
		return numericOp(opAdd, l, r)
	case opSubtract:
		if l.Kind == SequenceNode {
			if r.Kind == SequenceNode {
				return subtractSeq(l, r), nil
			}
			return nil, fmt.Errorf("%v (%v) cannot be subtracted from %v (%v)", rt, pathStr(r), lt, pathStr(l))
		}
		if l.Kind == MappingNode {
			return nil, fmt.Errorf("maps not yet supported for subtraction")
		}
		if lt == "!!str" || rt == "!!str" {
			if lt == "!!str" && rt == "!!str" {
				return nil, fmt.Errorf("strings cannot be subtracted")
			}
			return nil, fmt.Errorf("%v cannot be added to %v", lt, rt)
		}
		if lt == "!!null" {
			return r.Copy(), nil
		}
		if rt == "!!null" {
			return l.Copy(), nil
		}
		return numericOp(opSubtract, l, r)
	case opMultiply:
		if l.Kind == SequenceNode {
			if r.Kind == SequenceNode {
				return mergeNodes(l, r)
			}
			return nil, fmt.Errorf("cannot multiply %v with %v", lt, rt)
		}
		if l.Kind == MappingNode {
			if r.Kind == MappingNode {
				return mergeNodes(l, r)
			}
			return nil, fmt.Errorf("cannot multiply %v with %v", lt, rt)
		}
		if lt == "!!null" {
			if r.Kind == SequenceNode || r.Kind == MappingNode {
				return r.Copy(), nil
			}
			if rt == "!!null" {
				return NewScalar("!!null", "null", ZeroStyle), nil
			}
			return nil, fmt.Errorf("cannot multiply !!null with %v", rt)
		}
		if rt == "!!null" {
			if lt == "!!str" {
				return l.Copy(), nil
			}
			return l.Copy(), nil
		}
		if lt == "!!str" && rt == "!!int" {
			n, err := strconv.Atoi(r.Value)
			if err != nil {
				return nil, err
			}
			if n < 0 {
				return nil, fmt.Errorf("cannot repeat string by a negative number (%d)", n)
			}
			return NewScalar("!!str", strings.Repeat(l.Value, n), ZeroStyle), nil
		}
		if lt == "!!str" || rt == "!!str" {
			return nil, fmt.Errorf("cannot multiply %v with %v", lt, rt)
		}
		return numericOp(opMultiply, l, r)
	case opDivide:
		if l.Kind == SequenceNode || l.Kind == MappingNode {
			return nil, fmt.Errorf("%v (%v) cannot be divided by %v (%v)", lt, pathStr(l), rt, pathStr(r))
		}
		if r.Kind == SequenceNode || r.Kind == MappingNode {
			return nil, fmt.Errorf("%v (%v) cannot be divided by %v (%v)", lt, pathStr(l), rt, pathStr(r))
		}
		if lt == "!!str" && rt == "!!str" {
			return NewSeq("!!seq"), splitStr(l.Value, r.Value), nil
		}
		if lt != "!!int" && lt != "!!float" || rt != "!!int" && rt != "!!float" {
			return nil, fmt.Errorf("%v cannot be divided by %v", lt, rt)
		}
		return numericOp(opDivide, l, r)
	case opModulo:
		if l.Kind == SequenceNode || l.Kind == MappingNode {
			return nil, fmt.Errorf("%v (%v) cannot modulo by %v (%v)", lt, pathStr(l), rt, pathStr(r))
		}
		if r.Kind == SequenceNode || r.Kind == MappingNode {
			return nil, fmt.Errorf("%v (%v) cannot modulo by %v (%v)", lt, pathStr(l), rt, pathStr(r))
		}
		if lt != "!!int" && lt != "!!float" || rt != "!!int" && rt != "!!float" {
			return nil, fmt.Errorf("%v cannot modulo by %v", lt, rt)
		}
		return numericOp(opModulo, l, r)
	}
	return nil, fmt.Errorf("unhandled")
}

func nodeValue(n *CandidateNode) string {
	if n == nil {
		return "null"
	}
	return n.Value
}

func tagOrKind(n *CandidateNode) string {
	if n == nil {
		return "!!null"
	}
	if n.Tag != "" {
		return n.Tag
	}
	switch n.Kind {
	case SequenceNode:
		return "!!seq"
	case MappingNode:
		return "!!map"
	}
	return "!!str"
}

func pathStr(n *CandidateNode) string {
	if n == nil {
		return ""
	}
	return ""
}

func scalarString(n *CandidateNode) string {
	switch n.Tag {
	case "!!null":
		return ""
	case "!!bool":
		return n.Value
	case "!!int":
		return n.Value
	case "!!float":
		f, err := strconv.ParseFloat(n.Value, 64)
		if err != nil {
			return n.Value
		}
		return strconv.FormatFloat(f, 'g', -1, 64)
	}
	return n.Value
}

func splitStr(s string, sep string) []*CandidateNode {
	var out []*CandidateNode
	parts := strings.Split(s, sep)
	for _, p := range parts {
		out = append(out, NewScalar("!!str", p, ZeroStyle))
	}
	return out
}

func subtractSeq(l *CandidateNode, r *CandidateNode) *CandidateNode {
	n := NewSeq("!!seq")
	for _, c := range l.Content {
		found := false
		for _, d := range r.Content {
			if nodesEqual(c, d) {
				found = true
				break
			}
		}
		if !found {
			n.Content = append(n.Content, c)
		}
	}
	return n
}

func mergeNodes(l *CandidateNode, r *CandidateNode) (*CandidateNode, error) {
	n := NewMap("!!map")
	n.Content = append(n.Content, l.Content...)
	for _, c := range r.Content {
		replaced := false
		for j, d := range n.Content {
			if d.Key != nil && c.Key != nil && d.Key.Value == c.Key.Value {
				n.Content[j] = c
				replaced = true
				break
			}
		}
		if !replaced {
			n.Content = append(n.Content, c)
		}
	}
	return n, nil
}

func nodesEqual(a *CandidateNode, b *CandidateNode) bool {
	if a == nil || b == nil {
		return false
	}
	if a.Kind != b.Kind {
		return false
	}
	switch a.Kind {
	case SequenceNode, MappingNode:
		return false
	}
	return a.Value == b.Value && a.Tag == b.Tag
}

// numericOp performs arithmetic on numeric scalars, preserving radix from lhs text
func numericOp(op opType, l *CandidateNode, r *CandidateNode) (*CandidateNode, error) {
	lIsFloat := l.Tag == "!!float"
	rIsFloat := r.Tag == "!!float"
	if lIsFloat || rIsFloat {
		lf, err := strconv.ParseFloat(l.Value, 64)
		if err != nil {
			return nil, err
		}
		rf, err := strconv.ParseFloat(r.Value, 64)
		if err != nil {
			return nil, err
		}
		var res float64
		switch op {
		case opAdd:
			res = lf + rf
		case opSubtract:
			res = lf - rf
		case opMultiply:
			res = lf * rf
		case opDivide:
			res = lf / rf
		case opModulo:
			res = math.Mod(lf, rf)
		}
		return NewScalar("!!float", formatFloatGo(res), ZeroStyle), nil
	}
	li, err := strconv.ParseInt(l.Value, 0, 64)
	if err != nil {
		return nil, err
	}
	ri, err := strconv.ParseInt(r.Value, 0, 64)
	if err != nil {
		return nil, err
	}
	var res int64
	switch op {
	case opAdd:
		res = li + ri
	case opSubtract:
		res = li - ri
	case opMultiply:
		res = li * ri
	case opDivide:
		res = li / ri
	case opModulo:
		if ri == 0 {
			return nil, fmt.Errorf("cannot modulo by 0")
		}
		res = li % ri
	}
	radix := 10
	lv := l.Value
	if strings.HasPrefix(lv, "0x") || strings.HasPrefix(lv, "0X") {
		radix = 16
	}
	out := strconv.FormatInt(res, radix)
	if radix == 16 {
		out = "0x" + out
	}
	return NewScalar("!!int", out, ZeroStyle), nil
}

func formatFloatGo(f float64) string {
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func compareNodes(op opType, l *CandidateNode, r *CandidateNode) (bool, error) {
	switch op {
	case opEquals, opNotEquals:
		eq := equalsNodes(l, r)
		if op == opEquals {
			return eq, nil
		}
		return !eq, nil
	}
	// ordering
	if l.Tag == "!!null" && r.Tag == "!!null" {
		return op == opLessThanOrEqual || op == opGreaterThanOrEqual, nil
	}
	if l.Tag == "!!bool" || r.Tag == "!!bool" {
		return false, fmt.Errorf("!!bool not yet supported for comparison")
	}
	if l.Kind == SequenceNode || r.Kind == SequenceNode || l.Kind == MappingNode || r.Kind == MappingNode {
		return false, fmt.Errorf("arrays not yet supported for comparison")
	}
	if l.Tag == "!!str" && r.Tag == "!!str" {
		switch op {
		case opLessThan:
			return l.Value < r.Value, nil
		case opLessThanOrEqual:
			return l.Value <= r.Value, nil
		case opGreaterThan:
			return l.Value > r.Value, nil
		case opGreaterThanOrEqual:
			return l.Value >= r.Value, nil
		}
	}
	if l.Tag == "!!int" && r.Tag == "!!int" {
		li, err1 := strconv.ParseInt(l.Value, 0, 64)
		ri, err2 := strconv.ParseInt(r.Value, 0, 64)
		if err1 == nil && err2 == nil {
			switch op {
			case opLessThan:
				return li < ri, nil
			case opLessThanOrEqual:
				return li <= ri, nil
			case opGreaterThan:
				return li > ri, nil
			case opGreaterThanOrEqual:
				return li >= ri, nil
			}
		}
	}
	// mixed: compare as strings
	switch op {
	case opLessThan:
		return l.Value < r.Value, nil
	case opLessThanOrEqual:
		return l.Value <= r.Value, nil
	case opGreaterThan:
		return l.Value > r.Value, nil
	case opGreaterThanOrEqual:
		return l.Value >= r.Value, nil
	}
	return false, nil
}

func equalsNodes(l *CandidateNode, r *CandidateNode) bool {
	if l == nil || r == nil {
		return false
	}
	if l.Kind != r.Kind {
		return false
	}
	switch l.Kind {
	case SequenceNode, MappingNode:
		return false
	}
	return l.Value == r.Value
}

