		rf, err := strconv.ParseFloat(r.Value, 64)
		if err != nil {
			return nil, err
		}
		var res float64
		switch op {
		case opAdd:
			res = lf + rf
		case opSubtract:
			res = lf - rf
		case opMultiply:
			res = lf * rf
		case opDivide:
			res = lf / rf
		case opModulo:
			res = math.Mod(lf, rf)
		}
		return NewScalar("!!float", formatFloatGo(res), ZeroStyle), nil
	}
	li, err := strconv.ParseInt(l.Value, 0, 64)
	if err != nil {
		return nil, err
	}
	ri, err := strconv.ParseInt(r.Value, 0, 64)
	if err != nil {
		return nil, err
	}
	var res int64
	switch op {
	case opAdd:
		res = li + ri
	case opSubtract:
		res = li - ri
	case opMultiply:
		res = li * ri
	case opDivide:
		res = li / ri
	case opModulo:
		if ri == 0 {
			return nil, fmt.Errorf("cannot modulo by 0")
		}
		res = li % ri
	}
	radix := 10
	lv := l.Value
	if strings.HasPrefix(lv, "0x") || strings.HasPrefix(lv, "0X") {
		radix = 16
	}
	out := strconv.FormatInt(res, radix)
	if radix == 16 {
		out = "0x" + out
	}
	return NewScalar("!!int", out, ZeroStyle), nil
}

func formatFloatGo(f float64) string {
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func compareNodes(op opType, l *CandidateNode, r *CandidateNode) (bool, error) {
	switch op {
	case opEquals, opNotEquals:
		eq := equalsNodes(l, r)
		if op == opEquals {
			return eq, nil
		}
		return !eq, nil
	}
	// ordering
	if l.Tag == "!!null" && r.Tag == "!!null" {
		return op == opLessThanOrEqual || op == opGreaterThanOrEqual, nil
	}
	if l.Tag == "!!bool" || r.Tag == "!!bool" {
		return false, fmt.Errorf("!!bool not yet supported for comparison")
	}
	if l.Kind == SequenceNode || r.Kind == SequenceNode || l.Kind == MappingNode || r.Kind == MappingNode {
		return false, fmt.Errorf("arrays not yet supported for comparison")
	}
	if l.Tag == "!!str" && r.Tag == "!!str" {
		switch op {
		case opLessThan:
			return l.Value < r.Value, nil
		case opLessThanOrEqual:
			return l.Value <= r.Value, nil
		case opGreaterThan:
			return l.Value > r.Value, nil
		case opGreaterThanOrEqual:
			return l.Value >= r.Value, nil
		}
	}
	if l.Tag == "!!int" && r.Tag == "!!int" {
		li, err1 := strconv.ParseInt(l.Value, 0, 64)
		ri, err2 := strconv.ParseInt(r.Value, 0, 64)
		if err1 == nil && err2 == nil {
			switch op {
			case opLessThan:
				return li < ri, nil
			case opLessThanOrEqual:
				return li <= ri, nil
			case opGreaterThan:
				return li > ri, nil
			case opGreaterThanOrEqual:
				return li >= ri, nil
			}
		}
	}
	// mixed: compare as strings
	switch op {
	case opLessThan:
		return l.Value < r.Value, nil
	case opLessThanOrEqual:
		return l.Value <= r.Value, nil
	case opGreaterThan:
		return l.Value > r.Value, nil
	case opGreaterThanOrEqual:
		return l.Value >= r.Value, nil
	}
	return false, nil
}

func equalsNodes(l *CandidateNode, r *CandidateNode) bool {
	if l == nil || r == nil {
		return false
	}
	if l.Kind != r.Kind {
		return false
	}
	switch l.Kind {
	case SequenceNode, MappingNode:
		return false
	}
	return l.Value == r.Value
}

var _ = math.Mod
