{"command": "cd /workspace && sed -i 's/^\t_ = rv$//' pkg/yqlib/operators.go && cat > pkg/yqlib/formats.go <<'GOEOF'
package yqlib

import (
	"encoding/base64"
	"fmt"
	"net/url"
	"strconv"
	"strings"
)

func encodeProps(n *CandidateNode, o *printerOptions) string {
	var sb strings.Builder
	emitProps(&sb, n, "", o, false)
	return sb.String()
}

func emitProps(sb *strings.Builder, n *CandidateNode, prefix string, o *printerOptions, inArray bool) {
	if n == nil {
		return
	}
	switch n.Kind {
	case MappingNode:
		for _, c := range n.Content {
			key := c.Key.Value
			if key == "" {
				key = "null"
			}
			newPrefix := key
			if prefix != "" {
				newPrefix = prefix + o.shellKeySeparator + key
			}
			if c.Kind == MappingNode || c.Kind == SequenceNode {
				emitProps(sb, c, newPrefix, o, c.Kind == SequenceNode)
			} else {
				sb.WriteString(newPrefix + o.propertiesSeparator + propValue(c, o) + "\n")
			}
		}
	case SequenceNode:
		for i, c := range n.Content {
			key := strconv.Itoa(i)
			newPrefix := prefix
			if o.propertiesArrayBrackets {
				newPrefix = prefix + "[" + key + "]"
			} else {
				if prefix != "" {
					newPrefix = prefix + o.shellKeySeparator
				}
				newPrefix = newPrefix + key
			}
			if c.Kind == MappingNode || c.Kind == SequenceNode {
				emitProps(sb, c, newPrefix, o, c.Kind == SequenceNode)
			} else {
				sb.WriteString(newPrefix + o.propertiesSeparator + propValue(c, o) + "\n")
			}
		}
	default:
		sb.WriteString(prefix + o.propertiesSeparator + propValue(n, o) + "\n")
	}
}

func propValue(n *CandidateNode, o *printerOptions) string {
	if n == nil {
		return ""
	}
	switch n.Kind {
	case ScalarNode:
		switch n.Tag {
		case "!!null":
			return "null"
		case "!!bool", "!!int", "!!float":
			return n.Value
		}
		if needsQuote(n.Value) {
			return quoteSingle(n.Value)
		}
		return n.Value
	case SequenceNode:
		var sb strings.Builder
		sb.WriteString("[")
		for i, c := range n.Content {
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(propValue(c, o))
		}
		sb.WriteString("]")
		return sb.String()
	case MappingNode:
		var sb strings.Builder
		sb.WriteString("{")
		for i, c := range n.Content {
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(c.Key.Value + ": " + propValue(c, o))
		}
		sb.WriteString("}")
		return sb.String()
	}
	return ""
}

func encodeCSV(n *CandidateNode, o *printerOptions, tsv bool) (string, error) {
	if n == nil || n.Kind != SequenceNode {
		return "", fmt.Errorf("csv encoding only works for arrays, got: %v", tagOrKind(n))
	}
	sep := ","
	if tsv {
		sep = "\t"
	}
	autoParse := o.tsvAutoParse
	if !tsv {
		autoParse = o.csvAutoParse
	}
	header := []string{}
	for _, c := range n.Content {
		if c.Kind != MappingNode {
			return "", fmt.Errorf("csv encoding only works for arrays of maps")
		}
		for _, cc := range c.Content {
			k := cc.Key.Value
			found := false
			for _, h := range header {
				if h == k {
					found = true
					break
				}
			}
			if !found {
				header = append(header, k)
			}
		}
	}
	var sb strings.Builder
	for i, h := range header {
		if i > 0 {
			sb.WriteString(sep)
		}
		sb.WriteString(csvQuote(h, sep))
	}
	sb.WriteString("\n")
	for _, c := range n.Content {
		for i, h := range header {
			if i > 0 {
				sb.WriteString(sep)
			}
			v := ""
			for _, cc := range c.Content {
				if cc.Key != nil && cc.Key.Value == h {
					v = cellValue(cc, autoParse)
					break
			}
			}
			sb.WriteString(csvQuote(v, sep))
		}
		sb.WriteString("\n")
	}
