func encodeProps(n *CandidateNode, o *printerOptions) string {
	var sb strings.Builder
	emitProps(&sb, n, "", o, false)
	return sb.String()
}

func emitProps(sb *strings.Builder, n *CandidateNode, prefix string, o *printerOptions, inArray bool) {
	if n == nil {
		return
	}
	switch n.Kind {
	case MappingNode:
		for _, c := range n.Content {
			key := c.Key.Value
			if key == "" {
				key = "null"
			}
			newPrefix := key
			if prefix != "" {
				newPrefix = prefix + o.shellKeySeparator + key
			}
			if c.Kind == MappingNode || c.Kind == SequenceNode {
				emitProps(sb, c, newPrefix, o, c.Kind == SequenceNode)
			} else {
				sb.WriteString(newPrefix + o.propertiesSeparator + propValue(c, o) + "\n")
			}
		}
	case SequenceNode:
		for i, c := range n.Content {
			key := strconv.Itoa(i)
			newPrefix := prefix
			if o.propertiesArrayBrackets {
				newPrefix = prefix + "[" + key + "]"
			} else {
				if prefix != "" {
					newPrefix = prefix + o.shellKeySeparator
				}
				newPrefix = newPrefix + key
			}
			if c.Kind == MappingNode || c.Kind == SequenceNode {
				emitProps(sb, c, newPrefix, o, c.Kind == SequenceNode)
			} else {
				sb.WriteString(newPrefix + o.propertiesSeparator + propValue(c, o) + "\n")
			}
		}
	default:
		sb.WriteString(prefix + o.propertiesSeparator + propValue(n, o) + "\n")
	}
}

func propValue(n *CandidateNode, o *printerOptions) string {
	if n == nil {
		return ""
	}
	switch n.Kind {
	case ScalarNode:
		switch n.Tag {
		case "!!null":
			return "null"
		case "!!bool", "!!int", "!!float":
			return n.Value
		}
		if needsQuote(n.Value) {
			return quoteSingle(n.Value)
		}
		return n.Value
	case SequenceNode:
		var sb strings.Builder
		sb.WriteString("[")
		for i, c := range n.Content {
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(propValue(c, o))
		}
		sb.WriteString("]")
		return sb.String()
	case MappingNode:
		var sb strings.Builder
		sb.WriteString("{")
		for i, c := range n.Content {
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(c.Key.Value + ": " + propValue(c, o))
		}
		sb.WriteString("}")
		return sb.String()
	}
	return ""
}

func encodeCSV(n *CandidateNode, o *printerOptions, tsv bool) (string, error) {
	if n == nil || n.Kind != SequenceNode {
		return "", fmt.Errorf("csv encoding only works for arrays, got: %v", tagOrKind(n))
	}
	sep := ","
	if tsv {
		sep = "\t"
	}
	autoParse := o.tsvAutoParse
	if !tsv {
		autoParse = o.csvAutoParse
	}
	header := []string{}
	for _, c := range n.Content {
		if c.Kind != MappingNode {
			return "", fmt.Errorf("csv encoding only works for arrays of maps")
		}
		for _, cc := range c.Content {
			k := cc.Key.Value
			found := false
			for _, h := range header {
				if h == k {
					found = true
					break
				}
			}
			if !found {
				header = append(header, k)
			}
		}
	}
	var sb strings.Builder
	for i, h := range header {
		if i > 0 {
			sb.WriteString(sep)
		}
		sb.WriteString(csvQuote(h, sep))
	}
	sb.WriteString("\n")
	for _, c := range n.Content {
		for i, h := range header {
			if i > 0 {
				sb.WriteString(sep)
			}
			v := ""
			for _, cc := range c.Content {
				if cc.Key != nil && cc.Key.Value == h {
					v = cellValue(cc, autoParse)
					break
			}
			}
			sb.WriteString(csvQuote(v, sep))
		}
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

func cellValue(n *CandidateNode, autoParse bool) string {
	if n == nil {
		return ""
	}
	switch n.Kind {
	case ScalarNode:
		switch n.Tag {
		case "!!null":
			return ""
		case "!!bool", "!!int", "!!float":
			return n.Value
		}
		if autoParse {
			return n.Value
		}
		return quoteDouble(n.Value)
	case SequenceNode, MappingNode:
		s, _ := EncodeJSON(n, 0)
		return s
	}
	return ""
}

func csvQuote(v string, sep string) string {
	if strings.ContainsAny(v, sep+"\"\n\r") {
		return "\"" + strings.ReplaceAll(v, "\"", "\"\"") + "\""
	}
	return v
}

func encodeXML(n *CandidateNode, o *printerOptions) string {
	var sb strings.Builder
	emitXML(&sb, n, o, "")
	return sb.String()
}

func emitXML(sb *strings.Builder, n *CandidateNode, o *printerOptions, name string) {
	if n == nil {
		return
	}
	if name == "" {
		// root: emit children as elements
		for _, c := range n.Content {
			emitXML(sb, c, o, c.Key.Value)
		}
		return
	}
	switch n.Kind {
	case ScalarNode:
		switch n.Tag {
		case "!!null":
			sb.WriteString("<" + name + "></" + name + ">")
		default:
			sb.WriteString("<" + name + ">" + xmlEscape(n.Value) + "</" + name + ">")
		}
	case SequenceNode:
		for _, c := range n.Content {
			emitXML(sb, c, o, name)
		}
	case MappingNode:
		attrs := ""
		content := ""
		childTags := ""
		for _, c := range n.Content {
			k := c.Key.Value
			switch {
			case strings.HasPrefix(k, o.xmlAttributePrefix):
				attrs += " " + strings.TrimPrefix(k, o.xmlAttributePrefix) + "=\"" + xmlEscape(c.Value) + "\""
			case k == o.xmlContentName:
				content = c.Value
			default:
				childTags += emitXMLTag(c, o, k)
			}
		}
		sb.WriteString("<" + name + attrs + ">")
		sb.WriteString(content)
		sb.WriteString(childTags)
		sb.WriteString("</" + name + ">")
	}
}

func emitXMLTag(n *CandidateNode, o *printerOptions, name string) string {
	var sb strings.Builder
	emitXML(&sb, n, o, name)
	return sb.String()
}

func xmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	return s
}

func encodeShell(n *CandidateNode, o *printerOptions) string {
	var sb strings.Builder
	emitShell(&sb, n, "", o)
	return sb.String()
}

func emitShell(sb *strings.Builder, n *CandidateNode, prefix string, o *printerOptions) {
	switch n.Kind {
	case MappingNode:
		for _, c := range n.Content {
			k := shellEscapeKey(c.Key.Value, o)
			newPrefix := k
			if prefix != "" {
				newPrefix = prefix + o.shellKeySeparator + k
			}
			if c.Kind == MappingNode || c.Kind == SequenceNode {
				emitShell(sb, c, newPrefix, o)
			} else {
				sb.WriteString(newPrefix + "=" + shellQuoteValue(c) + "\n")
			}
		}
	case SequenceNode:
		for i, c := range n.Content {
			newPrefix := prefix
			if c.Kind == MappingNode || c.Kind == SequenceNode {
				emitShell(sb, c, newPrefix, o)
			} else {
				sb.WriteString(newPrefix + "=" + shellQuoteValue(c) + "\n")
			}
		}
	default:
		sb.WriteString(prefix + "=" + shellQuoteValue(n) + "\n")
	}
}

func shellEscapeKey(k string, o *printerOptions) string {
	return strings.ReplaceAll(k, o.shellKeySeparator, "")
}

func shellQuoteValue(n *CandidateNode) string {
	switch n.Tag {
	case "!!null":
		return "null"
	case "!!bool", "!!int":
		return n.Value
	case "!!float":
		return n.Value
	}
	return "'" + strings.ReplaceAll(n.Value, "'", "'\\''") + "'"
}

func encodeLua(n *CandidateNode, o *printerOptions) string {
	var sb strings.Builder
	sb.WriteString(o.luaPrefix)
	emitLua(&sb, n, o)
	sb.WriteString(o.luaSuffix)
	return sb.String()
}

func emitLua(sb *strings.Builder, n *CandidateNode, o *printerOptions) {
	switch n.Kind {
	case MappingNode:
		if o.luaGlobals {
			for _, c := range n.Content {
				k := c.Key.Value
				if o.luaUnquoted {
					sb.WriteString(k + " = " + luaValue(c) + "\n")
				} else {
					sb.WriteString("[\"" + k + "\"] = " + luaValue(c) + "\n")
				}
			}
			return
		}
		sb.WriteString("{")
		for i, c := range n.Content {
			if i > 0 {
				sb.WriteString(", ")
			}
			if o.luaUnquoted && luaKeyOK(c.Key.Value) {
				sb.WriteString(c.Key.Value + "=")
			} else {
				sb.WriteString("[\"" + c.Key.Value + "\"]=")
			}
			emitLua(sb, c, o)
		}
		sb.WriteString("}")
	case SequenceNode:
		sb.WriteString("{")
		for i, c := range n.Content {
			if i > 0 {
				sb.WriteString(", ")
			}
			emitLua(sb, c, o)
		}
		sb.WriteString("}")
	default:
		sb.WriteString(luaValue(n))
	}
}

func luaKeyOK(k string) bool {
	if k == "" {
		return false
	}
	for i := 0; i < len(k); i++ {
		c := k[i]
		if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c == '_' || (i > 0 && c >= '0' && c <= '9') {
			continue
		}
		return false
	}
	return true
}

func luaValue(n *CandidateNode) string {
	switch n.Kind {
	case ScalarNode:
		switch n.Tag {
		case "!!null":
			return "nil"
		case "!!bool", "!!int", "!!float":
			return n.Value
		}
		return "\"" + n.Value + "\""
	case SequenceNode, MappingNode:
		var sb strings.Builder
		emitLua(&sb, n, nil)
		return sb.String()
	}
	return "nil"
}

func encodeINI(n *CandidateNode, o *printerOptions) string {
	var sb strings.Builder
	for _, c := range n.Content {
		if c.Kind == MappingNode {
			sb.WriteString("[" + c.Key.Value + "]\n")
			for _, cc := range c.Content {
				sb.WriteString(cc.Key.Value + "=" + iniValue(cc) + "\n")
			}
		}
	}
	return sb.String()
}

func iniValue(n *CandidateNode) string {
	switch n.Tag {
	case "!!null":
		return ""
	case "!!bool", "!!int", "!!float":
		return n.Value
	}
	return n.Value
}

func encodeBase64(n *CandidateNode, o *printerOptions) string {
	s, _ := EncodeJSON(n, 0)
	return base64.StdEncoding.EncodeToString([]byte(s))
}

func encodeURI(n *CandidateNode, o *printerOptions) string {
	s, _ := EncodeJSON(n, 0)
	return url.QueryEscape(s)
}

func encodeTOML(n *CandidateNode, o *printerOptions) string {
	var sb strings.Builder
	emitTOML(&sb, n, "", o)
	return sb.String()
}

func emitTOML(sb *strings.Builder, n *CandidateNode, prefix string, o *printerOptions) {
	switch n.Kind {
	case MappingNode:
		for _, c := range n.Content {
			k := c.Key.Value
			newPrefix := k
			if prefix != "" {
				newPrefix = prefix + "." + k
			}
			switch c.Kind {
			case MappingNode:
				sb.WriteString("[" + newPrefix + "]\n")
				emitTOML(sb, c, newPrefix, o)
			case SequenceNode:
				sb.WriteString(k + " = " + tomlValue(c) + "\n")
			default:
				sb.WriteString(k + " = " + tomlValue(c) + "\n")
			}
		}
	}
}

func tomlValue(n *CandidateNode) string {
	switch n.Tag {
	case "!!null":
		return "null"
	case "!!bool", "!!int", "!!float":
		return n.Value
	}
	return "\"" + strings.ReplaceAll(n.Value, "\"", "\\\"") + "\""
}

func encodeHCL(n *CandidateNode, o *printerOptions) string {
	s, _ := EncodeJSON(n, 0)
	return s
}

func encodeKyaml(n *CandidateNode, o *printerOptions) (string, error) {
	s, err := EncodeYAML(n, o.indent, false, false, true)
	if err != nil {
		return "", err
	}
	return strings.ReplaceAll(strings.TrimSuffix(s, "\n"), "\n", "\n"), nil
}
