		return []*CandidateNode{CreateIntScalar(len(input.Value))}, nil
	}
	return []*CandidateNode{CreateIntScalar(0)}, nil
}

func (e *evaluator) fnToString(input *CandidateNode) ([]*CandidateNode, error) {
	switch input.Kind {
	case ScalarNode:
		if input.Tag == "!!null" {
			return []*CandidateNode{CreateStringScalar("")}, nil
		}
		return []*CandidateNode{CreateStringScalar(scalarString(input))}, nil
	}
	return []*CandidateNode{input}, nil
}

func (e *evaluator) fnToNumber(input *CandidateNode) ([]*CandidateNode, error) {
	switch input.Kind {
	case ScalarNode:
		switch input.Tag {
		case "!!int":
			return []*CandidateNode{input}, nil
		case "!!float":
			return []*CandidateNode{input}, nil
		case "!!bool":
			if input.Value == "true" {
				return []*CandidateNode{&CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: "1"}}, nil
			}
			return []*CandidateNode{&CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: "0"}}, nil
		}
		return nil, fmt.Errorf("cannot convert node at path %v of tag %v to number", input.GetPath(), tagOrKind(input))
	}
	return nil, fmt.Errorf("cannot convert node at path %v of tag %v to number", input.GetPath(), tagOrKind(input))
}

