func (e *evaluator) fnMap(input *CandidateNode, exp *expressionNode, valuesOnly bool) ([]*CandidateNode, error) {
	var out []*CandidateNode
	switch input.Kind {
	case SequenceNode:
		seq := NewSeq("!!seq")
		for _, c := range input.Content {
			res, err := e.eval(exp, c)
			if err != nil {
				return nil, err
			}
			if len(res) == 0 {
				continue
			}
			for _, r := range res {
				seq.Content = append(seq.Content, r)
			}
		}
		out = append(out, seq)
	case MappingNode:
		m := NewMap("!!map")
		for _, c := range input.Content {
			res, err := e.eval(exp, c)
			if err != nil {
				return nil, err
			}
			if len(res) == 0 {
				if valuesOnly {
					continue
				}
				continue
			}
			nv := res[0]
			nv.Key = c.Key
			m.Content = append(m.Content, nv)
		}
		out = append(out, m)
	default:
		return nil, fmt.Errorf("cannot map over %v", tagOrKind(input))
	}
	return out, nil
}

func (e *evaluator) fnSelect(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	res, err := e.eval(exp, input)
	if err != nil {
		return nil, err
	}
	var out []*CandidateNode
	for _, r := range res {
		if isTruthy(r) {
			out = append(out, input)
		}
	}
	return out, nil
}

func (e *evaluator) fnHas(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	keys, err := e.eval(exp, input)
	if err != nil {
		return nil, err
	}
	var out []*CandidateNode
	for _, k := range keys {
		switch input.Kind {
		case MappingNode:
			found := false
			for _, c := range input.Content {
				if c.Key != nil && c.Key.Value == k.Value {
					found = true
					break
				}
			}
			out = append(out, NewBool(found))
		case SequenceNode:
			i, err := strconv.Atoi(k.Value)
			if err != nil {
				return nil, fmt.Errorf("cannot check array with '%s'", k.Value)
			}
			out = append(out, NewBool(i >= 0 && i < len(input.Content)))
		default:
			return nil, fmt.Errorf("has only works on maps and arrays")
		}
	}
	return out, nil
}

func (e *evaluator) fnToEntries(input *CandidateNode) ([]*CandidateNode, error) {
	switch input.Kind {
	case MappingNode, SequenceNode:
		seq := NewSeq("!!seq")
		for i, c := range input.Content {
			entry := NewMap("!!map")
			var keyNode *CandidateNode
			if input.Kind == MappingNode {
				if c.Key.Tag == "!!int" {
					keyNode = &CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: c.Key.Value}
				} else {
					keyNode = CreateStringScalar(c.Key.Value)
				}
			} else {
				keyNode = CreateIntScalar(i)
			}
			v := c.Copy()
			v.Key = nil
			v.Parent = nil
			kv := v
			kv.Key = CreateStringScalar("key")
			vv := c
			vv.Key = CreateStringScalar("value")
			entry.Content = []*CandidateNode{kv, vv}
			seq.Content = append(seq.Content, entry)
		}
		return []*CandidateNode{seq}, nil
	}
	return nil, fmt.Errorf("to entries only works for maps and arrays")
}

func (e *evaluator) fnFromEntries(input *CandidateNode) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		return nil, fmt.Errorf("from entries only runs against arrays")
	}
	m := NewMap("!!map")
	for _, c := range input.Content {
		var key *CandidateNode
		var val *CandidateNode
		for _, cc := range c.Content {
			if cc.Key != nil {
				switch cc.Key.Value {
				case "key":
					key = cc
				case "value":
					val = cc
				}
			}
		}
		if key == nil {
			continue
		}
		k := key.Copy()
		k.Key = nil
		v := val.Copy()
		v.Key = k
		m.Content = append(m.Content, v)
	}
	return []*CandidateNode{m}, nil
}

func (e *evaluator) fnWithEntries(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	entries, err := e.fnToEntries(input)
	if err != nil {
		return nil, err
	}
	seq := entries[0]
	for _, c := range seq.Content {
		res, err := e.eval(exp, c)
		if err != nil {
			return nil, err
		}
		if len(res) == 0 {
			continue
		}
		c = res[0]
	}
	return e.fnFromEntries(seq)
}

func (e *evaluator) fnPick(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	keys, err := e.eval(exp, input)
	if err != nil {
		return nil, err
	}
	switch input.Kind {
	case MappingNode:
		m := NewMap("!!map")
		for _, k := range keys {
			for _, c := range input.Content {
				if c.Key != nil && c.Key.Value == k.Value {
					v := c.Copy()
					v.Key = c.Key
					m.Content = append(m.Content, v)
				}
			}
		}
		return []*CandidateNode{m}, nil
	case SequenceNode:
		seq := NewSeq("!!seq")
		for _, k := range keys {
			i, err := strconv.Atoi(k.Value)
			if err == nil && i >= 0 && i < len(input.Content) {
				seq.Content = append(seq.Content, input.Content[i])
			}
		}
		return []*CandidateNode{seq}, nil
	}
	return nil, fmt.Errorf("cannot pick from %v", tagOrKind(input))
}

func (e *evaluator) fnDel(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	res, err := e.eval(exp, input)
	if err != nil {
		return nil, err
	}
	doc := input.Copy()
	paths := [][]interface{}{}
	for _, r := range res {
		paths = append(paths, r.GetPath())
	}
	// delete in reverse order
	for i := len(paths) - 1; i >= 0; i-- {
		deletePath(doc, paths[i])
	}
	return []*CandidateNode{doc}, nil
}

func deletePath(root *CandidateNode, path []interface{}) {
	if len(path) == 0 {
		return
	}
	cur := root
	for i, p := range path {
		key := fmt.Sprintf("%v", p)
		if i == len(path)-1 {
			switch cur.Kind {
			case MappingNode:
				for j, c := range cur.Content {
					if c.Key != nil && c.Key.Value == key {
						cur.Content = append(cur.Content[:j], cur.Content[j+1:]...)
						return
					}
				}
			case SequenceNode:
				idx := -1
				if n, err := strconv.Atoi(key); err == nil {
					idx = n
				}
				if idx >= 0 && idx < len(cur.Content) {
					cur.Content = append(cur.Content[:idx], cur.Content[idx+1:]...)
				}
			}
			return
		}
		switch cur.Kind {
		case MappingNode:
			found := false
			for _, c := range cur.Content {
				if c.Key != nil && c.Key.Value == key {
					cur = c
					found = true
					break
				}
			}
			if !found {
				return
			}
		case SequenceNode:
			idx := -1
			if n, err := strconv.Atoi(key); err == nil {
				idx = n
			}
			if idx < 0 || idx >= len(cur.Content) {
				return
			}
			cur = cur.Content[idx]
		}
	}
}

func (e *evaluator) fnAll(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		return nil, fmt.Errorf("all only supports arrays, was %v", tagOrKind(input))
	}
	if exp == nil {
		out := true
		for _, c := range input.Content {
			if !isTruthy(c) {
				out = false
				break
			}
		}
		return []*CandidateNode{NewBool(out)}, nil
	}
	out := true
	for _, c := range input.Content {
		res, err := e.eval(exp, c)
		if err != nil {
			return nil, err
		}
		anyTruthy := false
		for _, r := range res {
			if isTruthy(r) {
				anyTruthy = true
				break
			}
		}
		if !anyTruthy {
			out = false
			break
		}
	}
	return []*CandidateNode{NewBool(out)}, nil
}

func (e *evaluator) fnAny(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		return nil, fmt.Errorf("any only supports arrays, was %v", tagOrKind(input))
	}
	if exp == nil {
		out := false
		for _, c := range input.Content {
			if isTruthy(c) {
				out = true
				break
			}
		}
		return []*CandidateNode{NewBool(out)}, nil
	}
	out := false
	for _, c := range input.Content {
		res, err := e.eval(exp, c)
		if err != nil {
			return nil, err
		}
		for _, r := range res {
			if isTruthy(r) {
				out = true
				break
			}
		}
	}
	return []*CandidateNode{NewBool(out)}, nil
}

func (e *evaluator) fnSort(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		if input.Kind == MappingNode {
			return []*CandidateNode{input}, nil
		}
		return nil, fmt.Errorf("only arrays are supported for sort")
	}
	c := make([]*CandidateNode, len(input.Content))
	copy(c, input.Content)
	if exp == nil {
		sortNodes(c, func(n *CandidateNode) []*CandidateNode { return []*CandidateNode{n} }, e)
	} else {
		sortNodes(c, func(n *CandidateNode) []*CandidateNode {
			r, err := e.eval(exp, n)
			if err != nil || len(r) == 0 {
				return []*CandidateNode{NewScalar("!!null", "null", ZeroStyle)}
			}
			return r
		}, e)
	}
	seq := NewSeq("!!seq")
	seq.Content = c
	return []*CandidateNode{seq}, nil
}

func sortNodes(list []*CandidateNode, keyfn func(*CandidateNode) []*CandidateNode, e *evaluator) {
	// simple insertion sort using comparison
	for i := 1; i < len(list); i++ {
		for j := i; j > 0; j-- {
			a := keyfn(list[j-1])
			b := keyfn(list[j])
			av := a[0]
			bv := b[0]
			lt, err := compareNodes(opLessThan, av, bv)
			if err != nil {
				break
			}
			if lt {
				break
			}
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
}

func (e *evaluator) fnUnique(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		return nil, fmt.Errorf("only arrays are supported for unique")
	}
	type keyVal struct {
		k []*CandidateNode
		v *CandidateNode
	}
	var items []keyVal
	for _, c := range input.Content {
		var k []*CandidateNode
		if exp == nil {
			k = []*CandidateNode{c}
		} else {
			r, err := e.eval(exp, c)
			if err != nil {
				return nil, err
			}
			k = r
		}
		items = append(items, keyVal{k, c})
	}
	seen := []([]*CandidateNode){}
	seq := NewSeq("!!seq")
	for _, it := range items {
		dup := false
		for _, sk := range seen {
			if keysEqual(sk, it.k) {
				dup = true
				break
			}
		}
		if dup {
			continue
		}
		seen = append(seen, it.k)
		seq.Content = append(seq.Content, it.v)
	}
	return []*CandidateNode{seq}, nil
}

func keysEqual(a []*CandidateNode, b []*CandidateNode) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if !equalsNodes(a[i], b[i]) {
			return false
		}
	}
	return true
}

func (e *evaluator) fnGroupBy(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		return nil, fmt.Errorf("only arrays are supported for group by")
	}
	return nil, fmt.Errorf("only arrays are supported for group by")
