func (e *evaluator) fnReverse(input *CandidateNode) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		return nil, fmt.Errorf("node at path %v is not an array (it's a %v)", input.GetPath(), tagOrKind(input))
	}
	seq := NewSeq("!!seq")
	for i := len(input.Content) - 1; i >= 0; i-- {
		seq.Content = append(seq.Content, input.Content[i])
	}
	return []*CandidateNode{seq}, nil
}

func (e *evaluator) fnFlatten(input *CandidateNode, depth int) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		return nil, fmt.Errorf("only arrays are supported for flatten")
	}
	seq := NewSeq("!!seq")
	var flatten func(n *CandidateNode, d int)
	flatten = func(n *CandidateNode, d int) {
		for _, c := range n.Content {
			if c.Kind == SequenceNode && d > 1 {
				flatten(c, d-1)
				continue
			}
			seq.Content = append(seq.Content, c)
		}
	}
	flatten(input, depth)
	return []*CandidateNode{seq}, nil
}

