func (e *evaluator) fnEval(input *CandidateNode, args []*expressionNode) ([]*CandidateNode, error) {
	if len(args) == 0 {
		return []*CandidateNode{input}, nil
	}
	res, err := e.eval(args[0], input)
	if err != nil {
		return nil, err
	}
	if len(res) == 0 {
		return []*CandidateNode{}, nil
	}
	toks, err := Tokenize(res[0].Value)
