func (e *evaluator) fnKeys(input *CandidateNode) ([]*CandidateNode, error) {
	var out []*CandidateNode
	switch input.Kind {
	case MappingNode:
		seq := NewSeq("!!seq")
		for _, c := range input.Content {
			if c.Key == nil {
				continue
			}
			k := CreateStringScalar(c.Key.Value)
			k.Style = c.Key.Style
			if c.Key.Tag == "!!int" {
				k = &CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: c.Key.Value}
			}
			seq.Content = append(seq.Content, k)
		}
		out = append(out, seq)
	case SequenceNode:
		seq := NewSeq("!!seq")
		for i := range input.Content {
			seq.Content = append(seq.Content, CreateIntScalar(i))
		}
		out = append(out, seq)
	default:
		return nil, fmt.Errorf("cannot get keys of %v, keys only works for maps and arrays", tagOrKind(input))
	}
	return out, nil
}

func (e *evaluator) fnLength(input *CandidateNode) ([]*CandidateNode, error) {
	switch input.Kind {
	case MappingNode, SequenceNode:
		return []*CandidateNode{CreateIntScalar(len(input.Content))}, nil
	case ScalarNode:
		switch input.Tag {
		case "!!null":
			return []*CandidateNode{CreateIntScalar(0)}, nil
		}
		return []*CandidateNode{CreateIntScalar(len(input.Value))}, nil
	}
	return []*CandidateNode{CreateIntScalar(0)}, nil
}

func (e *evaluator) fnToString(input *CandidateNode) ([]*CandidateNode, error) {
	switch input.Kind {
	case ScalarNode:
		if input.Tag == "!!null" {
			return []*CandidateNode{CreateStringScalar("")}, nil
		}
		return []*CandidateNode{CreateStringScalar(scalarString(input))}, nil
	}
	return []*CandidateNode{input}, nil
}

func (e *evaluator) fnToNumber(input *CandidateNode) ([]*CandidateNode, error) {
	switch input.Kind {
	case ScalarNode:
		switch input.Tag {
		case "!!int":
			return []*CandidateNode{input}, nil
		case "!!float":
			return []*CandidateNode{input}, nil
		case "!!bool":
			if input.Value == "true" {
				return []*CandidateNode{&CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: "1"}}, nil
			}
			return []*CandidateNode{&CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: "0"}}, nil
		}
		return nil, fmt.Errorf("cannot convert node at path %v of tag %v to number", input.GetPath(), tagOrKind(input))
	}
	return nil, fmt.Errorf("cannot convert node at path %v of tag %v to number", input.GetPath(), tagOrKind(input))
}

