func (e *evaluator) fnSplit(input *CandidateNode, args []*expressionNode) ([]*CandidateNode, error) {
	s, err := e.eval(args[0], input)
	if err != nil {
		return nil, err
	}
	if len(s) == 0 {
		return []*CandidateNode{NewSeq("!!seq")}, nil
	}
	if input.Tag != "!!str" {
		return nil, fmt.Errorf("cannot split %v, can only split strings", tagOrKind(input))
	}
	sep := s[0].Value
	parts := strings.Split(input.Value, sep)
	seq := NewSeq("!!seq")
	for _, p := range parts {
		seq.Content = append(seq.Content, CreateStringScalar(p))
	}
	return []*CandidateNode{seq}, nil
}

func (e *evaluator) fnJoin(input *CandidateNode, exp *expressionNode) ([]*CandidateNode, error) {
	if input.Kind != SequenceNode {
		return nil, fmt.Errorf("cannot join with %v, can only join arrays of scalars", tagOrKind(input))
	}
	sep, err := e.eval(exp, input)
	if err != nil {
		return nil, err
	}
	if len(sep) == 0 {
		return []*CandidateNode{CreateStringScalar("")}, nil
	}
	var parts []string
	for _, c := range input.Content {
		if c.Kind != ScalarNode {
			return nil, fmt.Errorf("cannot join with %v, can only join arrays of scalars", tagOrKind(input))
		}
		parts = append(parts, c.Value)
	}
	return []*CandidateNode{CreateStringScalar(strings.Join(parts, sep[0].Value))}, nil
}

func compileRegex(args []*expressionNode, input *CandidateNode, e *evaluator) (*regexp.Regexp, error) {
	if len(args) == 0 {
		return nil, fmt.Errorf("no regex given")
	}
	res, err := e.eval(args[0], input)
	if err != nil {
		return nil, err
	}
	if len(res) == 0 {
		return nil, fmt.Errorf("no regex given")
	}
	pattern := res[0].Value
	flags := ""
	if len(args) > 1 {
		fres, err := e.eval(args[1], input)
		if err != nil {
			return nil, err
		}
		if len(fres) > 0 {
			flags = fres[0].Value
		}
	}
	expr := pattern
	if strings.Contains(flags, "i") {
		expr = "(?i)" + expr
	}
	if strings.Contains(flags, "s") {
		expr = "(?s)" + expr
	}
	if strings.Contains(flags, "m") {
		expr = "(?m)" + expr
	}
	re, err := regexp.Compile(expr)
	if err != nil {
		return nil, err
	}
	return re, nil
}

func (e *evaluator) fnTest(input *CandidateNode, args []*expressionNode) ([]*CandidateNode, error) {
	if input.Tag != "!!str" {
		return nil, fmt.Errorf("cannot test %v, can only test strings", tagOrKind(input))
	}
	re, err := compileRegex(args, input, e)
	if err != nil {
		return nil, err
	}
	return []*CandidateNode{NewBool(re.MatchString(input.Value))}, nil
}

func (e *evaluator) fnMatch(input *CandidateNode, args []*expressionNode) ([]*CandidateNode, error) {
	if input.Tag != "!!str" {
		return nil, fmt.Errorf("cannot match %v, can only match strings", tagOrKind(input))
	}
	re, err := compileRegex(args, input, e)
	if err != nil {
		return nil, err
	}
	locs := re.FindStringSubmatchIndex(input.Value)
	seq := NewSeq("!!seq")
	for len(locs) > 0 {
		entry := NewMap("!!map")
		appendKV(entry, "string", CreateStringScalar(input.Value[locs[0]:locs[1]]))
		appendKV(entry, "offset", CreateIntScalar(locs[0]))
		appendKV(entry, "length", CreateIntScalar(locs[1]-locs[0]))
		caps := NewSeq("!!seq")
		for i := 2; i < len(locs); i += 2 {
			if locs[i] < 0 {
				continue
			}
			caps.Content = append(caps.Content, CreateStringScalar(input.Value[locs[i]:locs[i+1]]))
		}
		capsEntry := caps
		capsEntry.Key = CreateStringScalar("captures")
		entry.Content = append(entry.Content, capsEntry)
		seq.Content = append(seq.Content, entry)
		// only first match
		break
	}
	return []*CandidateNode{seq}, nil
}

func appendKV(m *CandidateNode, k string, v *CandidateNode) {
	kn := CreateStringScalar(k)
	v.Key = kn
	m.Content = append(m.Content, v)
}

func (e *evaluator) fnCapture(input *CandidateNode, args []*expressionNode) ([]*CandidateNode, error) {
	if input.Tag != "!!str" {
		return nil, fmt.Errorf("cannot capture %v, can only capture strings", tagOrKind(input))
	}
	re, err := compileRegex(args, input, e)
	if err != nil {
		return nil, err
	}
	names := re.SubexpNames()
	locs := re.FindStringSubmatchIndex(input.Value)
	seq := NewSeq("!!seq")
	for i := 2; i < len(locs); i += 2 {
		if locs[i] < 0 {
			continue
		}
		name := ""
		if i/2 < len(names) {
			name = names[i/2]
		}
		val := input.Value[locs[i]:locs[i+1]]
		v := CreateStringScalar(val)
		v.Key = CreateStringScalar(name)
		seq.Content = append(seq.Content, v)
	}
	return []*CandidateNode{seq}, nil
}

func (e *evaluator) fnSub(input *CandidateNode, args []*expressionNode) ([]*CandidateNode, error) {
	if input.Tag != "!!str" {
		return nil, fmt.Errorf("cannot substitute with %v, can only substitute strings.", tagOrKind(input))
	}
	re, err := compileRegex(args[:1], input, e)
	if err != nil {
		return nil, err
	}
	replRes, err := e.eval(args[1], input)
	if err != nil {
		return nil, err
	}
	if len(replRes) == 0 {
		return []*CandidateNode{CreateStringScalar("")}, nil
	}
	replacement := replRes[0].Value
	if len(args) > 2 {
		fres, err := e.eval(args[2], input)
		if err != nil {
			return nil, err
		}
		if len(fres) > 0 && strings.Contains(fres[0].Value, "g") {
			out := re.ReplaceAllString(input.Value, replacement)
			return []*CandidateNode{CreateStringScalar(out)}, nil
		}
		// non-global: remove first match
		loc := re.FindStringIndex(input.Value)
		if loc == nil {
			return []*CandidateNode{CreateStringScalar(input.Value)}, nil
		}
		out := input.Value[:loc[0]] + replacement + input.Value[loc[1]:]
		return []*CandidateNode{CreateStringScalar(out)}, nil
	}
	loc := re.FindStringIndex(input.Value)
	if loc == nil {
		return []*CandidateNode{CreateStringScalar(input.Value)}, nil
	}
	out := input.Value[:loc[0]] + replacement + input.Value[loc[1]:]
	return []*CandidateNode{CreateStringScalar(out)}, nil
}

