	if loc == nil {
		return []*CandidateNode{CreateStringScalar(input.Value)}, nil
	}
	out := input.Value[:loc[0]] + replacement + input.Value[loc[1]:]
	return []*CandidateNode{CreateStringScalar(out)}, nil
}

