func (j *jsonParser) parseString() (string, error) {
	j.pos++ // "
	var sb strings.Builder
	for j.pos < len(j.data) {
		c := j.data[j.pos]
		if c == '"' {
			j.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			j.pos++
			if j.pos >= len(j.data) {
				return "", fmt.Errorf("invalid json")
			}
			e := j.data[j.pos]
			j.pos++
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case 'b':
				sb.WriteByte(8)
			case 'f':
				sb.WriteByte(12)
			case '/':
				sb.WriteByte('/')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'u':
				if j.pos+4 > len(j.data) {
					return "", fmt.Errorf("invalid json")
				}
				v, err := strconv.ParseUint(j.data[j.pos:j.pos+4], 16, 32)
				if err != nil {
					return "", fmt.Errorf("invalid json")
				}
				sb.WriteRune(runei(v))
				j.pos += 4
			default:
				sb.WriteByte(e)
			}
			continue
		}
		sb.WriteByte(c)
		j.pos++
	}
	return "", fmt.Errorf("invalid json")
}

func (j *jsonParser) parseArray() (*CandidateNode, error) {
	j.pos++ // [
	seq := NewSeq("!!seq")
	for {
		j.skipWS()
		if j.pos >= len(j.data) {
			return nil, fmt.Errorf("invalid json")
		}
		if j.data[j.pos] == ']' {
			j.pos++
			break
		}
		v, err := j.parseValue()
		if err != nil {
			return nil, err
		}
		seq.Content = append(seq.Content, v)
		j.skipWS()
		if j.pos >= len(j.data) {
			return nil, fmt.Errorf("invalid json")
		}
