		if j.pos >= len(j.data) {
			return nil, fmt.Errorf("invalid json")
		}
		if j.data[j.pos] == ',' {
			j.pos++
			continue
		}
		if j.data[j.pos] == '}' {
			j.pos++
			break
		}
		return nil, fmt.Errorf("invalid json")
	}
	return m, nil
}
