// ParseCSV parses csv/tsv into a sequence of maps
func ParseCSV(data []byte, tsv bool) ([]*CandidateNode, error) {
	sep := ","
	if tsv {
		sep = "\t"
	}
	text := string(data)
	rows := strings.Split(strings.TrimRight(text, "\n"), "\n")
	if len(rows) == 0 || rows[0] == "" {
		return nil, fmt.Errorf("EOF")
	}
	var header []string
	// naive split handling quotes
	splitLine := func(line string) []string {
		var out []string
		var cur strings.Builder
		inQuote := false
		for i := 0; i < len(line); i++ {
			c := line[i]
			if c == '"' {
				if inQuote && i+1 < len(line) && line[i+1] == '"' {
					cur.WriteByte('"')
					i++
					continue
				}
				inQuote = !inQuote
				continue
			}
			if c == sep[0] && !inQuote {
				out = append(out, cur.String())
				cur.Reset()
				continue
			}
			cur.WriteByte(c)
		}
		out = append(out, cur.String())
		return out
	}
	header = splitLine(rows[0])
	seq := NewSeq("!!seq")
	for _, row := range rows[1:] {
		if row == "" {
			continue
		}
		vals := splitLine(row)
		m := NewMap("!!map")
		for i, h := range header {
			var v string
			if i < len(vals) {
				v = vals[i]
			}
			k := NewScalar("!!str", h, ZeroStyle)
			n := resolveScalar(v)
			if n.Tag == "!!null" {
				n.Value = ""
			}
			n.Key = k
			m.Content = append(m.Content, n)
		}
		seq.Content = append(seq.Content, m)
	}
