// ParseXML parses xml into a candidate node
func ParseXML(data []byte, skipProcInst bool, skipDirectives bool, strict bool) ([]*CandidateNode, error) {
	root := NewMap("!!map")
	cur := root
	var stack []*CandidateNode
	pos := 0
	text := string(data)
	for pos < len(text) {
		lt := strings.IndexByte(text[pos:], '<')
		if lt < 0 {
			break
		}
		// preceding text
		if lt > 0 {
			t := strings.TrimSpace(text[pos : pos+lt])
			if t != "" {
				cn := NewScalar(o_xmlContentName, t, ZeroStyle)
				cn.Key = NewScalar("!!str", o_xmlContentName, ZeroStyle)
				cur.Content = append(cur.Content, cn)
			}
		}
		pos += lt
		if strings.HasPrefix(text[pos:], "<!--") {
			end := strings.Index(text[pos:], "-->")
			if end < 0 {
				break
			}
			pos += end + 3
			continue
		}
		if strings.HasPrefix(text[pos:], "<?") {
			end := strings.Index(text[pos:], "?>")
			if end < 0 {
				break
			}
			pos += end + 2
			continue
		}
		if strings.HasPrefix(text[pos:], "<!") {
			end := strings.IndexByte(text[pos:], '>')
			if end < 0 {
				break
			}
			pos += end + 1
			continue
		}
		end := strings.IndexByte(text[pos:], '>')
		if end < 0 {
			break
		}
		tag := text[pos+1 : pos+end]
		pos += end + 1
		if strings.HasPrefix(tag, "/") {
			name := strings.TrimSpace(tag[1:])
			if len(stack) > 0 {
				cur = stack[len(stack)-1]
				stack = stack[:len(stack)-1]
			}
			_ = name
			continue
		}
		selfClose := strings.HasSuffix(tag, "/")
		if selfClose {
			tag = strings.TrimSuffix(tag, "/")
		}
		name := tag
		attrs := ""
		if idx := strings.IndexByte(tag, ' '); idx >= 0 {
			name = tag[:idx]
			attrs = tag[idx+1:]
		}
		node := NewMap("!!map")
		node.Key = NewScalar("!!str", name, ZeroStyle)
		// attributes
		for len(attrs) > 0 {
			attrs = strings.TrimSpace(attrs)
			if attrs == "" {
				break
			}
			eq := strings.IndexByte(attrs, '=')
			if eq < 0 {
				break
			}
			aname := strings.TrimSpace(attrs[:eq])
			rest := strings.TrimSpace(attrs[eq+1:])
			quote := byte('"')
			if len(rest) > 0 && rest[0] == '\'' {
				quote = '\''
			}
			val := ""
			if len(rest) > 0 && rest[0] == quote {
				endIdx := strings.IndexByte(rest[1:], quote)
				if endIdx < 0 {
					break
				}
				val = rest[1 : 1+endIdx]
				attrs = rest[2+endIdx:]
			} else {
				val = rest
				attrs = ""
			}
			ak := NewScalar("!!str", o_xmlAttributePrefix+aname, ZeroStyle)
			av := NewScalar("!!str", val, ZeroStyle)
			av.Key = ak
			node.Content = append(node.Content, av)
		}
		cur.Content = append(cur.Content, node)
		if !selfClose {
			stack = append(stack, cur)
			cur = node
		}
	}
	return []*CandidateNode{root}, nil
}

const o_xmlContentName = "+content"
const o_xmlAttributePrefix = "+@"

// ParseJSON parses json into candidate nodes
func ParseJSON(data []byte) ([]*CandidateNode, error) {
	trimmed := strings.TrimSpace(string(data))
	if trimmed == "" {
		return nil, fmt.Errorf("EOF")
	}
	jp := &jsonParser{data: trimmed}
	n, err := jp.parseValue()
	if err != nil {
		return nil, err
	}
	jp.skipWS()
	if jp.pos < len(jp.data) {
		return nil, fmt.Errorf("invalid json")
	}
	return []*CandidateNode{n}, nil
}

type jsonParser struct {
	data string
	pos  int
}

func (j *jsonParser) skipWS() {
	for j.pos < len(j.data) {
		c := j.data[j.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			j.pos++
			continue
		}
		break
	}
}

func (j *jsonParser) parseValue() (*CandidateNode, error) {
	j.skipWS()
	if j.pos >= len(j.data) {
		return nil, fmt.Errorf("EOF")
	}
	c := j.data[j.pos]
	switch c {
	case '{':
		return j.parseObject()
	case '[':
		return j.parseArray()
	case '"':
		s, err := j.parseString()
		if err != nil {
			return nil, err
		}
		n := NewScalar("!!str", s, DoubleQuotedStyle)
		return n, nil
	case 't':
		if strings.HasPrefix(j.data[j.pos:], "true") {
			j.pos += 4
			return NewScalar("!!bool", "true", ZeroStyle), nil
		}
		return nil, fmt.Errorf("invalid json")
	case 'f':
		if strings.HasPrefix(j.data[j.pos:], "false") {
			j.pos += 5
			return NewScalar("!!bool", "false", ZeroStyle), nil
		}
		return nil, fmt.Errorf("invalid json")
	case 'n':
		if strings.HasPrefix(j.data[j.pos:], "null") {
			j.pos += 4
			return NewScalar("!!null", "null", ZeroStyle), nil
		}
		return nil, fmt.Errorf("invalid json")
	default:
		start := j.pos
		if c == '-' || c == '+' {
			j.pos++
		}
		digits := 0
		for j.pos < len(j.data) {
			ch := j.data[j.pos]
			if ch >= '0' && ch <= '9' {
				digits++
				j.pos++
				continue
			}
			break
		}
		isFloat := false
		if j.pos < len(j.data) && j.data[j.pos] == '.' {
			isFloat = true
			j.pos++
			for j.pos < len(j.data) && j.data[j.pos] >= '0' && j.data[j.pos] <= '9' {
				j.pos++
			}
		}
		if j.pos < len(j.data) && (j.data[j.pos] == 'e' || j.data[j.pos] == 'E') {
			isFloat = true
			j.pos++
			if j.pos < len(j.data) && (j.data[j.pos] == '+' || j.data[j.pos] == '-') {
				j.pos++
			}
			for j.pos < len(j.data) && j.data[j.pos] >= '0' && j.data[j.pos] <= '9' {
				j.pos++
			}
		}
		if digits == 0 {
			return nil, fmt.Errorf("invalid json")
		}
		v := j.data[start:j.pos]
		tag := "!!int"
		if isFloat {
			tag = "!!float"
		}
		return NewScalar(tag, v, ZeroStyle), nil
	}
}

func (j *jsonParser) parseString() (string, error) {
	j.pos++ // "
	var sb strings.Builder
	for j.pos < len(j.data) {
		c := j.data[j.pos]
		if c == '"' {
			j.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			j.pos++
			if j.pos >= len(j.data) {
				return "", fmt.Errorf("invalid json")
			}
			e := j.data[j.pos]
			j.pos++
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case 'b':
				sb.WriteByte(8)
			case 'f':
				sb.WriteByte(12)
			case '/':
				sb.WriteByte('/')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'u':
				if j.pos+4 > len(j.data) {
					return "", fmt.Errorf("invalid json")
				}
				v, err := strconv.ParseUint(j.data[j.pos:j.pos+4], 16, 32)
				if err != nil {
					return "", fmt.Errorf("invalid json")
				}
				sb.WriteRune(runei(v))
				j.pos += 4
			default:
				sb.WriteByte(e)
			}
			continue
		}
		sb.WriteByte(c)
		j.pos++
	}
	return "", fmt.Errorf("invalid json")
}

func (j *jsonParser) parseArray() (*CandidateNode, error) {
	j.pos++ // [
	seq := NewSeq("!!seq")
	for {
		j.skipWS()
		if j.pos >= len(j.data) {
			return nil, fmt.Errorf("invalid json")
		}
		if j.data[j.pos] == ']' {
			j.pos++
			break
		}
		v, err := j.parseValue()
		if err != nil {
			return nil, err
		}
		seq.Content = append(seq.Content, v)
		j.skipWS()
		if j.pos >= len(j.data) {
			return nil, fmt.Errorf("invalid json")
		}
		if j.data[j.pos] == ',' {
			j.pos++
			continue
		}
		if j.data[j.pos] == ']' {
			j.pos++
			break
		}
		return nil, fmt.Errorf("invalid json")
	}
	return seq, nil
}

func (j *jsonParser) parseObject() (*CandidateNode, error) {
	j.pos++ // {
	m := NewMap("!!map")
	for {
		j.skipWS()
		if j.pos >= len(j.data) {
			return nil, fmt.Errorf("invalid json")
		}
		if j.data[j.pos] == '}' {
			j.pos++
			break
		}
		if j.data[j.pos] != '"' {
			return nil, fmt.Errorf("invalid json")
		}
		k, err := j.parseString()
		if err != nil {
			return nil, err
		}
		j.skipWS()
		if j.pos >= len(j.data) || j.data[j.pos] != ':' {
			return nil, fmt.Errorf("invalid json")
		}
		j.pos++
		v, err := j.parseValue()
		if err != nil {
			return nil, err
		}
		kn := NewScalar("!!str", k, DoubleQuotedStyle)
		v.Key = kn
		m.Content = append(m.Content, v)
		j.skipWS()
		if j.pos >= len(j.data) {
			return nil, fmt.Errorf("invalid json")
		}
		if j.data[j.pos] == ',' {
			j.pos++
			continue
		}
		if j.data[j.pos] == '}' {
			j.pos++
			break
		}
		return nil, fmt.Errorf("invalid json")
	}
	return m, nil
}
