	if len(pa.positional) != 1 {
		fmt.Fprintln(os.Stderr, "Error: accepts 1 arg(s), received "+strconv.Itoa(len(pa.positional)))
		fmt.Fprintln(os.Stderr, completionHelpText)
		return 1
	}
