		if err != nil {
			fmt.Fprintln(os.Stderr, "Error: "+err.Error())
			return 1
		}
		if len(toks) == 0 {
			exprNode = nil
		} else {
			node, err := yqlib.ParseExpression(toks)
			if err != nil {
