			warnOnce("yq default output is now 'auto' (based on the filename extension). Normally yq would output 'yaml', but for backwards compatibility 'yaml' has been set. Please use -oy to specify yaml, or drop the -p flag.")
			outputFormat = "yaml"
		} else if len(files) > 0 {
			outputFormat = detectFormatFromFilename(files[0])
			if outputFormat == "" {
				outputFormat = "yaml"
			}
		} else {
			outputFormat = "yaml"
		}
	}
	if inputFormat == "auto" {
		if len(files) > 0 {
			inputFormat = detectFormatFromFilename(files[0])
			if inputFormat == "" {
				inputFormat = "yaml"
			}
		}
	}
	opts := &yqlib.PrinterOptions{
		OutputFormat: outputFormat,
		Indent:       v.getInt("indent"),
		UnwrapScalar: v.getBool("unwrapScalar"),
		KeepComments: !v.getBool("unwrapScalar"),
		Colors:       v.getBool("colors") && !v.getBool("no-colors"),
		NoDoc:        v.getBool("no-doc"),
		NulOutput:    v.getBool("nul-output"),
		PrettyPrint:  v.getBool("prettyPrint"),
		PropertiesArrayBrackets: v.getBool("properties-array-brackets"),
		PropertiesSeparator:     v.getString("properties-separator"),
		ShellKeySeparator:       v.getString("shell-key-separator"),
		XmlAttributePrefix:      v.getString("xml-attribute-prefix"),
		XmlContentName:          v.getString("xml-content-name"),
		XmlDirectiveName:        v.getString("xml-directive-name"),
		XmlKeepNamespace:        v.getBool("xml-keep-namespace"),
		XmlProcInstPrefix:       v.getString("xml-proc-inst-prefix"),
		XmlRawToken:             v.getBool("xml-raw-token"),
		XmlSkipDirectives:       v.getBool("xml-skip-directives"),
		XmlSkipProcInst:         v.getBool("xml-skip-proc-inst"),
		XmlStrictMode:           v.getBool("xml-strict-mode"),
		LuaGlobals:              v.getBool("lua-globals"),
		LuaPrefix:               v.getString("lua-prefix"),
		LuaSuffix:               v.getString("lua-suffix"),
		LuaUnquoted:             v.getBool("lua-unquoted"),
		CsvSeparator:            v.getString("csv-separator"),
		CsvAutoParse:            v.getBool("csv-auto-parse"),
		TsvAutoParse:            v.getBool("tsv-auto-parse"),
		SplitExp:                v.getString("split-exp"),
		SplitExpFile:            v.getString("split-exp-file"),
		ExitStatus:              v.getBool("exit-status"),
		FrontMatter:             v.getString("front-matter"),
		SecurityDisableEnvOps:    v.getBool("security-disable-env-ops"),
		SecurityDisableFileOps:   v.getBool("security-disable-file-ops"),
		SecurityEnableSystemOperator: v.getBool("security-enable-system-operator"),
		StringInterpolation:         v.getBool("string-interpolation"),
		YamlCompactSeqIndent:        v.getBool("yaml-compact-seq-indent"),
		YamlFixMergeAnchorToSpec:    v.getBool("yaml-fix-merge-anchor-to-spec"),
		DebugNodeInfo:               v.getBool("debug-node-info"),
		Verbose:                     v.getBool("verbose"),
		HeaderPreprocess:            v.getBool("header-preprocess"),
		Inplace:                     v.getBool("inplace"),
	}
	// expression
	if !v.getBool("null-input") && len(files) == 0 && expression == "" && !hasStdin {
		fmt.Fprint(os.Stdout, evalUsageText(evalAll))
		return 0
	}
	var exprNode *yqlib.ExpressionNode
	var expr *yqlib.TokenStream
	if expression != "" {
		toks, err := yqlib.Tokenize(expression)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Error: "+err.Error())
			return 1
		}
		if len(toks) == 0 {
			exprNode = nil
		} else {
			node, err := yqlib.ParseExpression(toks)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error: "+yqlib.ParseErrorMessage(err))
				return 1
			}
			exprNode = node
		}
	}
	input := yqlib.NewNullDocument()
	if !v.getBool("null-input") {
		if len(files) == 0 {
			data, err := readStdin()
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error: "+err.Error())
				return 1
			}
			if inputFormat == "auto" {
				inputFormat = detectFormatFromContent(data)
			}
			docs, err := parseInput(data, inputFormat)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error: bad file '-': "+err.Error())
				return 1
			}
			_ = docs
		}
	}
	_ = expr
	_ = input
	_ = opts
	return evaluateAll(evalAll, expression, files, inputFormat, outputFormat, opts, hasStdin)
}

func rootUsageText() string {
	s := rootHelpText
	idx := strings.Index(s, "Usage:")
	if idx < 0 {
		return s
	}
	return s[idx:]
}

func evalUsageText(evalAll bool) string {
	s := evalHelpText
	if evalAll {
		s = evalAllHelpText
	}
	idx := strings.Index(s, "Usage:")
	if idx < 0 {
		return s
	}
	return s[idx:] + "\n"
}

func stdinIsPipe() bool {
	st, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return (st.Mode() & os.ModeCharDevice) == 0
}

func readStdin() ([]byte, error) {
	buf := make([]byte, 0, 4096)
	tmp := make([]byte, 4096)
	for {
		n, err := os.Stdin.Read(tmp)
		buf = append(buf, tmp[:n]...)
		if err != nil {
			break
		}
	}
	return buf, nil
}

func warnOnce(msg string) {
	fmt.Fprintln(os.Stderr, slogLine("WARN", msg))
}

func slogLine(level string, msg string) string {
	return "time=" + yqlib.NowRFC3339() + " level=" + level + " msg=" + fmt.Sprintf("%q", msg)
}

func detectFormatFromFilename(filename string) string {
	lower := strings.ToLower(filename)
	switch {
	case strings.HasSuffix(lower, ".json"):
		return "json"
	case strings.HasSuffix(lower, ".yaml"), strings.HasSuffix(lower, ".yml"):
		return "yaml"
	case strings.HasSuffix(lower, ".xml"):
		return "xml"
	case strings.HasSuffix(lower, ".props"), strings.HasSuffix(lower, ".properties"):
		return "props"
	case strings.HasSuffix(lower, ".csv"):
		return "csv"
	case strings.HasSuffix(lower, ".tsv"):
		return "tsv"
	case strings.HasSuffix(lower, ".toml"):
		return "toml"
	case strings.HasSuffix(lower, ".hcl"):
		return "hcl"
	case strings.HasSuffix(lower, ".lua"):
		return "lua"
	case strings.HasSuffix(lower, ".ini"):
		return "ini"
	}
	return ""
}

func detectFormatFromContent(data []byte) string {
	s := strings.TrimLeft(string(data), " \t\r\n")
	if s == "" {
		return "yaml"
	}
	switch s[0] {
	case '{', '[':
		return "json"
	case '<':
		return "xml"
	}
	first := s
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		first = s[:i]
	}
	if strings.Contains(first, ",") && strings.Contains(first, "=") == false && !strings.Contains(first, ":") {
		return "csv"
	}
	if strings.Contains(first, "\t") {
		return "tsv"
	}
	if strings.Contains(first, "=") {
		if strings.Contains(first, " = ") {
			return "toml"
		}
		return "props"
	}
	return "yaml"
}

func parseInput(data []byte, format string) ([]*yqlib.CandidateNode, error) {
	switch format {
	case "json", "j":
		return yqlib.ParseJSON(data)
	case "props", "p":
		return yqlib.ParseProps(data)
	case "csv", "c":
		return yqlib.ParseCSV(data, false)
	case "tsv", "t":
		return yqlib.ParseCSV(data, true)
	case "xml", "x":
		return yqlib.ParseXML(data, false, false, false)
	}
	return yqlib.ParseYAML(data, "", "")
}
