func (p *printer) printOne(n *CandidateNode, index int, filename string) (string, error) {
	if n == nil {
		return "", nil
	}
	switch p.opts.outputFormat {
	case "json", "j":
		if p.opts.indent <= 0 {
			return EncodeJSON(n, 0)
		}
		return EncodeJSON(n, p.opts.indent)
	case "props", "p":
		return encodeProps(n, p.opts), nil
	case "csv", "c":
		return encodeCSV(n, p.opts, false)
	case "tsv", "t":
		return encodeCSV(n, p.opts, true)
	case "xml", "x":
		return encodeXML(n, p.opts), nil
	case "shell", "s":
		return encodeShell(n, p.opts), nil
	case "lua", "l":
		return encodeLua(n, p.opts), nil
	case "ini", "i":
		return encodeINI(n, p.opts), nil
	case "base64":
		return encodeBase64(n, p.opts), nil
	case "uri":
		return encodeURI(n, p.opts), nil
	case "toml":
		return encodeTOML(n, p.opts), nil
	case "hcl", "h":
		return encodeHCL(n, p.opts), nil
	case "kyaml", "ky":
		return encodeKyaml(n, p.opts)
	}
	return p.encodeYAML(n)
}
