package cmd

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/mikefarah/yq/v4/pkg/yqlib"
)

func evaluateAll(evalAll bool, expression string, files []string, inputFormat string, outputFormat string, opts *yqlib.PrinterOptions, hasStdin bool) int {
	// tokenize the expression
	var exprNode *yqlib.ExpressionNode
	if strings.TrimSpace(expression) != "" {
		toks, err := yqlib.Tokenize(expression)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Error: "+err.Error())
			return 1
		}
		node, err := yqlib.ParseExpression(toks)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Error: "+yqlib.ParseErrorMessage(err))
			return 1
		}
		exprNode = node
	}
	// gather documents
	var docs []*CandidateWrapper
	if !optsInNullInput(opts) {
		if len(files) == 0 {
			data, err := readStdin()
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error: "+err.Error())
				return 1
			}
			ifmt := inputFormat
			if ifmt == "auto" {
				ifmt = detectFormatFromContent(data)
			}
			nodes, err := parseInput(data, ifmt)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error: bad file '-': "+err.Error())
				return 1
			}
			for i, n := range nodes {
				docs = append(docs, &CandidateWrapper{node: n, filename: "-", fileIndex: 0, docIndex: i, format: ifmt})
			}
		} else {
			for fi, f := range files {
				data, err := os.ReadFile(f)
				if err != nil {
					fmt.Fprintln(os.Stderr, "Error: "+err.Error())
					return 1
				}
				ifmt := inputFormat
				if ifmt == "auto" {
					ifmt = detectFormatFromFilename(f)
					if ifmt == "" {
						ifmt = detectFormatFromContent(data)
					}
				}
				nodes, err := parseInput(data, ifmt)
				if err != nil {
					fmt.Fprintln(os.Stderr, "Error: bad file '"+f+"': "+err.Error())
					return 1
				}
				for i, n := range nodes {
					docs = append(docs, &CandidateWrapper{node: n, filename: f, fileIndex: fi, docIndex: i, format: ifmt})
				}
			}
		}
	}
	if len(docs) == 0 {
		docs = append(docs, &CandidateWrapper{node: yqlib.NewNullDocument(), filename: "-", fileIndex: 0, docIndex: 0, format: "yaml"})
	}
	var results []*yqlib.CandidateNode
	if evalAll {
		var nodes []*yqlib.CandidateNode
		for _, d := range docs {
			d.node.fileIndex = d.fileIndex
			d.node.filename = d.filename
			d.node.docIndexVal = d.docIndex
			nodes = append(nodes, d.node)
		}
		if len(nodes) == 1 {
			res, err := yqlib.EvaluateDoc(exprNode, nodes[0], nil)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error: "+err.Error())
				return 1
			}
			results = res
		} else {
			// evaluate against the first document with all as siblings? approximate
			var combined []*yqlib.CandidateNode
			for _, d := range docs {
				combined = append(combined, d.node)
			}
			res, err := yqlib.EvaluateDocs(exprNode, combined, nil)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error: "+err.Error())
				return 1
			}
			results = res
		}
	} else {
		for _, d := range docs {
			d.node.fileIndex = d.fileIndex
			d.node.filename = d.filename
			d.node.docIndexVal = d.docIndex
			res, err := yqlib.EvaluateDoc(exprNode, d.node, nil)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error: "+err.Error())
				return 1
			}
			for _, r := range res {
				r.fileIndex = d.fileIndex
				r.filename = d.filename
				r.docIndexVal = d.docIndex
				r.format = d.format
				r.SourceFilename = d.filename
				r.SourceFileIndex = d.fileIndex
				r.SourceFormat = d.format
				results = append(results, r)
			}
		}
	}
	// print
	out := ""
	for i, r := range results {
		rfmt := r.SourceFormat
		if rfmt == "" {
			rfmt = inputFormat
		}
		if rfmt == "auto" {
			rfmt = "yaml"
		}
		ropts := *opts
		if opts.OutputFormat == "auto" {
			ropts.OutputFormat = rfmt
			if inputFormat != "auto" {
				ropts.OutputFormat = "yaml"
			}
		}
		s, err := yqlib.PrintOne(r, &ropts, i, r.SourceFilename)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Error: "+err.Error())
			return 1
		}
		if i > 0 && !opts.NoDoc {
			out += "---\n"
		}
		out += s
		if !opts.NulOutput && !strings.HasSuffix(out, "\n") {
			out += "\n"
		}
	}
	if opts.NulOutput {
		out = strings.TrimSuffix(out, "\n")
		for i := range results {
			_ = i
		}
	}
	fmt.Fprint(os.Stdout, out)
	if opts.ExitStatus {
		for _, r := range results {
			if r == nil {
				continue
			}
			if r.Tag == "!!null" || (r.Tag == "!!bool" && r.Value == "false") {
				return 1
			}
		}
		if len(results) == 0 {
			return 1
		}
	}
	return 0
}

func optsInNullInput(opts *yqlib.PrinterOptions) bool {
	return opts == nil
}

type CandidateWrapper struct {
	node     *yqlib.CandidateNode
	filename string
	fileIndex int
	docIndex int
	format   string
}

var _ = strconv.Itoa
