// EvaluateDoc evaluates an expression against a single document
func EvaluateDoc(expr *ExpressionNode, input *CandidateNode, vars map[string]*CandidateNode) ([]*CandidateNode, error) {
	if expr == nil {
		return []*CandidateNode{input}, nil
	}
	return evaluateExpression(expr, input, vars)
}

// EvaluateDocs evaluates an expression against a list of documents (eval-all)
func EvaluateDocs(expr *ExpressionNode, docs []*CandidateNode, vars map[string]*CandidateNode) ([]*CandidateNode, error) {
	if expr == nil {
		return docs, nil
	}
	return evaluateExpression(expr, docs[0], vars)
}

