func (p *yamlParser) skipToLineEnd() {
	for !p.atEOF() && p.peek() != '\\n' {
		p.advance()
	}
	if !p.atEOF() {
		p.advance()
	}
}

// nextContentLine positions the parser at the next content line, collecting comments.
// returns (comments, indent). indent -1 means EOF, -2 means document separator.
func (p *yamlParser) nextContentLine() ([]string, int) {
	var comments []string
	for {
		if p.atEOF() {
			return comments, -1
		}
		if p.peek() != '\\n' && p.col != 1 {
			p.skipToLineEnd()
			continue
		}
		if p.peek() == '\\n' {
			p.advance()
			continue
		}
		ind := 0
		for !p.atEOF() && p.peek() == ' ' {
			p.advance()
			ind++
		}
		if p.atEOF() {
			return comments, -1
		}
		if p.peek() == '\\n' {
			continue
		}
		if p.peek() == '#' {
			comments = append(comments, p.readCommentText())
			continue
		}
		if isDocSep(p.peek3()) {
			return comments, -2
		}
		return comments, ind
	}
}

// parseBlockMap parses a block mapping; key is the first key already parsed.
func (p *yamlParser) parseBlockMap(indent int, firstKey *CandidateNode) (*CandidateNode, error) {
	m := NewMap("!!map")
	curKey := firstKey
	for {
		p.advance() // ':'
		p.skipSpaces()
		var val *CandidateNode
		var err error
		if p.atEOF() || p.peek() == '\\n' || p.peek() == '#' {
			if !p.atEOF() && p.peek() == '#' {
				lineC := p.readCommentText()
				if curKey != nil {
					curKey.LineComment = lineC
				}
			}
			if p.atEOF() {
				val = NewScalar("!!null", "null", ZeroStyle)
			} else {
				p.skipToLineEnd()
				comments, ni := p.nextContentLine()
				if ni > indent {
					val, err = p.parseBlockNode(ni)
					if err != nil {
						return nil, err
					}
					if val == nil {
						val = NewScalar("!!null", "null", ZeroStyle)
					}
					if len(comments) > 0 {
						val.HeadComment = joinComments(comments)
					}
				} else {
					val = NewScalar("!!null", "null", ZeroStyle)
					// position must be restored for subsequent entries
					if ni == -1 || ni == -2 {
						// nothing
					}
				}
			}
		} else {
			nxtIndent := p.col - 1
			val, err = p.parseValue(nxtIndent, true)
			if err != nil {
				return nil, err
			}
			if val == nil {
				val = NewScalar("!!null", "null", ZeroStyle)
			}
		}
		val.Key = curKey
		val.Parent = m
		m.Content = append(m.Content, val)
		// next entry?
		comments, ni := p.nextContentLine()
		if ni < 0 {
			break
		}
		if ni != indent {
			return nil, yamlErr(fmt.Sprintf("yaml: line %d: could not find expected ':'", p.line))
		}
		k, isK, err := p.tryParseKey(indent)
		if err != nil {
			return nil, err
		}
		if !isK {
			return nil, yamlErr(fmt.Sprintf("yaml: line %d: could not find expected ':'", p.line))
		}
		if len(comments) > 0 {
			k.HeadComment = joinComments(comments)
		}
		curKey = k
	}
	return m, nil
}

// parseBlockSeq parses a block sequence
func (p *yamlParser) parseBlockSeq(indent int) (*CandidateNode, error) {
	seq := NewSeq("!!seq")
	for {
		p.advance() // '-'
		p.skipSpaces()
		var child *CandidateNode
		var err error
		if p.atEOF() || p.peek() == '\\n' || p.peek() == '#' {
			var lineC string
			if !p.atEOF() && p.peek() == '#' {
				lineC = p.readCommentText()
			}
			if p.atEOF() {
				child = NewScalar("!!null", "null", ZeroStyle)
			} else {
				p.skipToLineEnd()
				comments, ni := p.nextContentLine()
				if ni > indent {
					child, err = p.parseBlockNode(ni)
					if err != nil {
						return nil, err
					}
					if child == nil {
						child = NewScalar("!!null", "null", ZeroStyle)
					}
					if len(comments) > 0 {
						child.HeadComment = joinComments(comments)
					}
				} else {
					child = NewScalar("!!null", "null", ZeroStyle)
				}
			}
			if lineC != "" {
				child.LineComment = lineC
			}
		} else {
			child, err = p.parseBlockNode(p.col - 1)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = NewScalar("!!null", "null", ZeroStyle)
			}
		}
		seq.Content = append(seq.Content, child)
		comments, ni := p.nextContentLine()
		if ni < 0 {
			break
		}
		if ni != indent || p.peek() != '-' || !seqStart(p) {
			break
		}
		if len(comments) > 0 {
			// comments between entries: attach as head comment of the next child
		}
	}
	return seq, nil
}

