{"command": "cd /workspace && python3 - <<'PY'
p='cmd/evaluate.go'
s=open(p).read()
start=s.index('	// print\n')
end=s.index('func resetStyles(')
new='''	// print: build per-file outputs so that in-place writes are possible
	byFile := map[int]*strings.Builder{}
	var order []int
	prevDocIndex := -1
	prevFileIndex := -1
	for _, r := range results {
		if _, ok := byFile[r.SourceFileIndex]; !ok {
			byFile[r.SourceFileIndex] = &strings.Builder{}
			order = append(order, r.SourceFileIndex)
		}
		b := byFile[r.SourceFileIndex]
		if b.Len() > 0 && (prevFileIndex != r.SourceFileIndex || prevDocIndex != r.DocIndexVal) && !opts.NoDoc {
			b.WriteString("---\\n")
		}
		prevDocIndex = r.DocIndexVal
		prevFileIndex = r.SourceFileIndex
		rfmt := r.SourceFormat
		if rfmt == "" {
			rfmt = inputFormat
		}
		if rfmt == "auto" {
			rfmt = "yaml"
		}
		ropts := *opts
		if opts.OutputFormat == "auto" {
			ropts.OutputFormat = rfmt
			if inputFormat != "auto" {
				ropts.OutputFormat = "yaml"
			}
		}
		s, err := yqlib.PrintOne(r, &ropts, 0, r.SourceFilename)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Error: "+err.Error())
			return 1
		}
		b.WriteString(s)
		if !opts.NulOutput && !strings.HasSuffix(s, "\\n") {
			b.WriteString("\\n")
		}
	}
	var out string
	if opts.Inplace && len(files) > 0 {
		for _, fi := range order {
			fname := files[fi]
			perm := os.FileMode(0644)
			if st, err := os.Stat(fname); err == nil {
				perm = st.Mode().Perm()
			}
			if err := os.WriteFile(fname, []byte(byFile[fi].String()), perm); err != nil {
				fmt.Fprintln(os.Stderr, "Error: "+err.Error())
				return 1
			}
		}
	} else {
		for _, fi := range order {
			out += byFile[fi].String()
		}
		fmt.Fprint(os.Stdout, out)
	}
	if opts.ExitStatus {
		for _, r := range results {
			if r == nil {
				continue
			}
			if r.Tag == "!!null" || (r.Tag == "!!bool" && r.Value == "false") {
				return 1
			}
		}
		if len(results) == 0 {
			return 1
		}
	}
	return 0
}

'''
s = s[:start] + new + s[end:]
open(p,'w').write(s)
